"""Procedural Rokugan maps -> RPG-Cobo .bw files (built in-engine by plugin/rokugan/RokuganMapGen.sk).

Python designs each map as a column grid (block id + top height per cell) plus objects (trees/rocks = free blocks,
prefab buildings = map assets, extra blocks), writes tmp/rt_mapgen/<id>_cells.png + job.json, registers the map in
data/map.json (cloned from M001, events cleared), then runs rpgcobo.exe -testplay once; the plugin builds every
.bw and quits. Run after gen_data.py, before gen_render.py:  python -E tools/gen_maps.py [mapid ...]

Block ids (page | index << 5): page 2 = natural terrain (index = wall*12 + 1 + floor; wall 0..5 = dirt1/1/2/2/3/3,
floor 0..10 = grass1, grass2, grass3, sand1, grass2, sand1, sand2, sand1, snow1, sand1, grass1; floor index 0 =
bare dirt wall), page 3 = struct walls (46 variants), page 8 = water, page 11 = plants/flowers.
Free blocks: fbtype 20 = trees & rocks (fbparam 0 tree L, 1 tree M, 3 tree S, 17-19 rocks).
"""
import copy
import json
import re
import os
import subprocess
import sys

import numpy as np
from PIL import Image

HERE = os.path.dirname(os.path.abspath(__file__))
TOOL = os.path.normpath(os.path.join(HERE, "..", "_tools", "rpgcobo-tool"))
PROJ = os.path.join(TOOL, "project")
JOBDIR = os.path.join(TOOL, "tmp", "rt_mapgen")
PAD_X, PAD_TOP, PAD_BOTTOM = 26, 12, 4


def T(wall, floor=None):
    """Natural terrain block: wall 0-5, floor 0-10 (None = bare dirt wall)."""
    return 2 | ((wall * 12 + (0 if floor is None else 1 + floor)) << 5)


GRASS, GRASS2, GRASS3, ROAD, SAND, SNOW, DIRT = T(0, 0), T(0, 1), T(2, 2), T(0, 5), T(0, 6), T(4, 8), T(0)
STONE = 3 | (9 << 5)          # struct0 #9 stone3
WATER = 8 | (0 << 5)
FLOWER_R, FLOWER_W, TUFT = 11 | (0 << 5), 11 | (1 << 5), 11 | (2 << 5)
TREE_L, TREE_M, TREE_S, ROCK_S, ROCK_M = 0, 1, 3, 17, 18


class MapSpec:
    def __init__(self, mid, name, w, d, base=GRASS, y=2):
        self.mid, self.name, self.w, self.d = mid, name, w, d
        self.blk = np.full((d, w), base, np.int32)
        self.hgt = np.full((d, w), y, np.int32)
        self.objs = []
        self.walls = []                 # extra invisible-wall cells [(x, z)] (water is walled automatically)

    def rect(self, x, z, w, d, blk=None, y=None):
        if blk is not None:
            self.blk[z:z + d, x:x + w] = blk
        if y is not None:
            self.hgt[z:z + d, x:x + w] = y

    def tree(self, x, z, kind=TREE_M, rot=0):
        self.objs.append({"t": "fb", "x": x, "y": int(self.hgt[z, x]) + 1, "z": z, "rot": rot, "fbtype": 20,
                          "fbparam": kind})

    def asset(self, aid, x, z, rot=0, y=None):
        self.objs.append({"t": "asset", "id": aid, "x": x, "y": int(self.hgt[z, x] if y is None else y) + 1, "z": z,
                          "rot": rot})

    def block(self, x, z, blk, dy=1):
        self.objs.append({"t": "blk", "x": x, "y": int(self.hgt[z, x]) + dy, "z": z, "blk": blk})

    def write(self):
        os.makedirs(JOBDIR, exist_ok=True)
        img = np.zeros((self.d, self.w, 4), np.uint8)
        img[..., 0] = self.blk & 0xFF
        img[..., 1] = (self.blk >> 8) & 0xFF
        img[..., 2] = np.clip(self.hgt, 0, 255)
        img[..., 3] = 255
        path = os.path.join(JOBDIR, "%s_cells.png" % self.mid)
        Image.fromarray(img, "RGBA").save(path)
        return {"id": self.mid, "cells": "tmp/rt_mapgen/%s_cells.png" % self.mid, "objs": self.objs, "hgt": 64,
                "out": "project/data/mapdata/%s.bw" % self.mid, "bed": SAND,
                "walls": [[int(x), int(z)] for x, z in self.walls]}


# ------------------------------------------------------------------------------------------- maps
def probe():
    m = MapSpec("M090", "Probe", 32, 32)
    m.rect(0, 14, 32, 4, ROAD)
    m.rect(4, 4, 6, 5, WATER, 1)
    m.rect(20, 3, 8, 6, STONE, 4)
    m.tree(24, 24, TREE_L)
    m.tree(6, 24, TREE_S)
    m.block(14, 24, FLOWER_R)
    m.asset("MA038", 16, 28)
    return m


def catalog():
    m = MapSpec("M091", "Asset catalog", 120, 40)
    for i, aid in enumerate(["MA003", "MA004", "MA006", "MA010", "MA035", "MA038", "MA040", "MA041", "MA027", "MA028"]):
        m.asset(aid, 8 + i * 11, 18)
    return m


def catalog2():
    """Parts catalog: struct0 walls (rows 1-2), roof free blocks (row 3), exterior free blocks (rows 4-5)."""
    m = MapSpec("M092", "Parts catalog", 100, 60)
    for i in range(46):
        x, z = 4 + (i % 23) * 4, 6 + (i // 23) * 5
        m.objs.append({"t": "fill", "x": x, "y": 3, "z": z, "w": 2, "h": 3, "d": 2, "blk": 3 | (i << 5)})
    for i in range(21):
        m.objs.append({"t": "fb", "x": 4 + i * 4, "y": 3, "z": 20, "rot": 0, "fbtype": 50, "fbparam": i})
    for i in range(35):
        m.objs.append({"t": "fb", "x": 4 + (i % 18) * 5, "y": 3, "z": 30 + (i // 18) * 7, "rot": 0, "fbtype": 3,
                       "fbparam": i})
    for i in range(14):
        m.objs.append({"t": "fb", "x": 4 + i * 6, "y": 3, "z": 46, "rot": 0, "fbtype": 30, "fbparam": i})
    for i in range(14):
        m.objs.append({"t": "fb", "x": 4 + i * 6, "y": 3, "z": 53, "rot": 0, "fbtype": 1, "fbparam": i})
    return m


# ------------------------------------------------------------------------------------------- Rokugan kit
def S(i):
    return 3 | (i << 5)


PLASTER, DARKWOOD, WOOD, PLANK, SHOJI = S(13), S(7), S(11), S(25), S(31)
KAIU, STONEW, ROOF, VOID, TORII = S(22), S(8), S(34), S(35), S(19)
DIRT3, SAND2 = T(4), T(0, 6)
LAMP_TORCH, LAMP_STREET, LAMP_BRACKET, LAMP_FIRE = 6, 5, 3, 2       # map_vox lamp: torch1, streetlamp2, bracket, torch2
MATTING = S(26)                                                          # tan woven struct block: straw mats
FENCE = 10 | (0 << 5)


def fill(m, x, y, z, w, h, d, blk):
    m.objs.append({"t": "fill", "x": int(x), "y": int(y), "z": int(z), "w": int(w), "h": int(h), "d": int(d),
                   "blk": int(blk)})


def fb(m, x, z, fbtype, fbparam, rot=0, y=None):
    m.objs.append({"t": "fb", "x": int(x), "y": int((m.hgt[z, x] if y is None else y) + 1), "z": int(z),
                   "rot": rot, "fbtype": fbtype, "fbparam": fbparam})


STOREY_EXTRA = 2


def building(m, x, z, w, d, wall_h=4, door=True, roof=ROOF, wall=PLASTER, two_storey=False):
    """Rokugani house: stone footing, plaster walls on a dark-wood frame, doorway + shoji on the front (low-z
    side, facing the camera), stepped hip roof with a one-block eave.
    Scale (user: buildings didn't scale with the cast; 2 blocks = 1 m): every storey is 2 blocks taller than the
    wall_h asked for and the doorway is 4 blocks (2 m), so a doorway clears a head and walls stand ~1.8x the cast
    (Octopath's towns run tall)."""
    wall_h += STOREY_EXTRA
    y0 = int(m.hgt[z:z + d, x:x + w].max())
    fill(m, x, y0 + 1, z, w, 1, d, STONEW)                                   # footing
    fill(m, x, y0 + 2, z, w, wall_h, d, wall)
    top = y0 + 1 + wall_h
    for xx in list(range(x, x + w, 3)) + [x + w - 1]:                        # posts on front and back
        fill(m, xx, y0 + 2, z, 1, wall_h, 1, DARKWOOD)
        fill(m, xx, y0 + 2, z + d - 1, 1, wall_h, 1, DARKWOOD)
    for zz in (z, z + d - 1):
        fill(m, x, top, zz, w, 1, 1, DARKWOOD)                               # head beam
    fill(m, x, y0 + 2, z, 1, wall_h, d, DARKWOOD)
    fill(m, x + w - 1, y0 + 2, z, 1, wall_h, d, DARKWOOD)
    if door:
        cx = x + w // 2 - 1
        fill(m, cx, y0 + 2, z, 2, 4, 1, VOID)                                # doorway (2 m)
        for sx in range(x + 1, x + w - 1, 3):                                # shoji panels beside it
            if abs(sx - cx) > 2 and sx + 1 < x + w - 1:
                fill(m, sx, y0 + 3, z, 2, 3, 1, SHOJI)
    if two_storey:
        fill(m, x + 1, top + 1, z + 1, w - 2, 4, d - 2, wall)
        fill(m, x, top + 1, z, w, 1, d, ROOF)                                # skirt roof
        top += 4
        x, z, w, d = x + 1, z + 1, w - 2, d - 2
    # gabled roof (kirizuma): slopes front/back, ridge along x, eaves overhang on all sides
    step = 1 if d <= 6 else 2
    dd, zz, yy, k = d + 2, z - 1, top + 1, 0
    while dd > 2:
        fill(m, x - 1, yy, zz, w + 2, 1, dd, roof)
        zz, dd, yy, k = zz + step, dd - 2 * step, yy + 1, k + 1
    fill(m, x - 1, yy, zz, w + 2, 1, max(dd, 1), roof)
    fill(m, x - 2, yy + 1, zz, w + 4, 1, max(dd, 1), DARKWOOD)               # ridge beam with flared ends
    return y0


def torii(m, x, z, span=5, h=9):
    y0 = int(m.hgt[z, x])
    for px in (x, x + span):
        fill(m, px, y0 + 1, z, 1, h, 1, TORII)
    fill(m, x, y0 + h - 1, z, span + 1, 1, 1, TORII)                         # nuki
    fill(m, x - 1, y0 + h + 1, z, span + 3, 1, 1, DARKWOOD)                  # kasagi
    fill(m, x - 1, y0 + h, z, span + 3, 1, 1, TORII)


def tent(m, x, z, w=6, d=5):
    """A ragged ronin tent: straw mats over a ridge pole (stepped A-frame, ridge along x), dark opening at the
    front (camera side)."""
    y0 = int(m.hgt[z:z + d, x:x + w].max())
    for k in range((d + 1) // 2):
        fill(m, x, y0 + 1 + k, z + k, w, 1, d - 2 * k, MATTING)
    fill(m, x + w // 2 - 1, y0 + 1, z, 2, 1, 1, VOID)                       # the way in
    fill(m, x - 1, y0 + 1 + (d - 1) // 2, z + (d - 1) // 2, 1, 1, 1, DARKWOOD)   # ridge pole ends
    fill(m, x + w, y0 + 1 + (d - 1) // 2, z + (d - 1) // 2, 1, 1, 1, DARKWOOD)


def shrine(m, x, z):
    building(m, x, z, 7, 5, wall_h=3, wall=WOOD)
    fb(m, x - 2, z + 1, 2, LAMP_STREET)
    fb(m, x + 8, z + 1, 2, LAMP_STREET)


def shrine_rites(ev, x, z, intro, meditate, extra=(), reqs=None):
    """The shrine's step (in front of a shrine(m, x, z)): Pray cleanses Taint (memory counters-known-and-available),
    Meditate restores MP. extra = more (label, cmds) choices."""
    ev.talk(x + 3, z - 1, "CE000", [(None, [
        narrate(intro),
        choices(("Pray. (Cleanse Taint)", [script("W = ::Rokugan.cleanseTaint();"),
                                           if_([{"lvar": "W", "op": ">=", "rvar": 1}],
                                               [narrate("The offering water clouds over, then clears. The Taint is "
                                                        "gone.")],
                                               [narrate("The water stays clear. There is nothing in you for it to "
                                                        "take.")])]),
                ("Meditate. (Restore MP)", [{"charaid": "P000", "cmd": "cmd_hpmp", "cmdtgt": 11, "hp1": True,
                                             "op": 1, "pid": "MP", "val": 100}, narrate(meditate + " (MP restored.)")]),
                *extra, ("Leave.", []))])], trigger=1, reqs=reqs)


def item_named(name):
    """An item id from the generated item.json by name (bestiary drops are numbered by gen_data in table order)."""
    it = json.load(open(os.path.join(PROJ, "data", "item.json"), encoding="utf-8"))
    found = next((k for k, v in it.items() if isinstance(v, dict) and v.get("name") == name), None)
    if found is None:                    # item.json mid-rebuild (gen_data failed half-way): a placeholder, fixed by the
        print("item_named: %r not in item.json yet (rebuild with regen.py --maps)" % name)    # next full build
        return "I100"
    return found


def kaiu_wall(m, z0, z1, top=16, crenel_z=None):
    m.rect(0, z0, m.w, z1 - z0, KAIU, top)
    if crenel_z is not None:
        for x in range(0, m.w, 4):
            fill(m, x, top + 1, crenel_z, 2, 2, 2, KAIU)


# ------------------------------------------------------------------------------------------- events
class Events:
    def __init__(self, m):
        self.m, self.ev, self.n = m, {}, 0

    def _add(self, e):
        self.n += 1
        e.setdefault("col", 0)
        e.setdefault("flags", 1)
        e.setdefault("spawndist", 1)
        e["name"] = "*%s-%d" % (e["role"], self.n)
        self.ev["#%d#" % self.n] = e
        return self.n

    def pos(self, x, z, d=2, dy=1):
        return [int(x), int(self.m.hgt[z, x]) + dy, int(z), d]

    def npc(self, x, z, mdl, msg, d=2, reqs=None):
        return self._add({"role": "villager", "mdlid": mdl, "msg": msg, "pos": self.pos(x, z, d),
                          "moveaction": "stop", "movespd": 4, "reqs0": reqs, "pop": None, "standani": None})

    def follower(self, x, z, mdl, msg, lead=None, gap=1.6, reqs=None):
        """Escort follower (plugin moveaction rt_follow): trails the player, or the event `lead` (an id from this
        map), `gap` metres behind; always spawned so it never strands."""
        return self._add({"role": "villager", "mdlid": mdl, "msg": msg, "pos": self.pos(x, z, 2),
                          "moveaction": "rt_follow", "movespd": 4, "spawndist": 5, "reqs0": reqs, "pop": None,
                          "standani": None, "lead": lead, "gap": gap})

    def portal(self, x, z, dest_map, dest_ev, d=2):
        return self._add({"role": "portal", "pos": self.pos(x, z, d), "back": False, "remap": True, "wipe": 2,
                          "dest": {"mapid": dest_map, "evid": dest_ev}, "mdl": {"r": [0, 1.0, 0, 1.0, 1.0, 0.5]}})

    def scene(self, x, z, flag, cmds, after=None, touch=False):
        """Autorun cutscene that plays once (guarded by global flag; optionally only after another flag)."""
        block = [{"cmd": "cmd_compute", "lvar": flag, "op": "=", "rvar": True}] + cmds
        page = {"ani": {"id": "stand"}, "trigger": 5 if touch else 6, "memo": "", "moveaction": "stop", "movespd": 4,
                "pararun": False, "reqs": None, "standani": None,
                "cmdblock": [{"cmd": "cmd_if", "reqs": [{"lvar": flag, "op": "==", "rvar": False}] +
                              (([{"lvar": after, "op": "==", "rvar": True}] if isinstance(after, str) else
                                list(after)) if after else []),
                              "cmdblocks": [block]}]}
        # (user 2026-11-12: the Egg Caves altar scene only fired on one tile) walk-on scenes: 3 m tall, so a sloping
        # floor still puts the whole body inside the box (the engine's walk-on rule)
        r = [0, 1.0, 0, 2.5, 3.0, 2.5] if touch else [0, 0.5, 0, 0.5, 0.5, 0.5]
        pages = [page]
        if not touch:
            # (tester 2026-11-11) The engine runs an autorun (trigger 6) once per spawn, the first time its page is
            # live - even when the cmd_if inside says "not yet". A scene whose "after" flag was set while the player
            # stood there never played until he left and came back (Scorpion Ch1's memorial garden has no way out:
            # stuck after the three conversations; Lion's Burned Bridge). Now an empty page waits until the guard
            # holds, and the scene's page carries the guard itself: when it becomes live, the scene runs.
            page["reqs"] = list(page["cmdblock"][0]["reqs"])
            pages = [{"ani": {"id": "stand"}, "trigger": 0, "memo": "", "moveaction": "stop", "movespd": 4,
                      "pararun": False, "reqs": None, "standani": None, "cmdblock": []}, page]
        return self._add({"role": "custom", "pos": self.pos(x, z), "mdl": {"r": r},
                          "mdlid": "CE000", "page": pages})

    def talk(self, x, z, mdl, pages, reqs=None, d=2, trigger=2):
        """NPC/object with talk pages: [(page reqs or None, cmds), ...]; the engine runs the LAST page whose reqs
        pass. trigger 2 = talk (Z), 1 = examine."""
        pg = [{"ani": {"id": "stand"}, "trigger": trigger, "memo": "", "moveaction": "stop", "movespd": 4,
               "pararun": False, "reqs": r, "standani": None, "cmdblock": c} for r, c in pages]
        e = {"role": "custom", "mdlid": mdl, "pos": self.pos(x, z, d), "page": pg, "reqs0": reqs}
        if mdl == "CE000":
            # (user 2026-11-12: walk-on spots that needed one exact tile) a walk-on box is 3 m tall, so uneven ground
            # still puts the whole body inside it
            e["mdl"] = {"r": [0, 1.0, 0, 1.0, 3.0 if trigger == 5 else 1.0, 1.0]}
        return self._add(e)

    def clerk(self, x, z, mdl, storeid, d=2):
        return self._add({"role": "clerk", "mdlid": mdl, "storeid": storeid, "sell": True, "pos": self.pos(x, z, d),
                          "moveaction": "stop", "reqs0": None, "standani": None})

    def inn(self, x, z, mdl, price, d=2):
        n = self._add({"role": "hotel", "mdlid": mdl, "price": price, "pos": self.pos(x, z, d),
                       "moveaction": "stop", "reqs0": None})
        self.inns = getattr(self, "inns", []) + [(x, z, n, d)]              # Togashi Yosai waits beside every inn
        return n

    def prop(self, x, z, mdl, msg=None, d=1, reqs=None):
        e = {"role": "villager", "mdlid": mdl, "pos": self.pos(x, z, d), "moveaction": "stop", "movespd": 0,
             "reqs0": reqs, "pop": None, "standani": None, "msg": msg or ""}
        if not msg:
            # Nothing to say: not a villager (that role always talks, so Z by a bottle or a candle opened an empty
            # message box: the story player stuck on one in the Hoshi-no-Ichi inn, 2026-11-10). A custom event with
            # no trigger shows the same model and blocks the same way.
            e = {"role": "custom", "mdlid": mdl, "pos": self.pos(x, z, d), "reqs0": reqs, "col": 0, "flags": 1,
                 "spawndist": 1,
                 "page": [{"ani": {"id": "stand"}, "trigger": 0, "memo": "prop", "moveaction": "stop", "movespd": 0,
                           "pararun": False, "reqs": None, "standani": None, "cmdblock": []}]}
        return self._add(e)

    def light(self, x, z, col=0xFFFFB060, lr=5.0, dy=2):
        """An invisible warm point light (event role "light"; colour ARGB, signed like the rest of map.json)."""
        c = col - (1 << 32) if col & 0x80000000 else col
        return self._add({"role": "light", "mdlid": "CE000", "pos": self.pos(x, z, 2, dy=dy), "spawndist": 5,
                          "reqs0": None, "lcol": c, "lr": lr, "lhpb": [180, -50], "lspot": [174, 4], "flicker": 0})

    def campfire(self, x, z):
        """Animated campfire sprite (gen_props EP355) + its glow."""
        self.prop(x, z, "EP355", msg="A thin fire. Bark smoke.", d=0)
        return self.light(x, z)

    def chest(self, x, z, item, num=1):
        return self._add({"role": "itemchest", "itemid": item, "num": num, "mdlid": "CV036", "pos": self.pos(x, z)})


def flag(f, v=True):
    return {"lvar": f, "op": "==", "rvar": v}


ESCORT = [flag("G011"), flag("G012", False)]          # S02 done, cart not yet in Hoshi-no-Ichi


def setf(f, v=True, op="="):
    return {"cmd": "cmd_compute", "lvar": f, "op": op, "rvar": v}


def if_(reqs, then, otherwise=None):
    return {"cmd": "cmd_if", "reqs": reqs, "cmdblocks": [then] + ([otherwise] if otherwise is not None else [])}


def choices(*opts):
    """opts: (label, cmds) ... -> one cmd_choices."""
    longest = max(len(re.sub(r"\$\{[^}]*\}", "x" * 24, o[0])) for o in opts)    # (templates: ~24 chars shown)
    w = max(420, min(1200, longest * 11 + 70))                 # the stock box clipped labels past ~34 chars: stretch
    c = {"cmd": "cmd_choices", "backenable": False, "cmdblocks": [o[1] for o in opts],     # it to the longest label
         "pos": {"left": (1280 - w) // 2, "right": (1280 - w) // 2, "y": 380}}       # (screen 1280 wide)
    for i, o in enumerate(opts):
        c["text%d" % i] = o[0]
    return c


def script(code):
    return {"cmd": "cmd_script", "desc": "SCRIPT", "code": code}


