def road_coast(mid="M102", night=False):
    m = MapSpec(mid, "Coast Road" + (" (night)" if night else ""), 140, 44, base=GRASS, y=3)
    m.rect(0, 0, 140, 10, WATER, 1)
    m.rect(0, 10, 140, 6, SAND, 2)
    m.rect(0, 16, 140, 5, ROAD, 3)
    for x in range(0, 140):                                                  # cliffs, rising and broken
        hh = 9 + int(3 * np.sin(x * 0.11) + 2 * np.sin(x * 0.37))
        m.rect(x, 28, 1, 16, T(2, 0), hh)
        m.rect(x, 26, 1, 2, T(2, 1), max(4, hh - 4))
    for tx, tz in ((20, 12), (21, 13), (75, 11), (76, 12), (77, 11)):        # tidepools
        m.rect(tx, tz, 2, 1, WATER, 1)
    for x in range(6, 136, 9):
        m.tree(x, 35 + (x * 7) % 6, (TREE_L, TREE_M, TREE_S)[x % 3])
    for x in range(12, 136, 17):
        m.tree(x, 23, TREE_S)
        m.tree(x + 5, 12, ROCK_S)
    fb(m, CAVE[0], CAVE[1], 3, 21)                                           # the Egg Caves mouth (dungeon1 entrance1)
    fb(m, 4, 21, 2, LAMP_STREET)
    ev = Events(m)
    if night:
        return m, follow_walk(m, ev)
    ev.portal(1, 18, "M101", 2, d=1)
    ev.portal(138, 18, "M103", 1, d=3)
    ev.chest(40, 22, "I001", 2)
    ev.chest(30, 11, "I018", 2)
    ev.chest(96, 12, "N000", 80)
    if not night:
        coast_extras(m, ev)
    drv = ev.follower(3, 18, EP_SERVICE["cartdriver"], "Keep the goblins off the rice, Hiruma-sama, and I'll keep the "
                      "radish off you.", gap=1.4, reqs=ESCORT)
    ev.follower(3, 18, EP_SERVICE["cart"], "Rice, salt fish and one barrel of pickled radish.", lead=drv, gap=1.3,
                reqs=ESCORT)
    ev.talk(CAVE[0] + 2, CAVE[1] - 2, "CE000", [
        (None, [narrate("A cave mouth in the cliff. It stinks of rotten eggs."),
                say("Natsuko", "Not my business. I'm on leave.")]),
        ([flag("G024")], cave_enter())], trigger=1)
    ev.scene(CAVE[0] + 2, CAVE[1] - 6, "G051", [if_([flag("G048")], S09_DAWN)] + S09_NEZUMI +
             got("A104", "Squeak's Charm") + [narrate("Objective: Hoshi-no-Ichi. Someone is waiting at the tea "
                                                      "house.")], after="G049")
    return m, ev


