def _prompts():
    """FOLLOW-WALK prompt lines P1-P3 from the production script."""
    txt = open(os.path.join(SCRIPT_DIR, "crab-ch1.md"), encoding="utf-8").read()
    return {k: _clean(v) for k, v in re.findall(r'- (P\d) \([^)]*\): "([^"]+)"', txt)}


