def yosai_inn(ev, x, z, mid):
    """Togashi Yosai beside an inn: the first meeting (in a path's Ch1 town), then an offer to travel whenever no
    other companion is in the party."""
    # (user 2026-11-12: Yosai stays with the party) he offers whenever there is room (fewer than 4)
    alone = script('local n = length( ::rpgstat.members.filter( @( v) v)); W = n < 4;')
    come = [{"cmd": "cmd_memberop", "playerid": "P132", "op": 0, "slot": -1},
            script('local p = ::rpgstat.playermap["P132"], n = ::rpgstat.members.find( @( v) v && v != p); '
                   'if( n && p.LV < n.LV) p.setLV( n.LV);'),
            setf("G608"), narrate("Togashi Yosai joins the party. (Dragon's Breath, Arrowroot; his tattoos heal him a "
                                  "little every turn.)")]
    ask = [alone, if_([flag("W")], [choices(("Travel with me.", [say("Yosai", "Excellent. If I die, tell them I was "
                                                                              "taller.")] + come),
                                            ("Not now.", [say("Yosai", "I'll be here. Probably. Statistically.")]))],
                      [say("Yosai", "You've already got company. I'll keep the bench warm. Benches love me.")])]
    meet = [say("Yosai", "A traveler! Togashi Yosai. I hunt men who skin monks, and the Fortunes hunt me. We're all "
                         "very busy."),
            say("Yosai", "I've got tattoos that breathe fire and tattoos that steal wounds, and none of them do my "
                         "taxes."),
            say("Yosai", "Somewhere a woman is writing two letters at once. Nobody ever reads the second one. Strange "
                         "times."),
            setf("G607")] + ask
    first = [(None, meet)] if mid in YOSAI_MEET else [(None, [])]
    line = YOSAI_SAYS.get(mid, YOSAI_ANY[sum(map(ord, mid)) % len(YOSAI_ANY)])
    return ev.talk(x, z, SC["yosai"], first + [([flag("G607")], [say("Yosai", line)] + ask)],
            reqs=([flag("G608", False)] if mid in YOSAI_MEET else [flag("G607"), flag("G608", False),
                                                                   flag("G759", False)]))


