ROOM_DIMS = {"M229": (40, 14), "M230": (30, 12), "M231": (44, 16), "M232": (44, 16), "M233": (40, 16),
             "M234": (30, 12), "M218": (30, 12), "M217": (30, 12), "M219": (38, 15), "M206": (38, 15), "M207": (38, 14), "M208": (30, 12), "M142": (40, 14), "M143": (38, 14), "M144": (38, 14), "M145": (38, 14), "M146": (38, 15),
             "M154": (38, 14), "M155": (38, 14), "M156": (38, 14),
             "M305": (28, 10), "M306": (20, 8), "M308": (20, 8), "M313": (20, 8), "M316": (18, 7), "M317": (16, 7),
             "M324": (20, 8), "M327": (16, 6), "M328": (16, 6), "M329": (24, 8), "M330": (24, 8), "M331": (24, 8),
             "M332": (24, 8), "M339": (16, 6), "M342": (20, 8), "M344": (24, 8)}


def world(mid, x, z, d=0.0, padded=True):
    """mapmove destination position (world units) for block x, z (castle floors: their embed offset)."""
    if padded:
        return [(x + PAD_X) / 2.0, None, (z + PAD_BOTTOM) / 2.0, d]
    w, dd = ROOM_DIMS.get(mid, (0, 0))
    W, D = w + 2, dd + 3
    ox, oz = (max(32, W + 8) - W) // 2, (max(32, D + 8) - D) // 2
    return [(x + ox) / 2.0, None, (z + oz) / 2.0, d]


def go(mid, x, z, padded=True, wipe=1):
    return {"cmd": "cmd_mapmove", "dest": {"mapid": mid, "pos": world(mid, x, z, 0.0, padded)}, "wipe": wipe,
            "remap": True}


# ---- R hida_wall_road
def hida_road():
    m = MapSpec("M140", "Hida road", 120, 44, base=SNOW, y=3)
    for x in range(120):                                                   # foothills in front, rising
        m.rect(x, 0, 1, 8, SNOW, 3 + (2 if (x // 9) % 2 else 1))
    m.rect(0, 12, 120, 6, ROAD, 3)
    m.rect(0, 30, 120, 14, KAIU, 16)                                       # the Wall, always on the left
    for x in range(0, 120, 4):
        fill(m, x, 17, 41, 2, 2, 2, KAIU)
    for i, zz in enumerate(range(22, 30)):                                 # a half-collapsed Wall-stair
        m.rect(98, zz, 4, 1, STONEW, 4 + i * 2)
    rng = np.random.default_rng(140)
    for _ in range(90):                                                    # winter: dead grass showing through
        x, z = int(rng.integers(0, 120)), int(rng.integers(0, 30))
        if not (12 <= z < 18):
            m.rect(x, z, int(rng.integers(1, 4)), 1, GRASS3)
    for x in range(6, 116, 11):
        m.tree(x, 25 + (x * 3) % 4, (TREE_M, TREE_S)[x % 2])
        m.tree(x + 4, 4, (TREE_L, TREE_M)[x % 2])
    shrine(m, 52, 22)
    ev = Events(m)
    # (user: "going left you should keep going left") the garrison's west edge leads onto the road's EAST end; the
    # road's west end leads into Kyuden Hida's east side
    ev.portal(118, 15, "M101", DOOR_EV[("M101", "hidaroad")], d=3)
    kh_west = ev.portal(1, 15, "M141", 1, d=1)                              # winter town, until Crab Ch4 ends
    ev.ev["#%d#" % kh_west]["reqs0"] = [flag("G286", False)]
    kh_sum = ev.portal(1, 15, "M151", 1, d=1)                               # then the summer town (a portal: a
    ev.ev["#%d#" % kh_sum]["reqs0"] = [flag("G286")]                         # walk-on event at the edge never fired)
    p = list(go("M151", 105, 32)["dest"]["pos"])
    p[1] = None                                                             # (land on the ground there)
    ev.ev["#%d#" % kh_sum]["dest"] = {"mapid": "M151", "pos": p}
    ev.talk(113, 19, "CE000", [(None, [narrate("A road-stone: \"Kyuden Hida, two days. Danger 18-25.\"")])],
            trigger=1)
    ev.chest(86, 20, "I101", 2)
    ev.chest(100, 32, "A108", 1)                                           # up the Wall-stair
    shrine_rites(ev, 52, 22, "A waystation shrine on the Hida road. Travellers leave rice balls and chips of jade.",
                 "Natsuko kneels in the snow and listens to the Wall creak in the cold.")   # storyboard: + Taint cleanse
    return m, ev


