# ---- the castle (vertical hub)
def castle_floor(mid, name, w, d, layout, up=None, down=None, wall=PLASTER, extra=None):
    """A cut-away castle floor like interior() (tatami, plaster, dark wood): event 1 = the way down (the front door
    on 1F), event 2 = the way up (a stair at the back right). up / down = (map, event id)."""
    W, D = w + 2, d + 3
    m = MapSpec(mid, name, W, D, base=DARKWOOD, y=0)
    m.rect(1, 1, w, d + 1, PLANK, 1)
    fill(m, 0, 2, D - 1, W, 5, 1, wall)
    fill(m, 0, 2, 0, 1, 5, D, wall)
    fill(m, W - 1, 2, 0, 1, 5, D, wall)
    for x in range(0, W, 4):
        fill(m, x, 2, D - 1, 1, 5, 1, DARKWOOD)
    fill(m, 0, 7, D - 1, W, 1, 1, DARKWOOD)
    for z in range(0, D, 4):
        fill(m, 0, 2, z, 1, 5, 1, DARKWOOD)
        fill(m, W - 1, 2, z, 1, 5, 1, DARKWOOD)
    for x in range(3, W - 3, 5):
        fill(m, x, 3, D - 1, 3, 3, 1, SHOJI)
    fill(m, 1, 2, 0, W - 2, 1, 1, DARKWOOD)                                # front sill
    decor = []
    keep = set()                                                            # the stair cells and the step in front of
    if down:                                                                # each: nothing stands there (a candle on
        sx, sz = (2, 2) if mid != "M142" else (W // 2, 1)                   # the down-stair trapped the user)
        keep |= {(sx, sz), (sx, sz + 1)}
    if up:
        keep |= {(W - 4, D - 5), (W - 4, D - 6)}
    for it in layout:
        kind, x, z = it[0], it[1], it[2]
        if kind not in ("tatami", "futon", "dais", "screen") and (x, z) in keep:
            x += 2 if x + 2 < W - 1 else -2                                 # nudge it aside
        if kind in ("tatami", "futon"):
            fill(m, x, 2, z, 2 if kind == "futon" else 3, 1, 3 if kind == "futon" else 2,
                 FUTON if kind == "futon" else TATAMI)
        elif kind in DECOR_EP:
            decor.append((kind, x, z, None))
        elif kind == "hearth":
            furnish(m, kind, x, z, 0, 1)
        elif kind == "pillar":
            fill(m, x, 2, z, 1, 5, 1, DARKWOOD)
        elif kind == "screen":
            fill(m, x, 2, z, it[3], 3, 1, SHOJI)
        elif kind == "dais":
            fill(m, x, 2, z, it[3], 1, it[4], TATAMI)
        elif furnish(m, kind, x, z, it[3] if len(it) > 3 else 0, 1):
            pass
        else:
            fb(m, x, z, 4, IN[kind], y=1)
    for i in range(3 if up else 0):                                        # the stair up, back right (user: Lion
        fill(m, W - 5, 2 + i, D - 4 + i, 3, 1, 1, DARKWOOD)                # rooms showed stairs that led nowhere)
    ev = Events(m)
    if down:
        ev.portal(2 if mid != "M142" else W // 2, 2 if mid != "M142" else 1, down[0], down[1], d=2)
    if up:
        ev.portal(W - 4, D - 5, up[0], up[1], d=0)                      # at the foot of the stair: walk into it
    else:
        ev.prop(W - 4, D - 5, "CE000")
    if extra:
        extra(m, ev)
    place_decor(ev, decor)
    ROOM_OFS[mid] = embed(m, ev)
    return m, ev


