SS_TEAM = [
    narrate("The garrison yard. Isawa Michio has a table out in the cold, covered in papers, and six people around "
            "it who have never all stood in one place before."),
    say("Isawa Michio", "A year. A year we've hunted \"the Kyuden Hida poisoner\". Look."),
    narrate("Ide Fujio's forged letters. Yogo Mai's sabotaged traps, and the goblin who wouldn't talk about them. A "
            "bride at Kage's wedding, with very blue eyes."),
    say("Isawa Michio", "The woman who forged Fujio's letters. Who paid for the traps. Who sat at Kage's wedding."),
    say("Natsuko", "Doji Nashiko."),
    say("Isawa Michio", "Then the Inquisitors would like to be present when you find her."),
    say("Isawa Michio", "We start with what she left behind. A nest, under the Wall, where the old trap tunnels go "
                        "deep. Mai's goblin finally drew us a map."),
    choices(("Go down with Michio and Goro.",
             join("P124", "Isawa Michio", [], lv=46) + join("P123", "Hiruma Goro", [], lv=46) + [
                 narrate("Under the Wall. Takeo and Sakura hold the tunnel mouth; Fujio and Mai hold the lanterns. "
                         "The nest is a cave of bones and silk, and it is not empty."),
                 say("Hiruma Goro", "Smells like somebody's been feeding it."),
                 say("Isawa Michio", "Somebody has. Kill it, Hiruma. I'll write the report."),
                 dict(battle("M001", 170), losefunc=1),
                 leave("P123"), leave("P124"),
                 if_([WON], [
                     narrate("The nest burns. Michio stands over it until the last of the silk is ash."),
                     say("Isawa Michio", "One thing she made, unmade. Write that down, somebody. I want it in the "
                                         "record."),
                     say("Yogo Mai", "(writing) \"One thing unmade.\""),
                     say("Isawa Michio", "When you find her, Hiruma - send word. The Inquisitors will come."),
                     narrate("(The Inquisitors' Last Hunt - complete. Michio's team will be there at the end.)"),
                     setf("G1213")] + got("I130", "Jade Pouch", 3),
                     [say("Isawa Michio", "(hauling Natsuko up) Retreat is a tactic. So is coming back. Again?")])]),
            ("Not now.", [say("Isawa Michio", "We'll wait. We've waited a year. I'm told I'm very bad at it.")]))]


def ss_team(ev):
    """M101 yard: Michio (with a side-story "?") and the four Kyuden Hida guests, after Crab Ch4 with all six met."""
    met = [flag("G286"), flag("G233"), flag("G234"), flag("G235"), flag("G236")]
    ev.talk(40, 25, SCI["michio"], [(None, SS_TEAM)], reqs=met + [flag("G1213", False)])
    for x, z, k in ((43, 24, "takeo"), (43, 26, "mai"), (45, 24, "fujio"), (45, 26, "sakura")):
        ev.prop(x, z, SC[k], d=1, reqs=met + [flag("G1213", False)])
    ev.npc(40, 25, SC["michio"], "The nest is ash. I'm keeping the report. It's the first one I've enjoyed writing.",
           reqs=[flag("G1213")])


def goro_ss2(ev):
    """M101: Goro at the barracks with a side-story "?" (after Ch3; hidden while Ch4 runs), plain after."""
    for reqs in ([flag("G255"), flag("G270", False), flag("G292", False)], [flag("G286"), flag("G292", False)]):
        ev.talk(28, 40, SCI["goro"], [(None, GORO_SS2)], reqs=reqs)
    ev.npc(28, 40, SC["goro"], "My brother's having a new sword made. I told him to ask for a bent one.",
           reqs=[flag("G292")])


