import math  # noqa: E402

# ------------------------------------------------------------------------------------------- Crab Ch3
# "Beyond the Wall" (production/crab-ch3.md, storyboards/crab-ch3.md). Flags G240-G261 (gen_data). The Wall gate
# (M101) -> M170 trap tunnels -> point of no return -> M171 tar chasm -> M172 lava trees -> M173 poppy fields (waystone)
# -> M174 watchpost -> M175 Toshi no Kijo (Kage; waystone) -> M176 the plain (hide) -> M177 road home (boss) -> M101.
# Taint tiles: map.json "rt_taint" (plugin RokuganField taintStep); Jade Pouch / waystones cleanse.
CH3 = "crab-ch3"
TAR, LAVA, BOG = 8 | (4 << 5), 8 | (2 << 5), 8 | (3 << 5)       # map_vox water #4 black, #2 red, #3 purple
SL_GROUND, SL_ASH = T(2), T(4)                                  # bare dark earth, grey ash
TARSTAIN, EMBER, POPPYF = T(3, 7), T(0), T(5, 3)                # Taint tiles: stained earth, scorched red, poppy floor
TAINT_TILES = {"M171": ([TARSTAIN], 7), "M172": ([EMBER], 7), "M173": ([POPPYF], 8), "M176": ([TARSTAIN], 5)}
SL_PARTY = [flag("G255", False)]                                # followers last until the chapter ends


def ch3(sid, **kw):
    return script_scene(CH3, sid, **kw)


def waystone(m, ev, x, z, reqs=None):
    """A Hiruma waystone (storyboard crab-ch3): save, rest and cleanse Taint. Stands on the scout's road."""
    fb(m, x, z + 1, 3, 14)
    ev.talk(x, z - 1, "CE000", [(None, [
        narrate("A Hiruma waystone, the crab mon worn almost smooth. Jade grit is packed into the cracks."),
        choices(("Rest, cleanse and save.", REST + [script("::Rokugan.cleanseTaint();"),
                                                    narrate("(Rested. HP and MP restored. Taint cleansed.)"),
                                                    {"cmd": "cmd_showui", "key": "menu_save", "op": None,
                                                     "uiclose": 2}]),
                ("Leave it be.", []))])], reqs=reqs, trigger=1)


def sl_followers(ev, x, z):
    """Kage (after S05) and the broken guard (if carried) trail Natsuko through the Shadowlands."""
    kid = ev.follower(x, z, SC["kage_ch3"], "...Yes, scout. I'm still here.", gap=1.6,
                      reqs=[flag("G249")] + SL_PARTY)
    ev.follower(x, z, EP["veteran"], "...Off watch? Nobody comes off watch.", lead=kid, gap=1.4,
                reqs=[flag("G248"), flag("G249")] + SL_PARTY)
    ev.follower(x, z, EP["veteran"], "...all quiet in sector four...", gap=1.6,
                reqs=[flag("G248"), flag("G249", False)] + SL_PARTY)


def sl_ground(m, seed, back_z=30):
    """Shadowlands ground: dark earth with ash drifts, broken red-rock cliffs behind the road (camera faces north)."""
    rng = np.random.default_rng(seed)
    for _ in range(int(m.w * m.d / 60)):
        x, z = int(rng.integers(0, m.w - 4)), int(rng.integers(0, back_z))
        m.rect(x, z, int(rng.integers(2, 6)), int(rng.integers(1, 4)), SL_ASH)
    for x in range(m.w):
        hh = 7 + int(3 * np.sin(x * 0.17 + seed) + 2 * np.sin(x * 0.41))
        m.rect(x, back_z, 1, m.d - back_z, T(0, None), hh)
    for x in range(4, m.w - 4, 9):
        m.tree(x, back_z - 2 + (x * 3) % 3, (ROCK_M, ROCK_S)[x % 2])


# ---- S01 at the Wall gate (M101; events added in wall_garrison via ch3_gate)
S01_CH3 = [narrate("CHAPTER 3 - Beyond the Wall. (Recommended level 25)")] + ch3("S01") + \
    got("I130", "Jade Pouch", 5) + [
    say("Kaiu Takakana", "And buy a jade finger from the quartermaster if you have the zeni. Wear it out there. The "
                         "Taint can't take hold of anyone who wears jade."),
    narrate("(Taint: Shadowlands ground can Taint you, lowering max HP. A Jade Pouch or a Hiruma waystone cleanses "
            "it. A Jade Finger accessory stops it entirely. The quartermaster by the gate sells both.)"),
                                    {"cmd": "cmd_showui", "key": "menu_save", "op": None, "uiclose": 2}]
GUARD_HOME = [narrate("Behind them, the broken guard steps through the gate, wrapped in Natsuko's cloak. A sentry "
                      "looks at him, and drops his spear."),
              say("Sentry", "...Uncle?")]
S08_CH3 = ch3("S08", stop_at="[IF guard_rescued]") + [if_([flag("G248")], GUARD_HOME)] + \
    ch3("S08", start_at="HIRUMA KAGE: (giving", stop_at="[CHAPTER COMPLETE]") + [
    narrate("\"Beyond the Wall\" - complete."),
    narrate("Natsuko followed her grieving lord into the Shadowlands and found her father's road was real. She "
            "brought Kage home - and learned that a name left in the dark doesn't stay lost."),
    narrate("(Kage keeps the Map of the Road Home.)"),
    leave("P122"), leave("P125"), setf("G255")]


def ch3_gate(m, ev):
    """M101: Hida Sachiko starts the chapter at the Wall gate; the open gate; the quartermaster's T3 stock; S08."""
    ev.talk(17, 39, EP["sachiko"], [
        (None, [say("Sachiko", "Hiruma. Not today. Come back when the court's done with you.")]),
        ([flag("G216"), flag("G240", False)], [
            choices(("Talk to Sachiko.", S01_CH3 + [setf("G240")]), ("Not yet.", []))]),
        ([flag("G240")], [say("Sachiko", "Bring him back, Hiruma. Bring yourself back, too.")])],
        reqs=[flag("G255", False)])
    ev.clerk(20, 39, EP_SERVICE["quartermaster"], "R113")
    ev.talk(23, 39, SC["townguard"], [                                     # storyboard crab-ch3: the blueprint trade
        (None, [say("Kaiu smith", "Bring me a Kaiu blueprint some day and I'll forge it for nothing. Honour of the "
                                  "family.")]),
        ([{"lvar": "NUM_I124", "op": ">=", "rvar": 1}], [
            say("Kaiu smith", "That's my great-uncle's hand on that blueprint! Leave it with me."),
            choices(("Trade the Kaiu Tetsubo Blueprint.", [
                {"cmd": "cmd_itemop", "itemid": "I124", "op": 1, "num": 1, "LV": 1},
                narrate("An hour of hammering. The smith hands back a club still warm from the forge.")] +
                got("W120", "a Kaiu Tetsubo")),
                    ("Keep it.", []))])], reqs=[flag("G216")])
    ev.talk(13, 41, "CE000", [([flag("G240"), flag("G255", False)], [
        narrate("The gate stands open for the first time in forty years. Beyond it: the trap tunnels."),
        choices(("Go through.", [go("M170", 5, 15)]), ("Not yet.", [step_back(0, -2.0)]))])], trigger=5)
    ev.scene(8, 40, "G255", S08_CH3, after="G254", touch=False)


