def trap_tunnels():
    m = cave_map("M170", "Kaiu Wall - trap tunnels", 92, 30,
                 rooms=[(6, 15, 5, 4), (28, 15, 10, 4), (48, 7, 4, 3), (52, 15, 8, 4), (80, 15, 8, 5)],
                 links=[(6, 15, 86, 15, 4), (48, 7, 50, 15, 3)], seed=31, floor=STONEW, wall=STONE)
    for x in (20, 21, 34, 35, 44):                                          # trap stones in the floor
        m.rect(x, 14, 1, 3, KAIU)
    ev = Events(m)
    ev.talk(2, 15, "CE000", [(None, [narrate("Back up to the Wall gate."), go("M101", 13, 38)])], trigger=5)
    ev.scene(18, 15, "G260", ch3("S02", stop_at="[IF nezumi_friends]"), touch=True)
    ev.chest(47, 6, "I128", 3)                                             # Crab sapper's kit: Kaiu Iron Caltrops
    ev.chest(55, 17, "I131", 2)
    ev.prop(78, 13, EP["squeak"], reqs=[flag("G051"), flag("G241", False)], d=1)
    for x, z, k in ((78, 13, "gonta"), (79, 17, "hidden1"), (77, 18, "hidden2")):
        ev.prop(x, z, EP[k], reqs=[flag("G015"), flag("G051", False), flag("G241", False)], d=1)
    ev.scene(74, 15, "G241", [
        if_([flag("G051")], S02_SQUEAK + join("P122", "Squeak", [], lv=22) + [setf("G256")],
            [if_([flag("G015")], S02_GONTA + join("P125", "Gonta", [], lv=22) + [setf("G257")],
                 [narrate("The far mouth of the tunnels. Nobody waits for her. That's fine. It usually is.")])])],
        touch=True)
    ev.talk(87, 15, "CE000", [(None, PONR)], trigger=5)
    return m, ev


# ---- M171 the tar chasm
def sl_tar_chasm():
    m = MapSpec("M171", "Shadowlands - the tar chasm", 112, 40, base=SL_GROUND, y=3)
    sl_ground(m, 1)
    m.rect(48, 0, 14, 30, TAR, 1)                                           # the chasm
    fill(m, 48, 3, 14, 14, 1, 4, PLANK)                                     # the rope bridge
    for x in (48, 61):
        fill(m, x, 4, 13, 1, 2, 1, DARKWOOD), fill(m, x, 4, 18, 1, 2, 1, DARKWOOD)
    for (x, z, w, d) in ((18, 7, 5, 3), (82, 19, 5, 3), (95, 5, 3, 3)):      # tar pools ringed with stained earth
        m.rect(x - 2, z - 2, w + 4, d + 4, TARSTAIN)
        m.rect(x, z, w, d, TAR, 1)
    m.rect(45, 0, 3, 30, TARSTAIN), m.rect(62, 0, 3, 30, TARSTAIN)
    ev = Events(m)
    ev.talk(1, 16, "CE000", [(None, [narrate("The tunnel mouth is a crack in the rock behind her. The way home is "
                                             "forward, along her father's road.")])], trigger=1)
    ev.portal(110, 16, "M172", 1, d=3)                                      # event 2: east
    ev.scene(44, 16, "G242", [narrate("A tar chasm, and a rope bridge across it."),
                              say("Natsuko", "(checking her father's map) \"Tar chasm. Rope bridge.\" ...It's here.")],
             touch=True)
    ev.chest(63, 10, "I104", 2)                                             # on a Taint tile: a deliberate risk
    return m, ev


# ---- M172 the lava trees (b_sl_goblins)
def sl_lava_trees():
    m = MapSpec("M172", "Shadowlands - the lava trees", 112, 40, base=SL_ASH, y=3)
    sl_ground(m, 2)
    for (x, z, w, d) in ((22, 22, 6, 4), (44, 4, 5, 4), (72, 23, 7, 4), (88, 5, 5, 3)):
        m.rect(x - 2, z - 2, w + 4, d + 4, EMBER)
        m.rect(x, z, w, d, LAVA, 1)
    for x in range(8, 104, 7):                                              # the forest that hangs: dead trunks
        m.tree(x, 27 + (x * 5) % 3, (TREE_L, TREE_M)[x % 2])
    m.rect(98, 24, 10, 6, SL_ASH, 3)                                        # the dead end
    ev = Events(m)
    ev.portal(1, 16, "M171", 2, d=1)                                        # event 1: west
    ev.portal(110, 16, "M173", 1, d=3)                                      # event 2: east
    ev.scene(12, 16, "G243", [narrate("The Lava Trees: a forest growing roots-up, its branches buried, dripping "
                                      "fire.")] + ch3("S03", start_at="(A tar chasm", stop_at="[BATTLE b_sl_goblins]")[1:],
             touch=True)
    cave_fight(ev, 58, 16, "G244", 18, [narrate("Goblin warmongers, four of them, painted for war.")],
               [(61, 14, "EP110"), (62, 17, "EP110"), (63, 15, "EP110"), (64, 18, "EP110")])
    ev.talk(38, 25, "CE000", [
        (None, [narrate("A root as thick as a man hangs down from the buried canopy. Something glints in its "
                        "fork."),
                choices(("Climb it.", [narrate("Hiruma scouts climb before they can walk. Natsuko goes up the root "
                                               "hand over hand.")] + got("W121", "a Fine Katana") + [setf("G261")]),
                        ("Leave it.", []))]),
        ([flag("G261")], [narrate("The root sways, empty now.")])], trigger=1)
    ev.talk(103, 27, "CE000", [
        (None, [narrate("A dead end. A Hiruma scout's bones, curled around his pack. His last note is in a careful "
                        "hand: \"The road goes on past the poppies. Tell my daughter I found it.\""),
                say("Natsuko", "I'll tell her, brother.")] + got("A113", "a Hiruma Scout's Jingasa") +
         [setf("G258")]),
        ([flag("G258")], [narrate("Natsuko has laid his bones straight and covered his face.")])], trigger=1)
    return m, ev


# ---- M173 the poppy fields (b_sl_onikage, the ridge, waystone 1)
def sl_poppy_fields():
    m = MapSpec("M173", "Shadowlands - the poppy fields", 112, 40, base=SL_GROUND, y=3)
    sl_ground(m, 3)
    rng = np.random.default_rng(73)
    for (x, z, w, d) in ((14, 6, 16, 10), (36, 18, 14, 9), (60, 4, 18, 9), (70, 19, 10, 8)):
        m.rect(x, z, w, d, POPPYF)
        for _ in range(w * d // 5):
            m.block(x + int(rng.integers(0, w)), z + int(rng.integers(0, d)), FLOWER_R)
    for i, x in enumerate(range(86, 92)):                                   # up onto the ridge
        m.rect(x, 8, 1, 18, SL_GROUND, 3 + (i + 1) // 2)
    m.rect(92, 6, 20, 22, SL_GROUND, 6)
    ev = Events(m)
    ev.portal(1, 16, "M172", 2, d=1)                                        # event 1: west
    ev.portal(110, 16, "M174", 1, d=3)                                      # event 2: east
    cave_fight(ev, 50, 14, "G245", 19, ch3("S03", start_at="(The poppy fields", stop_at="[BATTLE b_sl_onikage]"),
               [(53, 12, "EP116"), (54, 16, "EP116")])
    ridge = ch3("S03", start_at="(A ridge.", stop_at="[IF any_ally]")
    dust = say("Natsuko", "(wiping her eyes with a filthy sleeve) Shadowlands dust. Very irritating.")
    ally = [if_([flag("G256")], [say("Squeak", "...Scout?"), dust],
                [if_([flag("G257")], [say("Gonta", "...Natsuko?"), dust])])]
    ev.scene(96, 16, "G246", ridge + ally, touch=True)
    waystone(m, ev, 102, 12)
    ev.chest(72, 24, "I131", 1)
    ev.chest(76, 6, "N000", 1200)
    return m, ev


