# ---- M175 Toshi no Kijo (S05 Kage; waystone 2)
def toshi_no_kijo():
    m = MapSpec("M175", "Shadowlands - Toshi no Kijo", 84, 44, base=SL_GROUND, y=3)
    sl_ground(m, 5, back_z=36)
    cx, cz, r = 42, 20, 13
    for a in range(0, 360, 6):                                              # the broken coliseum ring
        if 160 < a < 200 or 340 < a or a < 20:
            continue                                                        # gaps: west and east entrances
        x, z = int(cx + r * math.cos(math.radians(a))), int(cz + r * 0.8 * math.sin(math.radians(a)))
        fill(m, x, 4, z, 2, 2 + (a * 7) % 4, 2, STONEW)
    for (x, z) in ((34, 14), (50, 14), (34, 27), (50, 27)):
        fill(m, x, 4, z, 2, 7, 2, STONEW)                                   # pillars
    rng = np.random.default_rng(75)
    for _ in range(26):                                                     # broken pottery everywhere
        a, d = rng.uniform(0, 6.28), rng.uniform(0, 10)
        m.tree(int(cx + d * math.cos(a)), int(cz + d * 0.8 * math.sin(a)), ROCK_S)
    ev = Events(m)
    ev.portal(1, 20, "M174", 2, d=1)                                        # event 1: west
    ev.portal(82, 20, "M176", 1, d=3)                                       # event 2: east
    ev.prop(44, 21, SC["kage_ch3"], reqs=[flag("G249", False)], d=1)
    ev.scene(31, 20, "G249", ch3("S05", stop_at="(Kage walks with the party"), touch=True)
    waystone(m, ev, 47, 30, reqs=[flag("G249")])
    ev.talk(52, 24, "CV036", [                                              # the troll's hoard (storyboard: the plate,
        ([flag("G298", False)], [                                           # or 1,500 zeni if she already has one)
            narrate("The troll's hoard: broken jars, a cracked kabuto, and a suit of Hida heavy plate, folded with "
                    "care."),
            script('W = ::rpgstat.countItems( "A112", true);'),
            if_([{"lvar": "W", "op": ">=", "rvar": 1}],
                [narrate("Natsuko already has a suit like it. Under the plate: a patrol's pay chest the troll carried "
                         "off, still sealed."), {"cmd": "cmd_moneyop", "op": 0, "amount": 1500},
                 narrate("Got 1500 zeni.")],
                got("A112", "Hida Heavy Plate")), setf("G298")]),
        ([flag("G298")], [narrate("Broken jars and a cracked kabuto. The troll kept everything.")])], trigger=1)
    sl_followers(ev, 6, 20)
    return m, ev


