def battle_wall():
    m = MapSpec("M810", "Battle: Kaiu Wall (night)", 128, 128, base=DIRT3, y=0)
    m.rect(0, 30, 128, 56, KAIU, 0)
    m.rect(0, 34, 128, 50, STONEW, 0)                                        # walkway flagstones
    for x in range(0, 128, 4):
        fill(m, x, 1, 84, 2, 3, 2, KAIU)                                     # crenels behind the fight
    fill(m, 0, 1, 86, 128, 1, 1, KAIU)
    for x in range(2, 128, 6):
        fill(m, x, 1, 30, 3, 1, 1, KAIU)                                     # low inner parapet (foreground)
    for x in range(10, 128, 14):
        fb(m, x, 82, 2, LAMP_TORCH)
    for (rx, rz) in ((20, 100), (45, 110), (70, 96), (95, 105), (115, 98)):
        m.tree(rx, rz, ROCK_M)
    return m


def battle_coast():
    m = MapSpec("M811", "Battle: Coast Road", 128, 128, base=SAND, y=0)
    m.rect(0, 0, 128, 40, WATER, 0)
    m.rect(0, 40, 128, 8, SAND2, 0)
    m.rect(0, 72, 128, 6, ROAD, 0)
    m.rect(0, 78, 128, 50, GRASS, 0)
    for x in range(0, 128):
        hh = 8 + int(3 * np.sin(x * 0.13) + 2 * np.sin(x * 0.41))
        m.rect(x, 88, 1, 40, T(2, 0), hh)
    for x in range(6, 128, 11):
        m.tree(x, 95 + (x * 5) % 8, (TREE_L, TREE_M)[x % 2])
        m.tree(min(x + 3, 126), 52 + (x * 3) % 10, ROCK_S)
    return m


def battle_quarry():
    m = MapSpec("M812", "Battle: Old quarry", 128, 128, base=T(2, 6), y=0)
    m.rect(0, 0, 128, 40, GRASS, 0)
    for x in range(0, 128):                                                  # cut stone faces behind the bout
        hh = 9 + int(2 * np.sin(x * 0.17))
        m.rect(x, 86, 1, 6, STONE, hh)
        m.rect(x, 92, 1, 36, STONE, hh + 4)
    for x in (30, 52, 88):
        tent(m, x, 78)
    for x in range(8, 128, 13):
        m.tree(x, 50 + (x * 7) % 12, (ROCK_S, ROCK_M)[x % 2])
    ev = Events(m)
    ev.n = 100                                                               # after M800's own events
    ev.campfire(72, 80)
    return m, ev


