def catalog3():
    """Terrain catalog (dev): rows = wall 0-5, columns = floor none, 0-10 (T(wall, floor)); last row = liquids
    (block page 8, index 0-4) at y 1 over sand."""
    m = MapSpec("M094", "Terrain catalog", 90, 60, base=STONEW, y=1)
    for w in range(6):
        for f in range(-1, 11):
            m.rect(2 + (f + 1) * 7, 2 + w * 8, 6, 6, T(w, None if f < 0 else f), 2)
    for i in range(5):                                                       # map_vox.json has water #0-#4 only
        m.rect(2 + i * 7, 52, 6, 6, 8 | (i << 5), 1)
    return m


