def road_west():
    m = MapSpec("M201", "Road west", 120, 40, base=GRASS, y=3)
    for x in range(120):                                                   # the mountainside behind the road rises
        m.rect(x, 22, 1, 18, T(2, 0), 4 + (x * 7) % 3 + (2 if (x // 13) % 2 else 0))
    m.rect(0, 13, 120, 5, ROAD, 3)
    m.rect(0, 0, 120, 5, GRASS2, 2)                                        # the slope falling away in front
    rng = np.random.default_rng(201)
    for _ in range(60):
        x, z = int(rng.integers(0, 120)), int(rng.integers(5, 22))
        if not (12 <= z < 19):
            m.rect(x, z, int(rng.integers(1, 3)), 1, GRASS3)
    for x in range(4, 116, 9):
        m.tree(x, 26 + (x * 3) % 6, (TREE_L, TREE_M, TREE_S)[x % 3])
    for x in (30, 75, 104):
        m.tree(x, 8, TREE_M)
    m.rect(84, 6, 6, 5, DIRT, 3)                                           # the boar hollow
    ev = Events(m)
    ev.portal(1, 15, "M200", 1, d=1)                                       # event 1: back to the academy
    ev.portal(118, 15, "M202", 1, d=3)                                     # event 2: on to Pleasant Eaves
    ev.scene(4, 15, "G333", S02_CR1, after="G301")
    ev.scene(96, 15, "G1242", [narrate(OBJ_CR2_ROAD)], after=[flag("G321"), flag("G346", False)])   # (saves past Ch1)
    ev.follower(3, 17, "EP356", "Lady Doji Sanae, behind the screen: \"Walk, Rensei-san. Do not march.\"", gap=1.8,
                reqs=[flag("G303", False)])
    ev.scene(60, 15, "G334", FOUR_DAYS, touch=True)
    ev.chest(44, 19, "I100", 2)
    ev.chest(96, 11, "N000", 60)
    ev.talk(86, 9, "CE000", [(None, BOAR_HOLLOW), ([flag("G323")], [narrate("The hollow, quiet now.")])], trigger=1)
    ev.talk(10, 19, "CE000", [(None, [narrate("A road-stone: \"Beiden Pass, four days. Lion lands beyond.\" "
                                              "(Danger 2-8)")])], trigger=1)
    return m, ev


def battle_beiden():
    m = MapSpec("M821", "Battle: Beiden road", 128, 128, base=GRASS, y=0)
    m.rect(0, 70, 128, 8, ROAD, 0)
    m.rect(0, 0, 128, 40, GRASS2, 0)
    for x in range(0, 128):
        hh = 6 + int(3 * np.sin(x * 0.11) + 2 * np.sin(x * 0.37))
        m.rect(x, 90, 1, 38, T(2, 0), hh)
    for x in range(4, 128, 9):
        m.tree(x, 80 + (x * 5) % 8, (TREE_L, TREE_M)[x % 2])
        m.tree(min(x + 4, 126), 98 + (x * 3) % 10, TREE_M)
    return m


BATTLE_SPECS["M821"] = battle_beiden


# ---- Rensei's path action: Charm (rules/skills.md: chance, Etiquette; he starts bad at it). A failed Charm costs the
# village's standing (G330, 3 strikes); at 0 the village refuses until amends are made at the inn.
def with_charm(pages, name, chance, win, taunt, town="G330", done=None, line="May I trouble you, a moment?",
               place="Pleasant Eaves"):
    talk = pages[0][1]
    charm = [if_([{"lvar": town, "op": "<=", "rvar": 0}],
                 [say(name, "The Crane with the speeches? No."), narrate("(Make amends at the inn.)")],
                 [say("Rensei", line), script("W = ::Rokugan.roll( %d);" % chance),
                  if_([flag("W")], win, [say(name, taunt), setf(town, 1, "-="),
                                          narrate("(%s thinks a little less of the stiff young Crane.)" % place)])])]
    menu = [in_party("P101"), if_([flag("W")], [choices(("Talk", talk), ("Charm (%d%%)" % chance, charm),
                                                        ("Leave", []))], talk)]
    out = [(pages[0][0], menu)] + pages[1:]
    if done:
        out.append(([flag(done)], talk))
    return out


