def inn_guest(ev, x, z, n, line, path="G303"):
    """G-1: the guest who isn't travelling waits at the inn; talk to swap. (path: the flag that opens the guest roster
    on that traveler's path: G303 = Crane Ch1 S03.)"""
    key, name, f = GUESTS[n]
    ev.talk(x, z, SC[key], [(None, [say(name, line), choices(
        ("Ask %s to come along." % name, [setf("G232", n), narrate("%s will answer the Guest call." % name)]),
        ("Not now.", []))])], reqs=[flag(f), flag(path), {"lvar": "G232", "op": "!=", "rvar": n}])


def pleasant_eaves():
    m = MapSpec("M202", "Pleasant Eaves", 100, 44, base=GRASS, y=3)
    m.rect(0, 13, 100, 6, DIRT, 3)                                         # the muddy street
    m.rect(0, 0, 100, 7, GRASS3, 3)                                        # paddies' edge in front
    for x in range(0, 100, 3):
        m.block(x, 6, FENCE)
    m.rect(0, 32, 100, 12, GRASS2, 4)                                      # Mountains' Cloak Forest behind
    for x in range(2, 100, 4):
        if not 69 <= x <= 81:
            m.tree(x, 35 + (x * 7) % 7, (TREE_L, TREE_M)[x % 2])
    m.rect(73, 19, 4, 25, DIRT, 3)                                         # the north path into the forest
    building(m, 4, 22, 14, 8, wall=WOOD)                                   # the inn
    building(m, 24, 22, 13, 8)                                             # the headman's house
    fill(m, 44, 4, 21, 6, 1, 3, PLANK)                                     # the peddler's stall
    fill(m, 44, 6, 22, 6, 1, 2, ROOF)
    shrine(m, 84, 24)
    torii(m, 85, 20)
    fill(m, 18, 4, 24, 3, 2, 2, WOOD)                                      # the woodpile behind the inn
    for x in (2, 22, 42, 62, 90):
        fb(m, x, 19, 2, LAMP_STREET)
    ev = Events(m)
    ev.portal(1, 16, "M201", 2, d=1)                                       # event 1: road_west
    north = ev.portal(75, 42, "M203", 1, d=0)                              # event 2: the forest (after S03)
    ev.ev["#%d#" % north]["reqs0"] = [flag("G303")]
    ev.scene(6, 16, "G335", S03_CR1, after="G302", touch=True)
    for x, z, k in ((40, 15, "ebisu"), (38, 16, "youth"), (42, 17, "youth")):
        ev.prop(x, z, SC[k], reqs=[flag("G303", False)], d=0)
    ev.prop(40, 20, "EP356", msg="Lady Sanae's palanquin, its screen closed.", reqs=[flag("G303")], d=2)
    ev.npc(38, 19, SC["sanae"], "Into the forest tonight, Rensei-san. Quietly. The headman has been watching us since "
           "we arrived.", reqs=[flag("G303"), flag("G312", False)])
    ebisu = [(None, [say("Ebisu", "Found it by the waterfall. Shiny. Want sake...")])]
    ev.talk(62, 13, SC["ebisu"], with_charm(ebisu, "Ebisu", 70, [
        say("Ebisu", "Kind Crane. Kind. Show you! Show you where shiny was!"),
        narrate("Ebisu draws the way in the mud with a stick: off the forest path, toward the sound of water. "
                "(The waterfall glade is marked.)"), setf("G322")],
        "(flinching) No! No more questions! Ebisu didn't steal!", done="G322",
        line="Ebisu. Where exactly did you find it? I won't let anyone hurt you."), reqs=[flag("G303")])
    tori = [say("Torishigawa", "The forest is dangerous, my lord. Bandits.")]
    ev.talk(30, 20, SC["torishigawa"], [(None, [in_party("P101"), if_([flag("W")], [choices(
        ("Talk", tori),
        ("Charm", [say("Rensei", "Headman. A man of your experience must know this forest well."),
                   say("Torishigawa", "I'm only a simple headman, my lord. Only a simple headman."),
                   narrate("(He is very good at being simple.)")]),
        ("Leave", []))], tori)])], reqs=[flag("G303")])
    ev.npc(86, 13, SC["youth"], "We didn't mean anything by it. He's eta. He shouldn't have had a sword.",
           reqs=[flag("G303")])
    ev.npc(96, 16, SC["taxman"], "Taxes are Heaven's order, Crane.")
    ev.talk(98, 16, "CE000", [(None, [narrate("The Beiden Pass road, and a Lion checkpoint. Lady Sanae's business is "
                                              "in the forest."), step_back(-2.0, 0)])], trigger=5)
    ev.clerk(46, 20, EP_SERVICE["merchant"], "R115")
    ev.inn(10, 20, EP_SERVICE["innkeeper"], 30)
    ev.talk(7, 20, "CE000", [(None, [narrate("The inn's common room. One room. One futon. Crane eat last.")]),
                             ([{"lvar": "G330", "op": "<=", "rvar": 0}], [
                                 narrate("The village talks about the Crane with the speeches."),
                                 choices(("Buy the room a round. (50 zeni: make amends)",
                                          [if_([{"lvar": "MONEY", "op": ">=", "rvar": 50}],
                                               [{"cmd": "cmd_moneyop", "op": 1, "amount": 50}, setf("G330", 3),
                                                narrate("Rensei pays for the sake and drinks none of it. By the "
                                                        "second jar the village has forgiven him.")],
                                               [narrate("Not enough coin.")])]),
                                         ("Leave.", []))])], trigger=1)
    inn_guest(ev, 12, 19, 5, "The forest won't solve itself, boy. Call me when you want to think.")
    inn_guest(ev, 14, 19, 6, "I'm trying not to hit anyone. It's going well. Need me?")
    ev.chest(20, 23, "I018", 2)                                            # behind the inn: the woodpile
    ev.talk(33, 21, "CE000", [(None, [narrate("The headman's storehouse. A lacquer box, locked.")]),  # (was inside)
                              ([flag("G303"), flag("G324", False)], [
                                  narrate("The headman's storehouse. The lacquer box isn't locked after all. Someone "
                                          "wanted it read.")] + got("I141", "the Pleasant Eaves Tax Ledger") +
                               [{"cmd": "cmd_moneyop", "op": 0, "amount": 150}, narrate("Got 150 zeni."),
                                setf("G324"), say("Rensei", "Tripled. In three years.")]),
                              ([flag("G324")], [narrate("An empty lacquer box.")])], trigger=1)
    shrine_rites(ev, 84, 24, "The village shrine. Someone has left a rice ball for the Green Ronin.",
                 "Rensei kneels on the mud-stained step. For a moment nobody is grading him.")
    return m, ev


