def mountains_cloak_2():
    m = MapSpec("M204", "Mountains' Cloak Forest - the clearing", 90, 44, base=GRASS2, y=3)
    m.rect(0, 14, 90, 5, DIRT, 3)
    m.rect(32, 19, 18, 12, GRASS, 3)                                       # the clearing
    m.rect(60, 19, 5, 18, DIRT, 3)                                         # the dead end: an old training post
    rng = np.random.default_rng(204)
    forest_trees(m, rng, 110, [(0, 90, 12, 21), (30, 52, 19, 33), (58, 67, 19, 38)])
    m.tree(41, 30, TREE_L)                                                 # the tree they're tied to
    fill(m, 61, 4, 36, 1, 3, 1, WOOD)                                      # the training post
    ev = Events(m)
    ev.portal(1, 16, "M203", 2, d=1)                                       # event 1: back
    trail = ev.portal(88, 16, "M205", 1, d=3)                              # event 2: the trail to the village
    ev.ev["#%d#" % trail]["reqs0"] = [flag("G312")]
    ev.talk(86, 16, "CE000", [(None, [narrate("The bandits' trail. Something in the clearing first."),
                                      step_back(-2.0, 0)]), ([flag("G312")], [])], trigger=5)
    ev.prop(40, 28, SC["adoru"], reqs=[flag("G312", False)], d=0)
    ev.prop(43, 28, SC["yasurugi"], reqs=[flag("G312", False)], d=0)
    ev.scene(40, 22, "G339", S04_CLEARING + [setf("G312")], after="G310", touch=True)
    save_shrine(m, ev, 34, 20)
    ev.chest(48, 22, "N000", 120)
    ev.chest(70, 12, "W104", 1)                                            # a Bamboo Yumi
    ev.talk(62, 35, "CE000", [(None, [narrate("An old Kakita training post, notched by a hundred cuts. Someone "
                                              "practised here alone, for a long time. A kozuka is wedged in the "
                                              "top.")] + got("W102", "a Kozuka") + [setf("G340")]),
                              ([flag("G340")], [narrate("The training post. A hundred cuts, all the same height.")])],
            trigger=1)
    return m, ev


def battle_forest_night():
    m = MapSpec("M822", "Battle: Mountains' Cloak Forest", 128, 128, base=GRASS2, y=0)
    m.rect(0, 70, 128, 8, DIRT, 0)
    for x in range(2, 128, 7):
        m.tree(x, 80 + (x * 5) % 9, (TREE_L, TREE_M)[x % 2])
        m.tree(min(x + 3, 126), 96 + (x * 3) % 12, TREE_L)
        m.tree(x, 20 + (x * 7) % 14, TREE_M)
    for x in (30, 64, 98):
        fb(m, x, 82, 2, LAMP_STREET)                                       # the bandits' lanterns
    return m


