def green_ronin_village():
    m = MapSpec("M205", "The Green Ronin's village", 90, 44, base=GRASS, y=3)
    for i, z in enumerate(range(28, 44, 4)):                               # terraced paddies up the hillside
        m.rect(0, z, 90, 4, GRASS2, 4 + i * 2)
        m.rect(4, z + 1, 82, 2, WATER, 4 + i * 2)
    m.rect(0, 14, 90, 5, DIRT, 3)                                          # the village lane
    for z in range(9, 24):                                                 # the palisade, gate at the lane
        if not 13 <= z <= 19:
            m.block(6, z, FENCE)
    building(m, 16, 21, 14, 7, wall=WOOD)                                  # Imuro's house
    m.rect(19, 18, 8, 3, MATTING, 3)                                       # the tea mat
    building(m, 38, 21, 8, 6, wall=WOOD)                                   # the granary
    shrine(m, 56, 21)
    m.rect(72, 18, 8, 3, MATTING, 3)                                       # the inn mat
    for x in (10, 34, 52, 84):
        fb(m, x, 19, 2, LAMP_STREET)
    ev = Events(m)
    ev.portal(1, 16, "M204", 2, d=1)                                       # event 1: the forest trail
    down = ev.portal(88, 16, "M206", 1, d=3)                               # event 2: the road down to the castle
    ev.ev["#%d#" % down]["reqs0"] = [flag("G313")]
    ev.talk(86, 16, "CE000", [(None, [narrate("The road down to Goroso's castle. Not before the village has had its "
                                              "say."), step_back(-2.0, 0)]), ([flag("G313")], [])], trigger=5)
    ev.scene(8, 16, "G341", S05_CR1, after="G312", touch=True)
    ev.npc(24, 17, SC["imuro"], "Tea's still hot, Crane. Lion tea, taxed twice. Drink it slowly.", reqs=[flag("G313")])
