def border_camp_night():
    m = MapSpec("M214", "The border conference - the Crane lines", 110, 40, base=GRASS2, y=3)
    m.rect(0, 14, 110, 5, DIRT, 3)
    for i, x in enumerate(range(8, 100, 12)):
        tent(m, x, 23 + (i % 2) * 5, 6, 5)
        tent(m, x + 4, 5 + (i % 2) * 3, 6, 5)
    tent(m, 84, 24, 9, 6)                                                  # Daidoji Uji's tent
    for x in (14, 40, 66, 92):
        fb(m, x, 20, 2, LAMP_TORCH)
    ev = Events(m)
    ev.portal(1, 16, "M210", 1, d=1)                                       # event 1: back to the port
    dawn = ev.portal(108, 16, "M215", 1, d=3)                              # event 2: the ridge (after Uji)
    ev.ev["#%d#" % dawn]["reqs0"] = [flag("G357")]
    ev.talk(106, 16, "CE000", [(None, [narrate("The ridge. Not before Daidoji Uji has heard you."),
                                       step_back(-2.0, 0)]), ([flag("G357")], [])], trigger=5)
    ev.scene(5, 16, "G380", S04_IN, after="G352", touch=True)
    cave_fight(ev, 30, 16, "G354", 33, [narrate("Sentries, glassy-eyed, block the lane between the tents.")],
               [(33, 15, EP_HE["seduced_sentry"]), (34, 17, EP_HE["seduced_sentry"]), (35, 16, EP_HE["seduced_sentry"])],
               after=SENTRY_BARK)
    ev.talk(52, 19, SC["daidoji_general"], [(None, S04_CHARM), ([flag("G355")], [narrate("The rope line, unguarded.")])],
            reqs=[flag("G354")])
    cave_fight(ev, 62, 16, "G355", 34, [narrate("More sentries. Their eyes shine pink in the torchlight.")],
               [(65, 15, EP_HE["seduced_sentry"]), (66, 17, EP_HE["seduced_sentry"]), (67, 16, EP_HE["seduced_sentry"])])
    ev.prop(86, 22, SC["uji"], reqs=[flag("G357", False)], d=0)
    ev.talk(87, 21, "CE000", [(None, S04_UJI + S04_YAKAMO)], reqs=[flag("G355"), flag("G357", False)], trigger=1)
    ev.chest(48, 22, "I131", 1)                                            # the quartermaster's wagon
    ev.chest(50, 22, "I126", 2)
    return m, ev


