def border_ridge():
    m = MapSpec("M215", "The border conference - the ridge at dawn", 90, 40, base=GRASS, y=3)
    for x in range(90):
        m.rect(x, 26, 1, 14, T(2, 0), 6 + (x * 3) % 3)                     # the ridge
    m.rect(0, 14, 90, 5, DIRT, 3)
    for x in (6, 70, 82):
        tent(m, x, 4, 6, 5)
    ev = Events(m)
    ev.portal(1, 16, "M214", 2, d=1)                                       # event 1: back to the camp
