def sea_fight():
    """One roll-picked sea encounter (bestiary F "Crane sea & isles"): Mantis Corsair 15%, tide crabs, else wako with
    or without an eel."""
    return [script("W = ::Rokugan.roll( 15);"), if_([flag("W")], [battle("M001", 43)], [
        script("W = ::Rokugan.roll( 30);"), if_([flag("W")], [battle("M001", 42)], [
            script("W = ::Rokugan.roll( 50);"), if_([flag("W")], [battle("M001", 40)], [battle("M001", 41)])])])]


def sail(mid, name, landing):
    """A sea leg: one sea fight, a second one half the time, then landfall."""
    storm = [script("W = ::Rokugan.roll( 10);"), if_([flag("W")], [   # the south isles' storm seas: the rare Umibozu
        narrate("The sky goes black. Something rises out of the swell."), battle("M001", 44)])] if mid == "M225" else []
    return [narrate("The ship puts out for %s." % name)] + sea_fight() + storm + [
        script("W = ::Rokugan.roll( 50);"), if_([flag("W")], sea_fight()),
        narrate("Landfall: %s." % name), go(mid, *landing)]


def sea_chart():
    """The chart lists every node the story has revealed (in order, so one menu per stage)."""
    nodes = [n for n in SEA_NODES if n[0] in MAPS_CRANE or n[0] == "M220"]
    stages = [[n for n in nodes[:k + 1]] for k in range(len(nodes))]

    def leg(mid, nm, land):
        if mid != "M225" or "M224" not in MAPS_CRANE:
            return sail(mid, nm, land)
        return [if_([flag("G395")], sail(mid, nm, land), [         # the first time: S05, the storm
            narrate("The ship puts out for the south isles. By dusk the sky is black, and the sea stands up."),
            go("M224", 30, 12)])]                                   # (no sea fight first: Yosuke is a boss)

    def menu(ns):
        return [choices(*([("Sail to %s." % nm, leg(mid, nm, land)) for mid, nm, _, land in ns] +
                          [("Stay aboard.", [])]))]
    pages = [(None, [narrate("The sea chart, weighted with a cup and a knife.")] + menu(stages[0]))]
    for st in stages[1:]:
        pages.append(([flag(st[-1][2])], [narrate("The sea chart, weighted with a cup and a knife.")] + menu(st)))
    return pages


def ship_deck():
    m = MapSpec("M221", "Your ship", 60, 30, base=WATER, y=1)
    m.rect(8, 8, 44, 14, PLANK, 3)                                          # the deck
    for x in range(8, 52):
        m.rect(x, 8, 1, 1, DARKWOOD, 4), m.rect(x, 21, 1, 1, DARKWOOD, 4)  # the rails
    m.rect(4, 11, 4, 8, DARKWOOD, 3)                                        # the bow
    fill(m, 26, 4, 18, 1, 12, 1, DARKWOOD)                                  # the mast
    fill(m, 21, 9, 19, 11, 6, 1, PLASTER)                                   # the sail
    building(m, 40, 15, 10, 6, wall=WOOD)                                   # the cabin at the stern
    ev = Events(m)
    ev.scene(30, 12, "G386", S01_DECK, after="G388")
    ev.clerk(20, 11, SC["shipmaster"], "R121")
    fill(m, 33, 4, 14, 2, 2, 1, DARKWOOD)                                   # the chart table (2 high: at 1 the
                                                                            # step-up lifted you onto the chart)
    ev.talk(34, 14, "CE000", sea_chart(), trigger=1)
    ev.talk(45, 14, "CE000", [(None, [narrate("The captain's cabin: a bunk, a lamp, a basin that never stops "
                                              "sliding."), SAVE_CHOICE])], trigger=1)
    inn_guest(ev, 38, 13, 5, "Ghosts don't get seasick, boy. Luckily I'm not a ghost. Call me when you want to think.")
    inn_guest(ev, 40, 13, 6, "I like boats! Nobody can run away. Need me?")
    inn_guest(ev, 42, 13, 7, "Holding the rail. Holding it very hard. Need me?")
    ev.npc(14, 18, SC["sailor"], "Fair wind, captain. Mostly.")
    return m, ev


def battle_ship_deck(mid="M827", name="Battle: a ship's deck"):
    m = MapSpec(mid, name, 128, 128, base=WATER, y=0)               # combatants stand at height 0 (user: they sank
    m.rect(20, 34, 88, 64, PLANK, 0)                                # into a raised deck), so the deck is the floor
    for x in range(20, 108):
        m.rect(x, 34, 1, 1, DARKWOOD, 1), m.rect(x, 97, 1, 1, DARKWOOD, 1)
    fill(m, 64, 1, 94, 1, 14, 1, DARKWOOD)                                  # the mast behind the fight
    fill(m, 56, 6, 95, 17, 8, 1, PLASTER)
    return m


