def squid_shrine_1():
    m = cave_map("M226", "The White Squid shrine", 80, 44,
                 rooms=[(8, 22, 6, 5), (28, 22, 12, 8), (52, 14, 10, 6), (52, 36, 7, 5), (72, 22, 6, 6)],
                 links=[(12, 22, 18, 22, 4), (38, 20, 44, 15, 4), (52, 19, 52, 31, 4), (60, 16, 68, 21, 4)], seed=11)
    m.rect(48, 12, 3, 2, WATER, 1), m.rect(55, 15, 3, 2, WATER, 1)           # the tide-pools
    m.rect(50, 37, 4, 2, WATER, 1)                                          # the drowned shrine
    for x, z in ((24, 19), (30, 25), (34, 20)):                             # charm-workshop tables
        fill(m, x, 3, z, 3, 1, 1, PLANK)
    for x, z in ((22, 22), (36, 24), (50, 11), (72, 19)):
        fb(m, x, z, 2, LAMP_CANDLE)
    ev = Events(m)
    assert ev.portal(3, 22, "M225", 1, d=1) == 1                            # event 1: out to the isle (its 1)
    assert ev.portal(77, 22, "M227", 1, d=3) == 2                           # event 2: the inner shrine (its 1)
    ev.scene(9, 22, "G399", S07_CR3)
    ev.scene(50, 15, "G409", [narrate("At the tide-pool's edge the water glows white, then goes dark. Whatever is "
                                      "down there is listening.")], touch=True)
    ev.prop(31, 22, SC["tessai"], reqs=[flag("G387")], d=0)
    ev.talk(31, 22, SC["tessai"], [(None, [say("Yasuki Tessai", "My cook's knives! Those are my cook's knives!"),
                                           say("Yasuki Tessai", "These two chests are mine, Kakita-sama. We agreed.")])],
            reqs=[flag("G387")])
    tessai_chest(ev, 26, 26, "G410", got("W121", "a Fine Katana"))
    tessai_chest(ev, 33, 26, "G411", [{"cmd": "cmd_moneyop", "op": 0, "amount": 1500}, narrate("Got 1500 zeni.")])
    ev.chest(28, 17, "I131", 2)
    ev.chest(56, 12, item_named("Sea Salt"), 3)
    ev.chest(50, 38, item_named("Eel"), 3)                                  # the drowned shrine (dead end)
    ev.chest(54, 38, item_named("Pearl"), 1)
    return m, ev


