def kyuden_doji():
    m = MapSpec("M228", "Kyuden Doji", 110, 44, base=STONEW, y=3)
    m.rect(0, 0, 110, 7, WATER, 1)                                          # the sea
    ship(m, 2, 1, n=10)                                                     # your ship's boat at the harbour steps
    m.rect(0, 11, 110, 6, SAND, 3)                                          # the garden avenue (white gravel)
    building(m, 4, 20, 12, 7)                                               # the Doji silk house
    building(m, 20, 20, 12, 7, wall=WOOD)                                   # the Kakita sword gallery
    building(m, 36, 20, 10, 7, wall=WOOD)                                   # the apothecary
    building(m, 62, 20, 13, 7, wall=WOOD)                                   # the inn (x 47-61: the castle approach)
    building(m, 78, 20, 10, 7, wall=WOOD)                                   # the tea house (the actors)
    shrine(m, 91, 20)                                                       # Amaterasu's shrine
    building(m, 101, 20, 8, 7, wall=WOOD)                                   # the rehearsal hall (disused)
    m.rect(0, 32, 110, 12, STONE, 12)                                       # the castle wall at the back
    fill(m, 52, 13, 31, 10, 9, 2, DARKWOOD)                                 # the castle gate
    fill(m, 54, 13, 31, 6, 6, 1, VOID)
    for x in (2, 18, 34, 48, 60, 76, 100):
        fb(m, x, 18, 2, LAMP_STREET)
    ev = Events(m)
    ev.talk(8, 9, SC["shipmaster"], [(None, [say("Ship's master", "The boat's at the steps, captain. Back aboard?"),
                                             choices(("Go aboard.", [go("M221", 30, 12)]), ("Not yet.", []))])])
    gate = DOOR_EV[("M228", "gate")] = ev.portal(57, 31, "M229", 1, d=0)    # the castle (after S01)
    ev.ev["#%d#" % gate]["reqs0"] = [flag("G417")]
    ev.talk(57, 29, SC["craneguard"], [
        (None, [say("Daidoji guard", "Kyuden Doji receives no one today, Kakita-sama. The court is in mourning for "
                                     "its own reputation.")]),
        ([flag("G403"), flag("G417", False)], [
            say("Daidoji guard", "Kakita-sama. Lady Sanae is in her rooms. She asked for tea for two, and she does not "
                                 "drink tea."),
            narrate("CHAPTER 4 - The Play No One Performs. (Recommended level 41)"),
            choices(("Go in.", S01_CR4 + [go("M230", 15, 4, padded=False)]), ("Not yet.", []))]),
        ([flag("G417")], [say("Daidoji guard", "Go up, Kakita-sama.")])], reqs=[flag("G434", False)])
    hall = DOOR_EV[("M228", "hall")] = ev.portal(105, 19, "M234", 1, d=0)   # the rehearsal hall (after the play)
    ev.ev["#%d#" % hall]["reqs0"] = [flag("G425")]
    duel = DOOR_EV[("M228", "east")] = ev.portal(108, 14, "M235", 1, d=3)   # the dueling ground (after the duel)
    ev.ev["#%d#" % duel]["reqs0"] = [flag("G430")]
    ev.talk(106, 14, "CE000", [(None, [narrate("The road east to the Kakita dueling ground. Nobody goes there without "
                                               "a reason."), step_back(-2.0, 0)]), ([flag("G430")], [])], trigger=5)
    ev.clerk(10, 18, EP_SERVICE["merchant"], "R123")
    ev.clerk(26, 18, EP_SERVICE["quartermaster"], "R124")
    ev.clerk(41, 18, EP_SERVICE["jadeclerk"], "R125")
    ev.inn(68, 18, EP_SERVICE["innkeeper"], 120)
    ev.talk(65, 18, "CE000", [(None, [narrate("The inn's common room. Even the sake cups match.")]),
                              ([{"lvar": "G416", "op": "<=", "rvar": 0}], [
                                  narrate("The castle town talks about the Kakita with the speeches."),
                                  choices(("Buy the room a round. (150 zeni: make amends)",
                                           [if_([{"lvar": "MONEY", "op": ">=", "rvar": 150}],
                                                [{"cmd": "cmd_moneyop", "op": 1, "amount": 150}, setf("G416", 3),
                                                 narrate("Rensei buys the good sake, and the town decides he is "
                                                         "a Crane after all.")],
                                                [narrate("Not enough coin.")])]),
                                          ("Leave.", []))])], trigger=1)
    inn_guest(ev, 71, 18, 5, "A Doji castle and a forbidden play. Call me when you want to think, boy.")
    inn_guest(ev, 73, 18, 6, "Nobody here hits anyone. It's horrible. Need me?")
    inn_guest(ev, 75, 18, 7, "Everything's so clean. I keep my hands in my sleeves. Need me?")
    # path-action targets (storyboard): their own travelers aren't here yet, so they just talk
    ev.npc(30, 16, SC["censorclerk"], "Shelf nine? Never heard of it. Nobody has. That's the point of shelf nine.",
           reqs=[flag("G417")])
    ev.npc(23, 16, SC["smithboy"], "The master makes Excellent katana. I make tea. One day, Kakita-sama.")
    ev.npc(96, 17, SC["asahina"], "Amaterasu's light reaches every shelf of the archive, they say. Except one.")
    ev.npc(60, 29, SC["craneguard"], "A duel, Kakita-sama? Not with me. I've seen your father's.", reqs=[flag("G417")])
    ev.npc(83, 18, SC["drunkactor"], "A play! A real play, at night! ...Shh. I never said that.", reqs=[flag("G417")])
    ev.npc(86, 16, SC["actor_a"], "We're rehearsing nothing, Kakita-sama. Nothing at all.", reqs=[flag("G426"),
                                                                                                   flag("G434", False)])
    ev.chest(100, 9, "I131", 3)
    ev.chest(14, 30, "I125", 3)
    ev.chest(16, 30, "I148", 1)
    shrine_rites(ev, 91, 20, "Amaterasu's shrine. A bronze mirror, and a priest who polishes it with his sleeve.",
                 "Rensei kneels. In the mirror his left foot is very still.")
    ev.talk(104, 17, "CE000", [(None, [narrate("A road-stone: \"Kyuden Doji. The Kakita Academy and its dueling "
                                               "ground, east.\"")])], trigger=1)
    return m, ev


