# ---- M234 the rehearsal hall (S03: 3 timing prompts + 2 dialogue picks -> rehearsal_quality)
def cue(line_who, line):
    """One timing prompt: the actor's cue, a beat, then NOW! - closed within 0.9 s it lands (plugin cueEnd)."""
    return [say(line_who, line), {"cmd": "cmd_wait", "time": 700}, script("::Rokugan.cueStart();"),
            narrate("NOW!"), script("W = ::Rokugan.cueEnd( 900);"),
            if_([flag("W")], [setf("G438", 1, "+="), narrate("(On the beat.)")], [narrate("(A beat late.)")])]


