def clue(n, text):
    """Clue n (1-6) found: G446+n, clues_found G453 += 1, then whichever escalation that count opens."""
    f = "G%03d" % (446 + n)
    n_is = lambda k: {"lvar": "G453", "op": "==", "rvar": k}                 # noqa: E731
    return [if_([flag(f, False)], [setf(f), setf("G453", 1, "+="), narrate("(A clue: %s)" % text),
                                    if_([n_is(2), flag("G454", False)], ESC2),
                                    if_([n_is(3), flag("G455", False)], ESC3),
                                    if_([n_is(4), flag("G457", False)], ESC4),
                                    if_([{"lvar": "G453", "op": ">=", "rvar": 5}, flag("G463", False)], [
                                        setf("G463"), narrate("Five clues. Objective: Akodo Hojiki, in the "
                                                              "barracks.")])])]


