def duel_pa(name, gid, win, lose, flag_):
    """Shizue's path action: a Duel (one on one, first blood). Losing costs nothing but the duel."""
    return [say("Shizue", "%s. I challenge you. First blood." % name.split()[-1]),
            dict(battle("M001", gid), losefunc=1), setf(flag_),
            if_([WON], win, lose)]


