def shrine_spot(ev, x, z, f, after, cold):
    """A despoiled shrine on the road: after the Jade Chains, the lock's temperature (the colder/warmer compass)."""
    ev.talk(x, z, "CE000", [(None, [narrate("A despoiled roadside shrine: the doors torn off, the offering bowls "
                                            "kicked into the ditch.")]),
                            ([flag("G470")] + after, [narrate("A despoiled roadside shrine. Out come the Jade "
                                                              "Chains."), narrate(cold), setf(f)]),
                            ([flag(f)], [narrate(cold)])], trigger=1)


def shrine_road_a():
    m = MapSpec("M250", "The shrine road (Lion side)", 110, 36, base=GRASS, y=3)
    m.rect(0, 14, 110, 5, DIRT, 3)
    m.rect(0, 0, 110, 6, WATER, 1)                                          # the Magonojo, by day
    m.rect(0, 6, 110, 3, SAND, 2)
    for x in range(2, 110, 7):
        m.tree(x, 28 + (x * 3) % 5, (TREE_L, TREE_M)[x % 2])
    shrine(m, 40, 22)                                                       # shrine S3
    ev = Events(m)
    ev.portal(1, 16, "M241", 2 if "M250" in MAPS_LION else 1, d=1)          # event 1: Hiruto's castle town
    ev.portal(108, 16, "M251", 1, d=3)                                      # event 2: on east
    shrine_spot(ev, 43, 21, "G473", [flag("G472")], "Cold. Frost on the lacquer.")
    ev.talk(76, 10, "CE000", [(None, [narrate("The Magonojo ruins across the water: the burned warehouses. Smoke "
                                              "still rises from one.")])], trigger=1)
    ev.chest(24, 11, "I101", 1)
    ev.talk(90, 8, "CE000", [(None, [narrate("A river-bank ledge, slippery with fog. Something lodged in the reeds "
                                             "below."), choices(("Climb down. (Athletics)", [
        narrate("Shizue goes down carefully and comes back up carefully. Akodo tacticians do not fall in rivers.")] +
        got("I100", "Rice Ball", 2) + [setf("G477")]), ("Leave it.", []))]),
        ([flag("G477")], [narrate("The ledge. Only reeds now.")])], trigger=1)
    ev.talk(6, 20, "CE000", [(None, [narrate("A road-stone: \"Shiro no Kamatori, two days east. Danger 4-8.\"")])],
            trigger=1)
    if "M278" in MAPS_LION:                                                 # Phoenix Ch1 (defined further down)
        phoenix_road(ev)
    return m, ev


def shrine_road_b():
    m = MapSpec("M251", "The shrine road (Phoenix side)", 110, 36, base=GRASS, y=3)
    m.rect(0, 14, 110, 5, DIRT, 3)
