def winter_road():
    m = MapSpec("M254", "The Lion winter road", 120, 36, base=SNOW, y=3)
    m.rect(0, 14, 120, 5, DIRT, 3)
    m.rect(38, 10, 8, 14, WATER, 2)                                         # the frozen ford
    m.rect(38, 14, 8, 5, STONEW, 3)
    for x in range(2, 120, 6):
        m.tree(x, 4 + (x * 5) % 5, (TREE_L, TREE_M)[x % 2])
        m.tree(x + 3, 28 + (x * 3) % 5, TREE_S)
    shrine(m, 70, 21)                                                       # the Lion waystation
    ev = Events(m)
    ev.portal(1, 16, "M241", DOOR_EV.get(("M241", "west"), 3), d=1)         # event 1: Hiruto's castle town
    ev.portal(118, 16, "M255", 1, d=3)                                      # event 2: Shiro Akodo
    shrine_rites(ev, 70, 21, "A Lion waystation shrine under snow. Someone has brushed the step clean.",
                 "Shizue kneels in the cold and lays out the day's moves in her head.")
    ev.chest(42, 11, "I101", 2)
    ev.talk(96, 26, "CE000", [(None, [narrate("Tracks in the snow, lots of them, into a den under the rocks. "
                                              "(Hunting)"), choices(("Follow the tracks in.", [
        narrate("The den was not empty."), dict(battle("M001", 63), losefunc=1),
        if_([WON], [narrate("At the back of the den: a traveller's pack, frozen stiff.")] + got("I131", "Ginseng Tonic",
                                                                                                2) + [setf("G516")],
            [narrate("Shizue backs out of the den. The wolves don't follow.")])]), ("Leave them be.", []))]),
        ([flag("G516")], [narrate("The den, quiet now.")])], trigger=1)
    ev.talk(6, 20, "CE000", [(None, [narrate("A road-stone under snow: \"Shiro Akodo. Winter Court.\" (Danger "
                                             "18-25)")])], trigger=1)
    return m, ev


def battle_winter_road():
    m = MapSpec("M837", "Battle: the winter road", 128, 128, base=SNOW, y=0)   # fighters stand at height 0
    m.rect(0, 70, 128, 8, DIRT, 0)
    for x in range(4, 128, 9):
        m.tree(x, 92 + (x * 5) % 10, (TREE_L, TREE_M)[x % 2])
    return m


# ---- M255 Shiro Akodo, the castle town (storyboard screen A, F-2)
SWORD_CLUE = [say("Swordsmith", "Rewrapped? Kafu-sama's blade? Lady, if that sword came into my shed, I'd bow to it "
                                "for an hour first."),
              say("Swordsmith", "It hasn't been here."), setf("G500"),
              narrate("Objective: the South Dojo, tonight. The hostess says it was very cold there last night.")]


def shiro_akodo_town():
    m = MapSpec("M255", "Shiro Akodo", 100, 40, base=SNOW, y=3)
    m.rect(0, 12, 100, 6, DIRT, 3)
    building(m, 4, 20, 12, 7, wall=WOOD)                                    # the Lion armoury
    building(m, 20, 20, 10, 7, wall=WOOD)                                   # the apothecary
    building(m, 34, 20, 12, 7, wall=WOOD)                                   # the sake house
    building(m, 50, 20, 10, 6, wall=WOOD)                                   # the swordsmith's shed
    shrine(m, 66, 21)                                                       # Hachiman's shrine
    building(m, 80, 20, 12, 7, wall=WOOD)                                   # the war-fan maker
    m.rect(0, 32, 100, 8, STONE, 10)                                        # the castle wall
    fill(m, 46, 11, 31, 8, 7, 2, DARKWOOD)
    fill(m, 48, 11, 31, 4, 5, 1, VOID)
    for x in range(2, 100, 9):
        m.tree(x, 4 + (x * 3) % 4, (TREE_L, TREE_M)[x % 2])
    for x in (2, 18, 32, 48, 64, 78, 94):
        fb(m, x, 18, 2, LAMP_STREET)
    ev = Events(m)
    ev.portal(1, 15, "M254", 2, d=1)                                        # event 1: the winter road
    ev.portal(50, 30, "M256", 1, d=0)                                       # event 2: the castle
    if "M266" in MAPS_LION:
        east = DOOR_EV[("M255", "east")] = ev.portal(98, 15, "M266", 1, d=3)   # the west road (after Lion Ch3 S01)
        ev.ev["#%d#" % east]["reqs0"] = [flag("G519")]
    if "M272" in MAPS_LION:
        north = DOOR_EV[("M255", "north")] = ev.portal(70, 1, "M272", 1, d=2)  # Sorrow's Path road (after Lion Ch3)
        ev.ev["#%d#" % north]["reqs0"] = [flag("G537")]
    ev.clerk(10, 18, EP_SERVICE["quartermaster"], "R129")
    ev.clerk(25, 18, EP_SERVICE["jadeclerk"], "R130")
    ev.inn(40, 18, EP_SERVICE["innkeeper"], 60)
    for i, n in enumerate((8, 9, 10)):
        inn_guest(ev, 43 + i * 2, 18, n, ("The dead here are very proud of themselves. Need me?",
                                         "My grandfather approves of this castle. Loudly. Need me?",
                                         "The smell is stronger in town. Call me when you're ready.")[i], path="G444")
    ev.talk(55, 18, SC["swordsmith"], [(None, [say("Swordsmith", "Blades, Akodo-sama. I don't sell them. I keep "
                                                                 "them honest.")]),
                                       ([flag("G498"), flag("G500", False)], SWORD_CLUE),
                                       ([flag("G500")], [say("Swordsmith", "That sword would be bowed to. It hasn't "
                                                                           "been here.")])])
    ev.npc(86, 18, SC["merchant"], "War fans, Akodo-sama. Only for display. The jade ones are the dance contest's "
                                   "prize.")
    ev.npc(14, 15, SC["matsuduel"], "Lions don't read. Lions win.")
    ev.npc(70, 16, SC["widow"], "My husband's portrait hangs in the Hall. He looks bored.")
    ev.npc(30, 15, SC["ikomabard"], "Every song is true, if you sing it loudly.")
    ev.chest(96, 9, "N000", 600)
    ev.talk(40, 26, "CE000", [(None, [narrate("The sake house cellar: two jars of good sake and a box of calming "
                                              "tea.")] + got("I125", "Fine Sake", 2) + got("I127", "Calming Tea", 3) +
                               [setf("G518")]), ([flag("G518")], [narrate("An empty cellar shelf.")])], trigger=1)
    shrine_rites(ev, 66, 21, "Hachiman's shrine. A war-god's shrine, scrubbed clean for Winter Court.",
                 "Shizue kneels. Hachiman doesn't care for go, but he listens.")
    return m, ev


# ---- M256 the castle grounds (the garden, the stables, the kitchens; doors to the halls)
DOORS_SA = [("M257", (35, 30)), ("M258", (10, 22)), ("M259", (60, 22)), ("M260", (60, 10)), ("M262", (10, 10)),
            ("M263", (22, 30)), ("M264", (48, 30))]
S08_CL2 = cl2("S08") + guest_join(10) + [setf("G507"), narrate(
    "Moto Benjiro's Death Trance: for a round, nobody in the party fears, and nobody can be charmed. Objective: the "
    "South Dojo, the night before the wedding.")]


def shiro_akodo_grounds():
    m = MapSpec("M256", "Shiro Akodo - the castle", 70, 40, base=SNOW, y=3)
    m.rect(26, 12, 18, 10, GRASS2, 3)                                       # the Central Garden (winter)
    building(m, 28, 32, 16, 6, two_storey=True)                             # the Hall of Honors
    building(m, 4, 24, 12, 6, wall=WOOD)                                    # the Central Dojo
    building(m, 54, 24, 12, 6, wall=WOOD)                                   # the North Dojo
    building(m, 54, 4, 12, 5, wall=DARKWOOD)                                # the South Dojo (cold)
    building(m, 4, 4, 12, 5)                                                # the Hall of Akodo
    building(m, 18, 32, 8, 6, wall=WOOD)                                    # the library
    building(m, 46, 32, 6, 6, wall=STONE)                                   # the cells
    fill(m, 20, 3, 4, 10, 3, 5, WOOD)                                       # the stables
    for x, z in ((27, 13), (43, 13), (27, 21), (43, 21)):                  # the garden's corners (big trees in the
        m.tree(x, z, TREE_S)                                                # middle hid the player)
    ev = Events(m)
    ev.portal(35, 1, "M255", 2, d=2)                                        # event 1: the castle town
    for i, (mid, (x, z)) in enumerate(DOORS_SA):
        door = ev.portal(x, z, mid, 1, d=2 if z < 15 else 0)              # (tester 2026-11-11: the South Dojo and the
        assert door == i + 2                                                # Hall of Akodo face south, the building to
                                                                            # their north: d 0 set you down inside it,
                                                                            # and the fall-rescue put you on the roof)
    ev.ev["#5#"]["reqs0"] = [flag("G498")]                                  # the South Dojo: after Beat 3
    ev.ev["#8#"]["reqs0"] = [flag("G504")]                                  # the cells: after the arrest
    if "M265" in MAPS_LION:
        karo = ev.portal(12, 32, "M265", 1, d=2)                            # event 9: the karo's office (Lion Ch3)
        # (tester 2026-11-11: at (12, 30) d 0 it sat inside the Central Dojo's eaves - no way in, and arriving set you
        # down in the building. A square clear of the back wall now, facing out.)
        assert karo == 9
        ev.ev["#9#"]["reqs0"] = [flag("G510")]
    ev.talk(60, 12, "CE000", [(None, [narrate("The South Dojo. Kafu-sama's. The door is cold to the touch.")]),
                              ([flag("G498")], [])], trigger=5)
    ev.talk(24, 10, SC["benjiro"], [(None, [say("Benjiro", "The Crab laugh at me. Let them.")]),   # (at the stables'
                                                                            # door: at (24, 6) he stood inside the
                                                                            # stables' solid block - tester 2026-11-11)
                                   ([flag("G506"), flag("G507", False)], S08_CL2),
                                   ([flag("G507")], [say("Benjiro", "Tonight, Lion. It is fat enough now.")])])
    ev.npc(28, 7, SC["kitechild"], "Benjiro-sama paints his face every morning.")                # the stable girl
    ev.npc(62, 30, SC["kitchengirl"], "The South Dojo is cold even with the braziers lit.")
    ev.npc(34, 20, SC["yutaka"], "I paint the Wall. With birds in it.")
    ev.npc(40, 22, SC["mami"], "Watch - this paper crane is the Kaiu Wall. This one is your castle. Now it's on fire.")
    ev.talk(30, 24, SC["kafu"], [(None, [say("Kafu", "Court is a battlefield with better tea.")])],
            reqs=[flag("G498", False)])
    ev.talk(30, 24, SC["kafu_nosword"], [(None, [say("Kafu", "My sword? Rewrapping. The hilt was worn.")])],
            reqs=[flag("G498"), flag("G509", False)])
    return m, ev


# ---- M257 the Hall of Honors: S01 and the hostess's four beats
S01_CL2 = cl2("S01") + [setf("G490"), setf("G489"), SAVE_CHOICE,
                        narrate("Objective: the hostess, here in the Hall of Honors, announces the court's events.")]
PAINT = [narrate("The Central Garden. The hostess: \"The theme is tranquillity. Not the garden - what the garden makes "
                 "you feel.\""),
         choices(("A single snowflake on a sword blade.", [setf("G492", 1), narrate("The judges murmur.")] +
                  got("I157", "a Scroll of Acclaim")),
                 ("A sleeping lion.", [setf("G492", 2), narrate("Polite approval.")]),
                 ("The garden, very accurately.", [setf("G492", 3), narrate("A judge sighs.")]),
                 ("Nishi-sama's go stones, mid-game.", [setf("G492", 4), say("Nishi", "...That's not tranquil at all. "
                                                                                     "It's lovely.")])),
         narrate("Kaiu Yutaka shows his painting: a Wall battle; below it a mother bird feeding chicks in a nest."),
         say("Yutaka", "The Wall is the noise. The nest is what the noise is for."),
         say("Shizue", "Then your painting isn't of the Wall at all."), say("Yutaka", "Don't tell the judges.")]
BRACKET_END_WIN = [setf("G494", 1), narrate("Prize: a miniature jade-bladed tanto."),
                   say("Yutaka", "You moved me. Nobody moves me.")]
BRACKET_END_LOSE = [narrate("Prize: still awarded, \"for spirit\": the jade tanto."),
                    say("Yutaka", "You made me move my left foot. Take it.")]
BRACKET = [narrate("The Central Dojo. The hostess: \"The bokken tournament! Every samurai of the court may enter.\""),
           narrate("A Duel: first blood, no seconds. Losing a bout only ends your tournament."),
           say("Ikoma bard", "Did you know my grandfather-"), dict(battle("M001", 58), losefunc=1),
           if_([WON], [say("Matsu bushi", "RAAH!"), dict(battle("M001", 59), losefunc=1),
                       if_([WON], [narrate("The final: Kaiu Yutaka, who hasn't moved his feet once."),
                                   narrate("(He wants you to come to him. Every Crab does. Patience, or a feint.)"),
                                   dict(battle("M001", 60), losefunc=1),
                                   if_([WON], BRACKET_END_WIN, BRACKET_END_LOSE)], BRACKET_END_LOSE)],
               BRACKET_END_LOSE)] + got("W137", "the Jade Tanto") + [
    narrate("Up in the high seats, Akodo Toturi says two words to his karo. The karo writes something down.")]
BEAT1 = PAINT + BRACKET + [setf("G491"), SAVE_CHOICE]
BEAT2 = cl2("S04", stop_at="> CHOICE") + [choices(
    ("\"Matsu Joruri at Sorrow's Path.\"", [narrate("(Glory +1. Toturi glances up.)")]),
    ("\"My uncle's quietest victory.\"", [narrate("Akodo Nishi smiles.")]),
    ("\"The day my cousin started a war.\"", [narrate("A hush. Honest. (Honor +1)")]))] + got(
    "I156", "a Jade Flesh-cutter Arrow") + [setf("G496"), setf("G495")]
BEAT3 = cl2("S05", stop_at="> DEBATE") + [choices(
    ("\"Whose honour was it at Sorrow's Path, when both armies called themselves righteous?\"", []),
    ("\"My uncle told me to find the truth, even a Lion's truth.\"", []),
    ("\"Honour is following orders well.\"", [narrate("The Matsu speaker smiles. Weak."),
                                              say("Shizue", "...And yet.")]))] + \
    cl2("S05", start_at="SHIZUE: (strong)", stop_at="### The sword") + got("A130", "Akodo's Leadership") + [
    setf("G499"), narrate("Days later. Akodo Kafu no longer wears his ancestral katana."),
    say("Kafu", "Rewrapping. The hilt was worn."),
    narrate("Objective: the swordsmith's shed, in the castle town."), setf("G498")]
DANCE = [narrate("The dance. Who will Shizue partner?"), choices(
    ("Kaiu Yutaka.", [say("Yutaka", "I dance like a wall."), say("Shizue", "Then I'll dance like a siege.")]),
    ("Daidoji Atsuko.", [say("Atsuko", "A Lion asking a Crane spy to dance. They'll talk."), say("Shizue", "Let "
                                                                                                     "them.")]),
    ("Moto Benjiro.", [say("Benjiro", "No one ever asks me."), narrate("He dances surprisingly well.")]))] + \
    got("A131", "the Jade-inlaid War Fans") + [
    narrate("Akodo Nishi dances with her betrothed, smiling the whole way through. Her smile breaks only once - when "
            "she passes Kafu.")]
SEAL = [narrate("The next morning. Akodo Toturi strides into the hall, his karo behind him, dragging Daidoji Atsuko."),
        say("Toturi", "My seal. My mon. Taken from my own chamber."),
        say("Karo", "The Crane was seen in the corridor, my lord."),
        say("Toturi", "Akodo Shizue. You have a week. Clear her or confirm her."),
        narrate("That night Shizue lays them out in her room: a scarf, a flower, Duty, the banner, the sword, "
                "letters, the seal."),
        say("Shizue", "A scarf from a friend. A flower from the garden. Duty. The banner. His sword. The seal."),
        say("Shizue", "...They're all Kafu's. Everything Kafu loves, in order. Someone is taking his life apart one "
                      "piece at a time."),
        setf("G504"), narrate("Objective: Daidoji Atsuko, in the cells.")]
BEAT4 = DANCE + SEAL + [setf("G503"), SAVE_CHOICE]
HOSTESS = [(None, [say("Hostess", "Welcome to Winter Court, Akodo-san.")]),
           ([flag("G489"), flag("G491", False)], [say("Hostess", "The court's first contests: painting in the garden, "
                                                                  "then the bokken tournament."),
                                                   choices(("Begin.", BEAT1), ("Not yet.", []))]),
           ([flag("G493"), flag("G495", False)], [narrate("Tonight: the history dinner."),
                                                   choices(("Begin.", BEAT2), ("Not yet.", []))]),
           ([flag("G497"), flag("G498", False)], [narrate("Today: the bushido debate."),
                                                   choices(("Begin.", BEAT3), ("Not yet.", []))]),
           ([flag("G498"), flag("G501", False)], [say("Hostess", "The South Dojo was so cold last night, my lady - has "
                                                                  "anyone looked?")]),
           ([flag("G501"), flag("G503", False)], [say("Hostess", "The dance contest! Partners, please."),
                                                   choices(("Begin.", BEAT4), ("Not yet.", []))]),
           ([flag("G503")], [say("Hostess", "The wedding is in a week. Everyone keeps telling the bride.")])]


def hall_of_honors():
    def extra(m, ev):
        ev.talk(18, 10, SC["hostess"], HOSTESS)
        ev.npc(24, 11, SC["toturi"], "...", reqs=[flag("G499", False)])
        ev.npc(24, 11, SC["toturi"], "Akodo Shizue.", reqs=[flag("G499")])
        ev.npc(8, 9, SC["gesshin"], "Sufficient.")
        ev.npc(30, 9, SC["hiruto"], "The far end of the hall, Shizue. You see the whole board from there.")
        ev.scene(18, 4, "G489", S01_CL2)
    return castle_floor("M257", "Shiro Akodo - the Hall of Honors", 36, 12, [
        ("tatami", 6, 5), ("tatami", 12, 5), ("tatami", 24, 5), ("tatami", 30, 5), ("dais", 15, 10, 6, 2),
        ("candle", 3, 12), ("candle", 33, 12)], down=("M256", 2), extra=extra)


ESC1 = [narrate("The Central Dojo. A pale rectangle on the wall where a painting hung. Servants whisper."),
        say("Servant", "The \"Duty\" plaque. Gone. In the night. Who would steal Duty?"),
        say("Courtier", "The Crane, of course."), setf("G493")]


def central_dojo():
    def extra(m, ev):
        ev.scene(12, 4, "G493", ESC1, after="G491")
        ev.talk(12, 10, "CE000", [(None, [narrate("The bushido paintings, in order like a scroll.")]),
                                  ([flag("G493")], [narrate("The bushido paintings, in order like a scroll. One is "
                                                            "missing: \"Duty\".")])], trigger=1)
    return castle_floor("M258", "Shiro Akodo - the Central Dojo", 26, 10, [("candle", 3, 10), ("candle", 23, 10)],
                        down=("M256", 3), extra=extra)


GO_GAME = [say("Nishi", "Sit. Black, as always?"), narrate("A go game in the North Dojo. Nishi plays fast."),
           choices(("Sacrifice the left edge.", [say("Nishi", "Four summers, and you still do that."), setf("G517")]),
                   ("Take the centre at once.", [say("Nishi", "Hm. Greedy. Kafu plays like that.")]),
                   ("Play her own move back at her.", [say("Nishi", "...Kafu taught me that one. Kafu taught me to "
                                                                    "play."), setf("G517")]))]


def north_dojo():
    def extra(m, ev):
        ev.talk(12, 9, SC["nishi"], [(None, [say("Nishi", "My wedding is in eleven weeks. Everyone keeps telling me."),
                                             choices(("A game of go?", GO_GAME), ("Leave.", []))]),
                                     ([flag("G510")], [say("Nishi", "...Black, as always.")])])
        ev.talk(18, 10, "CE000", [(None, [narrate("The painting \"Honor\", Nishi's favourite.")])], trigger=1)
    return castle_floor("M259", "Shiro Akodo - the North Dojo", 26, 10, [("tatami", 10, 6), ("candle", 3, 10),
                                                                        ("candle", 23, 10)],
                        down=("M256", 4), extra=extra)


S06_IN = [narrate("The South Dojo at night. Cold. Braziers guttering. A wet trail across the floorboards that hisses "
                  "where it touches the wood."),
          say("Shizue", "Something crawled here. Something heavy. And frightened."),
          narrate("Terror: a Terrified traveler may lose the turn, and can't use Void. Jade gear resists it; Calming Tea "
                  "cures it."),
          battle("M001", 61), setf("G502"),
          narrate("The trail goes under the floor. A loose board.")]
S06_VOICES = [narrate("Behind the dojo's inner screen: a voice, very faint - Kafu's - and another, many voices "
                      "layered."),
              say("Kafu", "...I've given you everything. Everything. Please."),
              say("Other voice", "...Not everything. Not yet."), setf("G513"), setf("G501"), SAVE_CHOICE]
S09_CL2 = cl2("S09", stop_at="### Talk-down") + [choices(
    ("\"Think of Nishi.\"", [say("Kafu", "I think of nothing else. That's how it eats me.")]),
    ("\"Remember your duty.\"", [say("Kafu", "My duty brought me here.")]),
    ("\"You told the story of the man who wept. Weep now, where I can see.\"", [
        if_([flag("G490"), flag("G496")], [say("Kafu", "...Thirty years. No more."),
                                           narrate("Akodo Kafu weeps, openly. Then he rises and draws his short "
                                                   "sword."), setf("G508")],
            [say("Kafu", "What man? I don't know what you mean.")])]))] + [
    narrate("Oni no Ianwa has no attacks of its own. Each turn it charms one of you. Jade cuts the chance; Death "
            "Trance blocks it. It breaks on Jade and Fire - and it is a coward."),
    if_([flag("G508")], join("P129", "Akodo Kafu", [], lv=22)),
    battle("M001", 62), leave("P129"), setf("G509"),
    say("Benjiro", "...It's lying. It won't come back. Cowards never do.")]
S10_CL2 = [narrate("Dawn.")] + [if_([flag("G508")], [
    narrate("Kafu asks Toturi's leave for seppuku. Toturi grants it. In the garden, Kafu kneels. He looks past Nishi, "
            "who stands at the edge of the snow, to the mountains."),
    say("Kafu", "You can see all the way to the Spine this morning. I'd forgotten."),
    narrate("The wedding goes ahead at noon. Nishi doesn't cry until evening, alone in the North Dojo - where Shizue "
            "finds her, says nothing, and sets up the go board. They play until morning.")], [
    narrate("Kafu is taken in chains. Toturi orders his name cut from every record."),
    say("Toturi", "The Akodo have no son called Kafu. Not any more."),
    narrate("The wedding goes ahead. In the North Dojo, Shizue sets up the go board. Nishi looks at it, and doesn't "
            "play.")])] + [
    narrate("The stolen objects are found in the oni's lair beneath the floor - all but one. The plaque \"Duty\" is "
            "never found."),
    if_([{"lvar": "G505", "op": "==", "rvar": 1}], [say("Atsuko", "You kept your one true thing, Lion. I'll "
                                                                 "remember.")]),
    narrate("A corridor. Toturi passes Shizue without stopping."), say("Toturi", "Akodo Shizue. Again."),
    narrate("\"Shadow of a Doubt\" - complete."),
    narrate("A cowardly oni ate a good man one treasure at a time. Shizue found the pattern, armed herself in jade "
            "without knowing why, and made the Lion Champion learn her name."), setf("G510")]


def south_dojo():
    def extra(m, ev):
        ev.prop(14, 9, SC["kafu_nosword"], reqs=[flag("G507"), flag("G509", False)], d=0)
        ev.scene(12, 4, "G502", S06_IN, after="G498")
        DOOR_EV[("M260", "board")] = ev.portal(20, 6, "M261", 1, d=0)       # the loose board (after the fight)
        ev.ev["#%d#" % DOOR_EV[("M260", "board")]]["reqs0"] = [flag("G502")]
        ev.talk(6, 9, "CE000", [(None, [narrate("The inner screen. Behind it, silence.")]),
                                ([flag("G511"), flag("G513", False)], S06_VOICES),
                                ([flag("G513")], [narrate("The inner screen. Cold air breathes through it.")])],
                trigger=1)
        ev.scene(12, 6, "G514", S09_CL2 + S10_CL2 + DARK + [go("M256", 35, 4)], after="G507")
    return castle_floor("M260", "Shiro Akodo - the South Dojo at night", 26, 10, [
        ("candle", 3, 10), ("candle", 23, 10)], down=("M256", 5), extra=extra)


def under_dojo():
    m = cave_map("M261", "Under the South Dojo", 60, 30,
                 rooms=[(8, 15, 5, 4), (26, 14, 8, 5), (46, 10, 6, 4), (46, 22, 5, 4)],
                 links=[(12, 15, 18, 14, 3), (33, 13, 41, 10, 3), (46, 14, 46, 18, 3)], seed=21,
                 floor=PLANK, wall=DARKWOOD)
    ev = Events(m)
