    shrine(m, 78, 22)                                                       # a roadside Hachiman
    for x in range(2, 100, 8):
        m.tree(x, 34 + (x * 3) % 4, TREE_M)
    ev = Events(m)
    ev.portal(1, 14, "M266", 2, d=1)                                        # event 1: the west road
    east = ev.portal(98, 14, "M268", 1, d=3)                                # event 2: the waystation (after the ford)
    ev.ev["#%d#" % east]["reqs0"] = [flag("G522")]
