def hermitage():
    m = MapSpec("M271", "Kaze-no-Tani", 60, 30, base=SNOW, y=3)
    m.rect(0, 22, 60, 8, STONE, 12)                                         # the peaks
    building(m, 24, 14, 12, 6, wall=WOOD)                                   # the hermitage
    fill(m, 40, 4, 15, 4, 2, 2, WOOD)                                       # the woodpile
    m.rect(10, 16, 4, 3, WATER, 2)                                          # the cold spring
    ev = Events(m)
    ev.portal(2, 10, "M270", 2, d=1)                                        # event 1: back down the pass
    ev.prop(30, 12, SC["shogen"], reqs=[flag("G533", False)], d=0)
    ev.scene(28, 9, "G531", SHOGEN, touch=True, after=[ROUTE_A, flag("G530")])
    ev.talk(42, 13, "CE000", [(None, [narrate("Shogen's woodpile, and behind it a jar of plum wine.")]),
                              ([flag("G541", False), flag("G533")], [
                                  narrate("A jar of plum wine behind the woodpile."),
                                  choices(("Take it.", [narrate("Shogen notices. He laughs so hard he has to sit "
                                                                "down. (Honor -1)")] +
                                           got("I125", "Shogen's Plum Wine") + [setf("G541")]),
                                          ("Leave it.", []))])], trigger=1)
    shrine_rites(ev, 9, 18, "A cold spring under the peaks. The water is so clear it looks like nothing.",
                 "Shizue kneels. The cold is a rumour.")
