def cl4(sid, **kw):
    return script_scene("lion-ch4", sid, **kw)


FULL_NAMES.update({"Rokuro": "Matsu Rokuro", "Yosai": "Togashi Yosai"})
GO_ME = {"lvar": "G556", "op": "==", "rvar": 3}                             # Shizue crossed herself: Hiruto holds
ADD_SHIZUE = {"cmd": "cmd_memberop", "playerid": "P103", "op": 0, "slot": -1}


def bark4(shizue, hiruto):
    return [if_([GO_ME], [say("Hiruto", hiruto)], [say("Shizue", shizue)])]


# ---- M272 Sorrow's Path road (the old battlefield)
def sorrows_road():
    m = MapSpec("M272", "Sorrow's Path road", 110, 36, base=GRASS, y=3)
    m.rect(0, 14, 110, 5, DIRT, 3)
    m.rect(0, 0, 110, 4, WATER, 1)                                          # the river, east toward the ford
    for i, x in enumerate(range(8, 100, 11)):                               # grave-mounds and rusted spears
        fill(m, x, 3, 24 + i % 3, 3, 1, 3, DIRT)
        fill(m, x + 5, 3, 7 + i % 2, 1, 3, 1, DARKWOOD)
    fill(m, 58, 3, 22, 2, 4, 2, STONE)                                      # Matsu Joruri's victory stone
    fill(m, 36, 3, 6, 5, 2, 4, WOOD)                                        # the collapsed watchtower
    for x in range(3, 104, 8):
        m.tree(x, 30 + (x * 3) % 4, (TREE_L, TREE_M)[x % 2])
    ev = Events(m)
    ev.portal(1, 16, "M255", DOOR_EV.get(("M255", "north"), 4), d=1)        # event 1: Shiro Akodo
    for dest, reqs in (("M273", [flag("G551", False)]), ("M274", [flag("G551"), flag("G561", False)]),
                       ("M276", [flag("G561"), flag("G573", False)]), ("M273", [flag("G573")])):
        e = ev.portal(108, 16, dest, 1, d=3)                                # events 2-5: the camp, by day or night
        ev.ev["#%d#" % e]["reqs0"] = reqs
    ev.talk(59, 21, "CE000", [(None, [narrate("Matsu Joruri's victory stone. Centuries of rain have nearly taken "
                                              "the words. (Lore: History)"),
                                      narrate("Shizue reads the battle off the stone the way she'd read a go game: "
                                              "where the Matsu line broke, and why."),
                                      narrate("(Wave 1 at the ford: the berserkers break sooner, Resolve -1.)"),
                                      setf("G549")]),
                              ([flag("G549")], [narrate("Matsu Joruri's victory stone.")])], trigger=1)
    ev.talk(38, 10, "CE000", [(None, [narrate("A collapsed watchtower. A spear-shaft sticks out of the beams up "
                                              "top. (Athletics)"),
                                      choices(("Climb.", [narrate("Shizue goes up the leaning beams.")] +
                                               got("W138", "a Matsu War Yari") + [setf("G550")]),
                                              ("Leave it.", []))]),
                              ([flag("G550")], [narrate("The collapsed watchtower.")])], trigger=1)
    ev.chest(24, 21, "I131", 1)
    ev.npc(102, 18, SC["lionrider"], "Lion pickets, Akodo-sama. The camp's just ahead, at the ford. The Crane are "
                                     "on the other bank.")
    ev.talk(6, 20, "CE000", [(None, [narrate("A road-stone: \"Kanashimi no Komichi. Sorrow's Path.\" (Danger "
                                             "40-46)")])], trigger=1)
    return m, ev


def battle_old_battlefield():
    m = MapSpec("M841", "Battle: the old battlefield", 128, 128, base=GRASS, y=0)   # fighters stand at height 0
    m.rect(0, 70, 128, 8, DIRT, 0)
    for i, x in enumerate(range(6, 128, 13)):
        fill(m, x, 0, 92 + i % 3 * 3, 4, 1, 3, DIRT)                        # grave-mounds
        fill(m, x + 6, 0, 88 + i % 2 * 4, 1, 3, 1, DARKWOOD)                # a rusted spear
    for x in range(4, 128, 11):
        m.tree(x, 108 + (x * 5) % 10, (TREE_L, TREE_M)[x % 2])
    return m


