def lion_camp(mid, night):
    m = MapSpec(mid, "The Lion camp at the ford" + (" (night)" if night else ""), 100, 40, base=GRASS, y=3)
    m.rect(0, 0, 100, 8, WATER, 1)                                          # the river; the Crane on the far bank
    m.rect(0, 14, 100, 5, DIRT, 3)
    building(m, 8, 21, 14, 6, wall=PLASTER)                                 # the command tent
    building(m, 28, 21, 10, 5, wall=PLASTER)                                # Gusai's tent
    building(m, 45, 21, 9, 5, wall=WOOD)                                    # the quartermaster
    building(m, 56, 21, 9, 5, wall=WOOD)                                    # the field kitchen
    building(m, 67, 21, 9, 5, wall=PLASTER)                                 # Yachiko's tent
    shrine(m, 84, 22)                                                       # the camp shrine
    for x in range(2, 100, 7):
        m.tree(x, 34 + (x * 3) % 4, (TREE_L, TREE_M)[x % 2])
    for x in (4, 26, 44, 66, 82, 96):
        fb(m, x, 19, 2, LAMP_STREET)
    ev = Events(m)
    ev.portal(1, 16, "M272", 2, d=1)                                        # event 1: Sorrow's Path road
    east = ev.portal(98, 16, "M275", 1, d=3)                                # event 2: the riverbank
    ev.ev["#%d#" % east]["reqs0"] = [flag("G555"), flag("G561", False)]
    ev.talk(96, 16, "CE000", [(None, [narrate("The riverbank path. Nothing to do there yet."), step_back(-2.0, 0)]),
                              ([flag("G555")], [])], trigger=5)
    ev.clerk(49, 19, EP_SERVICE["quartermaster"], "R132")
    ev.inn(58, 19, EP_SERVICE["innkeeper"], 120)
    ev.clerk(61, 19, EP_SERVICE["merchant"], "R133")
    for i, n in enumerate((8, 9, 10)):
        inn_guest(ev, 40 + i * 2, 19, n, ("The river's dead are loud tonight. Need me?",
                                         "Every Lion here is pretending not to be afraid. Need me?",
                                         "I can make them stop being afraid for a breath. Call me.")[i], path="G444")
    shrine_rites(ev, 84, 22, "The camp shrine: a war-god's stones, and a bowl of river water.",
                 "Shizue kneels. The river runs on either side of the prayer.")
    ev.prop(18, 19, SC["shogen"], reqs=[flag("G532")], d=2)
    ev.talk(18, 20, "CE000", [(None, [say("Shogen", "Think the other thing, girl.")])], reqs=[flag("G532")])
    return m, ev


