def the_ford():
    m = MapSpec("M276", "The ford at Sorrow's Path", 100, 30, base=GRASS, y=3)
    m.rect(14, 0, 72, 30, WATER, 1)                                         # the river
    m.rect(14, 12, 72, 6, SAND, 2)                                          # the ford: stones and gravel
    for x in range(16, 86, 5):
        fill(m, x, 2, 11 + (x * 3) % 2 * 7, 1, 1, 1, STONE)                 # stepping stones at the edges
    fill(m, 30, 2, 3, 40, 1, 3, DARKWOOD)                                   # the old bridge upstream (burning)
    for x in (30, 48, 66):
        fill(m, x, 1, 3, 1, 2, 3, DARKWOOD)
    building(m, 88, 21, 8, 5, wall=PLASTER)                                 # Crane tents on the far bank
    building(m, 88, 4, 8, 5, wall=PLASTER)
    for x in (2, 6, 10):
        m.tree(x, 4 + x % 3, TREE_M)
    ev = Events(m)
    west = ev.portal(1, 15, "M272", 2, d=1)                                 # event 1: back up the road (after)
    ev.ev["#%d#" % west]["reqs0"] = [flag("G573")]
    tent = ev.portal(98, 15, "M277", 1, d=3)                                # event 2: the courtier's tent (after)
    ev.ev["#%d#" % tent]["reqs0"] = [flag("G573")]
    ev.talk(3, 15, "CE000", [(None, [narrate("The shield-line. No one leaves it now."), step_back(2.0, 0)]),
                             ([flag("G573")], [])], trigger=5)
    ev.talk(96, 15, "CE000", [(None, [narrate("The Crane bank. Not yet."), step_back(-2.0, 0)]),
                              ([flag("G573")], [])], trigger=5)
