# ---- M287 the traitor's torii (S05 the debate, by day; S06 Hioninmaru, by night)
def strong(line_who, lines):
    return [say(line_who, t) for t in lines] + [setf("G626", 1, "+="), narrate("(A strong answer. Someone in the mob "
                                                                                "looks at the ground.)")]


DEBATE = cp2("S05", stop_at="### DEBATE") + [
    narrate("The debate: the mob raises three claims. Two strong answers will turn them."), setf("G626", 0),
    narrate("Claim 1: \"He disobeyed his lord.\""),
    choices(("\"So did the boy who ran into a burning house to save his sister.\"",
             strong("Haruki", ["So did the boy who ran into a burning house to save his sister. Do we burn his memory "
                               "too?"])),
            ("\"He had his reasons.\"", [say("Haruki", "He had his reasons."), narrate("(A weak answer.)")])),
    narrate("Claim 2: \"Honouring a traitor insults the loyal dead.\""),
    choices(("\"The loyal dead would want peace.\"", [say("Haruki", "The loyal dead would want us at peace."),
                                                     narrate("(A weak answer.)")]),
            ("Let Ashimita answer.", strong("Ashimita", ["My grandfather screams at me for every order I've ever "
                                                         "obeyed.", "The loyal dead died for something. Ask what."]))),
    narrate("Claim 3: \"There is no righteousness in disobedience.\""),
    choices(("\"He refused an order to burn people.\"",
             strong("Haruki", ["He refused an order to burn people. You'd burn his shrine for it.",
                               "Which of those is the insult to the dead?"])),
            ("\"Perhaps not. But he was brave.\"", [say("Haruki", "Perhaps not. But he was brave."),
                                                    narrate("(A weak answer.)")])),
    narrate("Silence. A torch lowers. Then another."),
    if_([{"lvar": "G626", "op": ">=", "rvar": 2}],
        [setf("G625"), say("Mob Leader", "...Leave it. Leave it standing.")] + honor(1),
        [narrate("The torii burns. Haruki stands in the smoke until it's gone.")]),
    setf("G624"), narrate("Objective: back to the guest houses. Rest until night.")]
BOSS_PHX2 = cp2("S06", stop_at="[BATTLE") + [
    narrate("Hioninmaru's maho costs him his own blood, and his blood Taints. If his cultists fall, his nerve goes."),
    battle("M001", 81),
    say("Hioninmaru", "It said the best of you... the very best... why not me?"),
    say("Haruki", "Because you wanted it."),
    narrate("\"The Consumer\" lies in the snow where he dropped it."),
    choices(("Give it to the Council.", [narrate("Keiki locks it away. Haruki doesn't watch where.")]),
            ("Keep it.", [setf("G629")] + got("I169", "\"The Consumer\""))),
    setf("G628")] + DARK + [go("M285", 54, 12)]
S07_PHX2 = cp2("S07", stop_at="[CHAPTER COMPLETE]") + got("I172", "a Scroll: Courage of the Seven Thunders") + [
    setf("G638"), narrate("Haruki learns Courage of the Seven Thunders."),
    narrate("\"The Silent Court\" - complete."),
    narrate("At Hoju's memorial, Haruki refused a ritual of forgetting, defended a traitor's shrine with words, and met "
            "Mieko, who remembers a boy who counted on his fingers. At midnight, she remembers more."),
    narrate("Rank 2: the Council finally writes down Isawa Haruki's name."),
    leave("P131"), say("Ashimita", "Kamasari is leaving. So am I. My grandfather says to keep an eye on you."),
    setf("G630"), narrate("Next: the Darkfever. Kyuden Isawa, by the south road out of the treaty city. (Recommended "
                          "level 30)")]


def traitors_torii():
    m = MapSpec("M287", "The traitor's torii", 60, 30, base=SNOW, y=3)
    m.rect(0, 24, 60, 6, STONE, 9)                                          # the mountain
    for x in (26, 34):
        fill(m, x, 3, 18, 1, 6, 1, DARKWOOD)                                # the torii's pillars
    fill(m, 24, 9, 18, 13, 1, 1, DARKWOOD)                                  # ... and its beams
    fill(m, 25, 8, 18, 11, 1, 1, DARKWOOD)
    for x in range(2, 60, 9):
        m.tree(x, 4 + (x * 3) % 5, TREE_M)
    ev = Events(m)
    ev.portal(2, 12, "M285", 2, d=1)                                        # event 1: down to the city
    ev.prop(30, 10, SC["mobleader"], reqs=[flag("G624", False)], d=2)
    for x in (26, 34):
        ev.prop(x, 9, SC["youth"], reqs=[flag("G624", False)], d=2)
    ev.scene(30, 13, "G640", DEBATE, touch=True, after=[flag("G622")])
    ev.prop(30, 10, EP_HE["bloodspeaker"], reqs=[flag("G627"), flag("G628", False)], d=2)
    for x in (27, 33):
        ev.prop(x, 9, EP_HE["painted_cultist"], reqs=[flag("G627"), flag("G628", False)], d=2)
    ev.scene(30, 14, "G641", BOSS_PHX2, touch=True, after=[flag("G627")])
    ev.talk(30, 17, "CE000", [(None, [narrate("The traitor's torii.")]),
                              ([flag("G625")], [narrate("Shiba Mitsuhide's torii, still standing. Someone has left "
                                                        "a candle.")]),
                              ([flag("G624"), flag("G625", False)], [narrate("Ash where the torii stood.")])],
            trigger=1)
    return m, ev


