# no inn; the temple hospital lets Haruki rest once; treatments cost his SP.
def cp3(sid, **kw):
    return script_scene("phoenix-ch3", sid, **kw)


FULL_NAMES.update({"Hayato": "Doji Hayato", "Rujo": "Isawa Rujo", "Uona": "Isawa Uona"})
S01_PHX3 = [narrate("CHAPTER 3 - The Darkfever. (Recommended level 30)")] + cp3("S01", stop_at="[SAVE]") + [
    say("Kamasari", "Ashimita goes with you. The Council will want someone to blame if you die, and I'd rather it "
                    "wasn't me."),
    say("Ashimita", "My grandfather says fevers are cowards. Fight them in the open.")] + \
    join("P131", "Shiba Ashimita", [], lv=30) + [setf("G651"), SAVE_CHOICE,
                                                 narrate("Objective: the fever villages, out of the south gate.")]


def sp_cost(n, ok):
    """Haruki spends SP on a treatment (the fever villages have no inn)."""
    return [script('local h = ::rpgstat.playermap["P104"]; W = !!h && h.MP >= %d; if( W) h.MP -= %d;' % (n, n)),
            if_([flag("W")], ok, [narrate("Not enough SP. (Rejuvenating Tea restores it; the fever villages have no "
                                          "inn.)")])]


def treated(f, line):
    return [narrate(line), setf(f), setf("G650", 1, "+="),
            if_([{"lvar": "G650", "op": "==", "rvar": 5}],
                [narrate("Five of the sick are eased. The Council must hear what is spreading. Objective: back to "
                         "Kyuden Isawa to report (the north road).")])]


def sick(ev, x, z, mdl, f, who, line, after, opts):
    """One of the sick (production S02 table): treatments are path actions and spells. Hand of Jurojin (G656) is
    cheaper than Path to Inner Peace once the dying healer has taught it."""
    base = [say(who, line), choices(*(opts + [("Not now.", [])]))]
    jur = [say(who, line), choices(*([("Hand of Jurojin (4 SP)", sp_cost(4, treated(f, "Hand of Jurojin: the fever "
                                                                                        "breaks, for now.")))] +
                                     opts + [("Not now.", [])]))]
    ev.talk(x, z, mdl, [(None, base), ([flag("G656"), flag(f, False)], jur), ([flag(f)], [say(who, after)])])


PTIP = lambda f: ("Path to Inner Peace (6 SP)", sp_cost(6, treated(f, "Water and quiet. The dark veins fade.")))  # noqa
MASS = lambda f: ("Path to Inner Peace, with Void (12 SP)", sp_cost(12, treated(f, "Path to Inner Peace, with Void: the "  # noqa
                                                                               "whole family breathes easier.")))
BLESS = lambda f, t: ("Bless (lead them to the temple hospital)", [narrate("Bless (Haruki's path action): " + t)] +  # noqa
                      treated(f, "At the temple hospital, they rest."))
REMEDY = ("Remedy (another traveler's art)", [narrate("Only a remedy will help here: Sayo's art, not Haruki's.")])


# ---- M288 Kyuden Isawa (S01; S03 the Council; S04 Hayato's circle; the sealed library after S06)
S03_PHX3 = cp3("S03") + [narrate("Objective: Doji Hayato's lodging, by the avenue.")]
S04_PHX3 = cp3("S04", stop_at="[SAVE]") + [
    say("Haruki", "Kuzushi. The unbalancing. The old records say it knocks people off their feet."),
    say("Hayato", "Then stand on something heavier than your feet. The temple-smith sells mountain charms."),
    narrate("(The Mountain's-Feet Charm, sold by the temple-smith, keeps its wearer from being knocked Off-Balance.)"),
    setf("G664"), SAVE_CHOICE, narrate("Objective: the Isawa Mori, east past the fever villages.")]


def kyuden_isawa():
    m = MapSpec("M288", "Kyuden Isawa", 110, 44, base=GRASS, y=3)
    m.rect(0, 14, 110, 5, ROAD, 3)
    building(m, 4, 21, 10, 6, wall=WOOD)                                    # the temple-smith
    building(m, 18, 21, 10, 6, wall=WOOD)                                   # the scroll shop
    building(m, 32, 21, 10, 6, wall=WOOD)                                   # the inn
    building(m, 46, 21, 10, 6, wall=PLASTER)                                # Hayato's lodging
    shrine(m, 62, 21)                                                       # the shrine of the five rings
    building(m, 70, 30, 14, 8, two_storey=True)                             # the Council hall
    building(m, 88, 31, 10, 7, wall=STONE)                                  # the sealed library
    fill(m, 100, 3, 31, 6, 16, 6, STONE)                                    # the Tower of Air
    for x in range(2, 110, 8):
        m.tree(x, 4 + (x * 3) % 5, (TREE_L, TREE_M)[x % 2])
    for x in (2, 16, 30, 44, 58, 72, 86, 100):
        fb(m, x, 19, 2, LAMP_STREET)
    ev = Events(m)
    ev.portal(1, 16, "M285", DOOR_EV.get(("M285", "isawa"), 62), d=1)      # event 1: the treaty road
    south = ev.portal(108, 16, "M289", 1, d=3)                              # event 2: the fever road
    ev.ev["#%d#" % south]["reqs0"] = [flag("G651")]
    lib = ev.portal(93, 29, "M296", 1, d=0)                                 # event 3: the sealed library (after S06)
    ev.ev["#%d#" % lib]["reqs0"] = [flag("G671")]
    ev.talk(93, 28, "CE000", [(None, [narrate("The sealed library. Bound shut; no one has opened it in a century.")]),
                              ([flag("G671")], [])], trigger=1)
    ev.scene(54, 16, "G651", S01_PHX3, after=[flag("G630")])
    ev.scene(76, 16, "G662", S03_PHX3, after=[flag("G660")])
    ev.prop(76, 28, SC["rujo"], reqs=[flag("G662", False)], d=2)
    ev.prop(72, 18, SC["hayato"], reqs=[flag("G662")], d=2)
    ev.talk(50, 19, "CE000", [(None, [narrate("Doji Hayato's lodging.")]),
                              ([flag("G662"), flag("G664", False)], S04_PHX3),
                              ([flag("G664")], [narrate("Hayato's maps, still spread on the floor, a ring of ink "
                                                        "around one house.")])], trigger=1)
    ev.clerk(9, 19, EP_SERVICE["merchant"], "R136")
    ev.inn(36, 19, EP_SERVICE["innkeeper"], 120)
    shrine_rites(ev, 62, 21, "The shrine of the five rings. Since the eclipse the kami here are hoarse.",
                 "Haruki kneels. The kami answer, the way the very ill answer: slowly.")
    ev.npc(24, 17, SC["acolyte"], "(An apprentice with ink on her fingers.) The Masters say it's dirt. My hands are "
                                  "clean and I still feel sick when the bell rings.")
    ev.npc(80, 17, SC["clerk"], "(A Council clerk.) Master Rujo will hear petitions after the eclipse rites. Which will "
                                "be never.")
    ev.npc(66, 17, SC["servant"], "(An old Master's servant.) My master sent his family north. I'm not supposed to say.")
    ev.talk(70, 17, SC["widow"], [(None, [say("Refugee", "My village is burning up and they say it's dirt. Will you "
                                                         "come? Will anyone?"),
                                          choices(("Bless her: walk her to the shrine.", [
                                              narrate("Bless (Haruki's path action): he walks her to the shrine of "
                                                      "the five rings, and she prays for the first time in days."),
                                              say("Refugee", "I'll go back with you. I know the road. Call on me."),
                                              setf("G663")]), ("Not now.", []))]),
                                  ([flag("G663")], [say("Refugee", "My village is the first on the road. Goemon's "
                                                                   "wife is very ill.")])], reqs=[flag("G651")])
    ev.npc(30, 17, SC["keiki"], "(An Asako monk with a cart of tea.) Rejuvenating tea for the healers. One cup each; "
                                "there isn't enough.")
    ev.npc(86, 17, SC["matsuduel"], "(A Lion envoy.) The Lion say the Phoenix brewed this fever. Prove them wrong, "
                                    "scholar.")
    ev.chest(40, 34, "N000", 1200)
    if "M297" in MAPS_LION:                                                 # Phoenix Ch4: the coast road
        coast = DOOR_EV[("M288", "coast")] = ev.portal(60, 1, "M297", 1, d=2)
        ev.ev["#%d#" % coast]["reqs0"] = [flag("G673")]
    return m, ev


