def fever_road_1():
    m = MapSpec("M289", "The fever road", 130, 36, base=GRASS, y=3)
    m.rect(0, 14, 130, 5, DIRT, 3)
    for x in (12, 24):
        building(m, x, 21, 8, 5, wall=WOOD)                                 # village 1
    building(m, 56, 21, 14, 7, wall=PLASTER)                                # the temple hospital
    for x in (88, 100, 112):
        building(m, x, 21, 8, 5, wall=WOOD)                                 # village 2
    for x in range(3, 130, 8):
        m.tree(x, 4 + (x * 5) % 6, (TREE_L, TREE_M)[x % 2])
    ev = Events(m)
    ev.portal(1, 16, "M288", 2, d=1)                                        # event 1: Kyuden Isawa
    ev.portal(128, 16, "M291", 1, d=3)                                      # event 2: on east (the ferry)
    ev.portal(63, 20, "M290", 1, d=0)                                       # event 3: the temple hospital
    ev.talk(3, 16, "CE000", [(None, []), ([{"lvar": "G650", "op": ">=", "rvar": 5}, flag("G660", False)], LEAVE)],
            trigger=5)
    sick(ev, 16, 19, SC["gonbei"], "G652", "Farmer Goemon", "My wife... can't see her own hands...",
         "She sees her hands again. She keeps looking at them.", [PTIP("G652"), REMEDY])
    sick(ev, 28, 19, SC["twin"], "G653", "Hana", "Mama says the dark goes away if I'm good. I've been very good.",
         "I'm still being good. Just in case.", [BLESS("G653", "Haruki carries Hana to the temple hospital.")])
    sick(ev, 92, 19, SC["oldwoman"], "G654", "Charcoal-burner", "Leave me. Treat the young ones.",
         "Stubborn of you. Thank you.", [BLESS("G654", "Haruki walks the old charcoal-burner to the temple hospital, "
                                                   "arguing all the way."), REMEDY])
    sick(ev, 104, 19, SC["priest"], "G655", "Village priestess", "My prayers bounce off it. Like rain off stone.",
         "My prayers land again. Some of them.", [MASS("G655")])
    sick(ev, 116, 19, SC["youth"], "G658", "Twin boys", "We share everything. Even this.",
         "We share being better, too.", [MASS("G658")])
    ev.chest(40, 10, "I018", 3)
    ev.chest(80, 10, "I131", 1)
    ev.npc(70, 17, SC["kitchengirl"], "The inns are hospitals now, Isawa-sama. There's no bed to rent anywhere on "
                                      "this road.")
    return m, ev


