def cp4(sid, **kw):
    return script_scene("phoenix-ch4", sid, **kw)


def dark4(cmds):
    """The production's MIEKO (DARK) lines: label them as the dark half."""
    return [dict(c, name="Mieko (dark)") if c.get("name") == "Isawa Mieko" else c for c in cmds]


S01_PHX4 = [narrate("CHAPTER 4 - Howl. (Recommended level 41)")] + cp4("S01", stop_at="[IF told_keiki]") + [
    if_([flag("G623")], [say("Keiki", "I watched her, as you asked. Every midnight. I'm sorry I wasn't enough.")]),
    if_([flag("G622"), flag("G623", False)], [say("Keiki", "You saw her at midnight, didn't you. In Treaty City. "
                                                            "You knew before any of us.")]),
    say("Hayato", "The Emerald Magistrates owe you a report with your name in it. They'll settle for me instead."),
    say("Hayato", "I'll walk you up the cliffs. Try not to fall off them. I'd have to write that down.")] + \
    join("P133", "Doji Hayato", [], lv=41) + [setf("G683"), SAVE_CHOICE,
                                              narrate("Objective: the red torii on the cliffs, by the cliff path north.")]
SAILOR = [narrate("Bless (Haruki's path action): guide someone, living or dead, a little way."),
          say("Haruki", "Show me where you're going, sailor. I'll walk with you."),
          narrate("The drowned sailor walks out along the jetty and points down into the water: a box, lashed to a "
                  "pile. Then he is gone.")] + got("A139", "an Orochi Scale") + [setf("G699"), setf("G700")]


def coast_town():
    m = MapSpec("M297", "The coast temple town", 110, 40, base=GRASS, y=3)
    m.rect(0, 0, 110, 9, WATER, 1)                                          # the storm sea
    m.rect(80, 0, 4, 11, PLANK, 3)                                          # the jetty
    m.rect(0, 14, 110, 5, DIRT, 3)
    building(m, 8, 22, 16, 8, two_storey=True)                              # the temple scriptorium
    building(m, 30, 22, 10, 6, wall=WOOD)                                   # the pilgrim inn
    building(m, 46, 22, 10, 6, wall=WOOD)                                   # the outfitter
    shrine(m, 64, 22)                                                       # the sea shrine
    for x in (4, 26, 44, 60, 76, 96):
        fb(m, x, 19, 2, LAMP_STREET)
    ev = Events(m)
    ev.portal(1, 16, "M288", DOOR_EV.get(("M288", "coast"), 59), d=1)      # event 1: the coast road
    cliff = ev.portal(108, 16, "M298", 1, d=3)                              # event 2: the cliff path
    ev.ev["#%d#" % cliff]["reqs0"] = [flag("G683")]
    ev.scene(54, 16, "G683", S01_PHX4, after=[flag("G673")])
    ev.prop(16, 20, SC["keiki"], reqs=[flag("G698", False)], d=2)
    ev.inn(34, 20, EP_SERVICE["innkeeper"], 150)
    ev.clerk(50, 20, EP_SERVICE["merchant"], "R137")
    shrine_rites(ev, 64, 22, "The sea shrine. The storm pulls at the paper prayers; they hold.",
                 "Haruki kneels. Under the wind, something in the sea is listening.")
    ev.npc(20, 17, SC["acolyte"], "(A copy-monk.) The thief came at night. She hummed while she took it.")
    ev.npc(40, 17, SC["netmender"], "(A fisherwife.) Eel, Isawa-sama? No? The storm will bring better tomorrow.")
    ev.npc(56, 17, SC["h_yojimbo"], "(A ronin guard.) There's a ledge on the cliff path. A shortcut, if you've the legs "
                                    "for it.")
    ev.npc(74, 17, SC["noboru"], "(A Shiba sentry.) Nobody goes up the cliffs in this. Nobody sensible.")
    ev.npc(88, 17, SC["oldwoman"], "(A storm-watcher.) Two wolves on the cliff, every night. One white, one black.")
    ev.npc(100, 17, SC["twin"], "(A child with a kite, in a storm.) It'll fly better when the wind is angry!")
    ev.prop(82, 6, "EP438", reqs=[flag("G699", False)], d=2)               # the drowned sailor's ghost
    ev.talk(82, 8, "CE000", [(None, [narrate("The jetty, slick with rain. A drowned sailor's ghost stands at the end of "
                                             "it, looking down."),
                                     choices(("Bless him.", SAILOR), ("Leave him.", []))]),
                             ([flag("G700")], [narrate("The jetty. Just rain now.")])], trigger=1)
    ev.chest(96, 26, "N000", 2000)
    ev.scene(54, 13, "G701", globals().get("S06_PHX4", []), after=[flag("G696")])     # S06 at dawn (defined below)
    return m, ev


# ---- M298-M299 the cliff path (S02: the shadows; the echoes of the gentle Mieko), M300 the last shrine
ECHOES = [("G685", "An echo of Mieko, tending wet camellias: \"They'll drown if I don't cover them...\"",
           [say("Haruki", "Let me help."), narrate("They cover the camellias together. She fades, smiling.")]),
          ("G686", "An echo of Mieko, singing a children's counting song: \"...fire, water, air, earth, void...\"",
           [say("Haruki", "...void."), narrate("He counts along on his fingers. She fades on the last word.")]),
          ("G687", "An echo of Mieko, writing the Consumer scroll by candlelight, weeping.",
           [say("Haruki", "You were so brave. To write a warning about yourself."), narrate("She fades, still "
                                                                                             "writing.")])]


def echo(ev, x, z, i):
    f, intro, lines = ECHOES[i]
    ev.prop(x, z, SC["mieko"], reqs=[flag(f, False)], d=2)
    ev.talk(x, z + 1, "CE000", [(None, [narrate(intro), choices(
        ("Bless her.", [narrate("Bless (Haruki's path action): guide someone, living or dead, a little way.")] + lines +
         [setf(f), setf("G684", 1, "+="), narrate("(Each echo Haruki blesses will stand between him and the dark "
                                                  "half's Void.)")]),
        ("Leave her.", []))]), ([flag(f)], [narrate("Where the echo stood, the rain falls a little softer.")])],
            trigger=1)


SHADOWS_A = cp4("S02", stop_at="[BATTLE b_mieko_shadows_a]") + [
    narrate("Mieko's shadows: they know every spell Haruki knows."), battle("M001", 87)] + \
    cp4("S02", start_at="HARUKI: (as a shadow", stop_at="### Echoes") + [setf("G688")]
SHADOWS_B = [narrate("More shadows, nearer the top of the cliff."), battle("M001", 88), setf("G689"),
             narrate("Objective: the last shrine, above.")]


def cliff_path_1():
    m = cave_map("M298", "The cliff path", 80, 36, rooms=[(8, 18, 6, 5), (30, 14, 10, 6), (54, 22, 9, 6),
                                                         (72, 16, 6, 5)],
                 links=[(13, 18, 22, 15, 4), (38, 16, 47, 21, 4), (60, 20, 68, 17, 4)], seed=61, floor=GRASS3,
                 wall=STONE)
    ev = Events(m)
    ev.portal(3, 18, "M297", 2, d=1)                                        # event 1: the town
    ev.portal(77, 16, "M299", 1, d=3)                                       # event 2: on up
    for x, z in ((30, 12), (34, 16)):
        ev.prop(x, z, "EP162", reqs=[flag("G688", False)], d=3)
    ev.scene(25, 15, "G688", SHADOWS_A, touch=True, after=[flag("G683")])
    echo(ev, 54, 21, 0)
    ev.chest(60, 24, "I131", 1)
    return m, ev


def cliff_path_2():
    m = cave_map("M299", "The cliff path - the shrines", 80, 36,
                 rooms=[(8, 18, 6, 5), (32, 18, 12, 7), (56, 8, 6, 4), (70, 20, 7, 6)],
                 links=[(13, 18, 21, 18, 4), (40, 15, 52, 9, 3), (43, 20, 64, 20, 4)], seed=62, floor=GRASS3,
                 wall=STONE)
    ev = Events(m)
    ev.portal(3, 18, "M298", 2, d=1)                                        # event 1: back down
    top = ev.portal(76, 20, "M300", 1, d=3)                                 # event 2: the last shrine (after b)
    ev.ev["#%d#" % top]["reqs0"] = [flag("G689")]
    echo(ev, 28, 17, 1)
    echo(ev, 36, 21, 2)
    for x, z in ((64, 18), (66, 22)):
        ev.prop(x, z, "EP162", reqs=[flag("G689", False)], d=3)
    ev.scene(60, 20, "G689", SHADOWS_B, touch=True, after=[flag("G688")])
    ev.talk(56, 7, "CE000", [(None, [narrate("A dead end, and a wrecked shrine-boat wedged in the rocks. Pearls in its "
                                             "offering box.")] + got("I240", "Pearl", 3) + [setf("G703")]),
                             ([flag("G703")], [narrate("The wrecked shrine-boat.")])], trigger=1)
    return m, ev


DREAMWALK = cp4("S03", stop_at="### SYSTEM") + [
    narrate("Dreamwalker: Haruki walks in Mieko's dream - the night they were both eight. Find what can be mended "
            "there. (Up to three dream keys; standing where the crack began wakes him.)")] + DARK + [go("M301", 18, 15)]


def last_shrine():
    def extra(m, ev):
        ev.prop(10, 6, SC["mieko"], reqs=[flag("G695", False)], d=0)        # asleep on the floor, the book beside her
        ev.talk(14, 5, "CE000", [(None, [narrate("A dry corner out of the storm. A place to rest before the dream."),
                                         SAVE_CHOICE])], trigger=1)
        ev.scene(10, 4, "G690", DREAMWALK, after=[flag("G689")])
    return castle_floor("M300", "The last shrine", 20, 8, [("candle", 3, 6), ("candle", 17, 6)],
                        down=("M299", 2), wall=STONE, extra=extra)


# ---- M301 the dream (S03: three keys), M302 the red torii (S04 the boss, S05 the choice)
DREAM_IN = cp4("S03", start_at="(The forest estate, twelve years ago", stop_at="### Dream keys") + [
    narrate("In the sunlight, the gentle Mieko. In the ash, the dark one. Where the crack began, a frozen boy.")]
KEY1 = [say("Haruki", "You wrote this. A warning."),
        say("Gentle Mieko", "...I wrote this? I don't - I was afraid of her. Of me."),
        setf("G692"), setf("G691", 1, "+="), narrate("(A dream key.)")]
KEY2 = [narrate("Haruki holds out the folded note. A child's brushwork: \"I'm sorry Mieko I didn't mean to please wake "
                "up.\""),
        say("Dark Mieko", "...You wrote this."), say("Dark Mieko", "...You were eight."),
        setf("G693"), setf("G691", 1, "+="), narrate("(A dream key.)")]
KEY3 = [say("Child-Haruki", "I'm sorry I'm sorry I'm sorry I didn't mean to-"),
        say("Haruki", "I know."), say("Haruki", "You don't have to say it anymore. I'll say it for both of us."),
        if_([flag("G679")], [narrate("Haruki sets the child's go stone on the dream board. \"I'm giving back the stone "
                                     "too.\"")]),
        setf("G694"), setf("G691", 1, "+="), narrate("The dream shudders. Haruki wakes.")] + DARK + [go("M302", 30, 18)]
BOSS_PHX4 = dark4(cp4("S04", stop_at="[BATTLE")) + [
    narrate("Her Void drains his. Each echo Haruki blessed stands between them once; each dream key loosened her."),
    if_([{"lvar": "G691", "op": ">=", "rvar": 3}], [battle("M001", 92)], [
        if_([{"lvar": "G691", "op": "==", "rvar": 2}], [battle("M001", 91)], [
            if_([{"lvar": "G691", "op": "==", "rvar": 1}], [battle("M001", 90)], [battle("M001", 89)])])]),
    setf("G695")]
JOIN = cp4("S05", start_at="HARUKI: (kneeling in front of her", stop_at="### SYSTEM")
CHOICE_PHX4 = dark4(cp4("S05", stop_at="> CHOICE")) + [choices(
    ("Strike the final blow.", [narrate("Haruki raises his staff. Stops. Lowers it."),
                                say("Haruki", "...No. Not again. I won't break you again.")] + dark4(JOIN)),
    ("Join the halves.", dark4(JOIN)))] + [
    narrate("Haruki gives part of his Void. (Void -1, for good. Passive \"Whole\": his Water heals also cleanse a "
            "debuff, and he can draw the Void twice in a battle.)"), setf("G696")] + \
    cp4("S05", start_at="(One Mieko kneels", stop_at='> CHOICE "Her answer"') + [choices(
        ("\"Someone who doesn't forgive you yet.\"", [setf("G697", 1),
                                                     say("Mieko", "Someone who doesn't forgive you. Yet."),
                                                     say("Haruki", "\"Yet\" is more than I ever hoped for.")]),
        ("\"Someone who remembers you were eight.\"", [setf("G697", 2),
                                                      say("Mieko", "Someone who remembers you were eight. And that I "
                                                                   "was cruel first. I took your stone."),
                                                      say("Haruki", "...You did take my stone.")]))] + DARK + \
    [go("M297", 54, 12)]


def dream_estate():
    m = MapSpec("M301", "The dream - the forest estate, twelve years ago", 60, 30, base=GRASS2, y=3)
    m.rect(0, 0, 28, 30, GRASS2, 3)                                         # the garden in sunlight
    m.rect(32, 0, 28, 30, DIRT, 3)                                          # the ash
    m.rect(28, 0, 4, 30, VOID, 2)                                           # the crack
    m.rect(28, 12, 4, 6, PLANK, 3)                                          # ... and a way over it
    for x, z in ((6, 6), (14, 22), (22, 4)):
        m.tree(x, z, TREE_S)
    ev = Events(m)
    ev.scene(18, 14, "G702", DREAM_IN, after=[flag("G690")])     # arrive in the garden, not in the crack (user)
    ev.prop(10, 14, SC["mieko"], d=2)                                       # the gentle Mieko, arranging flowers
    ev.talk(10, 15, "CE000", [(None, [say("Gentle Mieko", "The camellias need covering before the rain. Do you know "
                                                          "who I am? I don't.")]),
                              ([{"lvar": "G629", "op": "==", "rvar": True}, flag("G692", False)], [
                                  say("Gentle Mieko", "The camellias need covering before the rain."),
                                  choices(("Show her the warning she wrote.", KEY1), ("Not yet.", []))]),
                              ([flag("G670"), flag("G692", False)], [
                                  say("Gentle Mieko", "The camellias need covering before the rain."),
                                  choices(("Show her the warning she wrote.", KEY1), ("Not yet.", []))]),
                              ([flag("G692")], [say("Gentle Mieko", "I was afraid of her. I think I still am.")])])
    ev.prop(48, 14, "EP162", d=2)                                           # the dark Mieko on the broken go board
    ev.talk(48, 15, "CE000", [(None, [say("Dark Mieko", "Little Void. In my dream, uninvited. Rude.")]),
                              ([flag("G587"), flag("G693", False)], [
                                  say("Dark Mieko", "Little Void. In my dream, uninvited. Rude."),
                                  choices(("Show her the note.", KEY2), ("Not yet.", []))]),
                              ([flag("G693")], [say("Dark Mieko", "...Go away. I'm thinking.")])])
    ev.prop(30, 12, "EP204", d=2)                     # the frozen child-Haruki at the bridge's edge (the way stays open)
    ev.talk(30, 13, "CE000", [(None, [narrate("Where the crack began: a frozen boy, mid-scream, Void pouring from his "
                                              "hands."),
                                      choices(("Kneel beside him. (The dream will end.)", KEY3), ("Not yet.", []))])],
            trigger=1)
    return m, ev


def red_torii():
    m = MapSpec("M302", "The red torii on the cliff", 60, 30, base=STONE, y=3)
    m.rect(0, 0, 60, 8, WATER, 1)                                          # the sea below the cliff
    for x in (26, 34):
        fill(m, x, 3, 10, 1, 6, 1, DARKWOOD)                                # the red torii
    fill(m, 24, 9, 10, 13, 1, 1, DARKWOOD)
    fill(m, 25, 8, 10, 11, 1, 1, DARKWOOD)
    ev = Events(m)
    ev.portal(2, 18, "M300", 1, d=1)                                        # event 1: back to the shrine
    ev.prop(30, 12, SC["mieko"], reqs=[flag("G695", False)], d=2)
    ev.scene(30, 16, "G704", BOSS_PHX4, after=[flag("G694")])
    ev.scene(30, 15, "G705", CHOICE_PHX4, after=[flag("G695")])
    return m, ev


def battle_cliffs():
    m = MapSpec("M848", "Battle: the cliffs in the storm", 128, 128, base=STONE, y=0)   # height 0
    m.rect(0, 96, 128, 32, WATER, 0)                                        # the sea far below
    for x in range(10, 128, 22):
        fill(m, x, 0, 90, 2, 3, 2, STONEW)                                  # little cliff shrines
    return m


def battle_torii():
    m = MapSpec("M849", "Battle: the red torii", 128, 128, base=STONE, y=0)   # height 0
    m.rect(0, 100, 128, 28, WATER, 0)
    for x in (58, 70):
        fill(m, x, 0, 94, 1, 7, 1, DARKWOOD)
    fill(m, 56, 7, 94, 17, 1, 1, DARKWOOD)
    return m


# ---- S06 the ending (the coast town at dawn)
S06_PHX4 = cp4("S06", stop_at="[ITEM") + got("I177", "\"Against the Bloodspeakers\"") + [
    narrate("\"Howl\" - complete."),
    narrate("Haruki walked through the night he broke Mieko, met both halves of her, and gave up part of his own Void "
            "to make her whole. She doesn't forgive him - yet. She does want to help hunt the Bride of Fu Leng."),
    leave("P133"), say("Hayato", "My report will say \"the Isawa\" again. You'll like it."),
    setf("G698"), narrate("The Phoenix path is complete.")]


BATTLE_SPECS.update({"M848": battle_cliffs, "M849": battle_torii})
INTERIORS.update({"M300": last_shrine})
MAPS_LION.update({"M297": coast_town, "M298": cliff_path_1, "M299": cliff_path_2, "M300": last_shrine,
                  "M301": dream_estate, "M302": red_torii, "M848": battle_cliffs, "M849": battle_torii})


# ======================================================================================== Dragon Ch1 "Under the Skin"
# production/dragon-ch1.md, storyboards/dragon-ch1.md, scripts/dragon-ch1-under-the-skin.md. Kitsuki Gendo the
# starter (G706), alone until Togashi Yosai joins at the dump (S03: his story home; companion P132). The Mantis ship
# M303, the Isle of Silk M304, Yoritomo's hall M305, the guest house M306, the dump M307, the Rakusho school M308, the
# silk hill path M309, the Gusai ruins M310-M312, the boathouse M313, Tortoise beach M314; backdrops M850 (the docks),
# M851 (the ruins), M852 (the beach and the tide).
def dp1(sid, **kw):
    return script_scene("dragon-ch1", sid, **kw)


FULL_NAMES.update({"Oharu": "Kitsuki Oharu", "Momo": "Kitsuki Momo", "Kumpei": "Kakita Kumpei",
                   "Riichi": "Riichi", "Kosai": "Kosai", "Tadayasu": "Tadayasu", "Yoritomo": "Yoritomo"})


def discern(info, after=()):
    """Gendo's path action: Discern an NPC (a choice) -> what they hide."""
    return ("Discern (Gendo's path action)", [narrate("Discern: " + info)] + list(after))


# ---- M303 the Mantis ship (S01: the Discern tutorial; the dock brawl b_dock_tutorial)
DOCK = dp1("S01", start_at="GENDO: (to the captain", stop_at="[BATTLE") + [
    narrate("Deduce: Gendo's School technique. It reveals an enemy's weaknesses and its next action. (Battle menu: School.)"),
    battle("M001", 93)] + dp1("S01", start_at="GENDO: (after)", stop_at="[SAVE]") + [
    setf("G709"), SAVE_CHOICE] + DARK + [go("M305", 12, 4, padded=False)]
S01_DGN1 = [narrate("CHAPTER 1 - Under the Skin.")] + dp1("S01", stop_at="### TUTORIAL") + [
    narrate("Discern: Gendo's path action. Study someone to learn what they hide. Discern the ship's captain.")]


def mantis_ship():
    m = MapSpec("M303", "A Mantis trading ship", 60, 30, base=WATER, y=1)
    m.rect(8, 8, 44, 14, PLANK, 3)                                          # the deck
    for x in range(8, 52):
        m.rect(x, 8, 1, 1, DARKWOOD, 4), m.rect(x, 21, 1, 1, DARKWOOD, 4)  # the rails
    m.rect(4, 11, 4, 8, DARKWOOD, 3)                                        # the bow
    fill(m, 26, 4, 18, 1, 12, 1, DARKWOOD)                                  # the mast
    fill(m, 21, 9, 19, 11, 6, 1, PLASTER)                                   # the sail
    ev = Events(m)
    ev.scene(30, 14, "G707", S01_DGN1, after=[flag("G706")])
    ev.prop(24, 12, SC["oharu"], reqs=[flag("G709", False)], d=2)
    ev.talk(40, 14, SC["mcaptain"], [
        (None, [say("Mantis captain", "Silk, magistrate-sama. Only silk. Very light, silk."),
                choices(discern("The captain is smuggling Mantis rice past a Crane tariff. Nervous. Not dangerous.",
                                [setf("G708")] + DOCK), ("Leave him.", []))]),
        ([flag("G708")], [say("Mantis captain", "Please don't tell the Yoritomo.")])])
    ev.chest(16, 18, "I100", 3)
    return m, ev


def battle_docks():
    m = MapSpec("M850", "Battle: the Silk docks", 128, 128, base=PLANK, y=0)   # fighters stand at height 0
    m.rect(0, 96, 128, 32, WATER, 0)                                        # the harbour behind
    for x in range(8, 128, 20):
        fill(m, x, 0, 88, 3, 2, 3, WOOD)                                    # crates on the quay
    return m


# ---- M305 Yoritomo's hall, M306 the guest house (S02: hospitality; the poisoned tea; the seal)
HALL = dp1("S02", stop_at="(Night. The guest house") + [setf("G710")] + DARK + \
    [go("M306", 10, 4, padded=False)]
POISON = dp1("S02", start_at="(Night. The guest house", stop_at="[SET oharu_poisoned]") + \
    got("I178", "Oharu's Seal") + [setf("G711")] + dp1("S02", start_at="(Morning. Tadayasu", stop_at="[SAVE]") + [
    SAVE_CHOICE, narrate("Objective: the dump above the sea, where the body was found. (Out through the town, west.)")]


def yoritomo_hall():
    def extra(m, ev):
        ev.prop(16, 9, SC["yoritomo"], d=0)
        ev.prop(20, 9, SC["tadayasu"], d=0)
        ev.prop(12, 6, SC["oharu"], reqs=[flag("G710", False)], d=0)
        ev.scene(12, 4, "G710", HALL, after=[flag("G709")])
    return castle_floor("M305", "The Isle of Silk - Yoritomo's hall", 28, 10, [("dais", 12, 9, 10, 2),
                                                                               ("candle", 3, 9), ("candle", 25, 9)],
                        down=("M304", 3), extra=extra)


def guest_house():
    def extra(m, ev):
        ev.prop(14, 7, SC["oharu"], d=0)                                     # on cushions, recovering
        ev.scene(10, 5, "G711", POISON, after=[flag("G710")])
        ev.scene(8, 5, "G727", S08_DGN1, after=[flag("G726")])              # S08: back from the beach
        ev.talk(14, 6, "CE000", [(None, [say("Oharu", "Go and look, Gendo. I'll lie here and be poisoned.")]),
                                 ([flag("G726")], [])])
        ev.inn(5, 7, EP_SERVICE["innkeeper"], 20)
    return castle_floor("M306", "The Isle of Silk - the guest house", 20, 8, [("futon", 13, 6), ("candle", 3, 2)],
                        down=("M304", 4), extra=extra)


# ---- M304 the Isle of Silk (town)
def silk_docks():
    m = MapSpec("M304", "The Isle of Silk", 110, 44, base=SAND, y=3)
    m.rect(0, 0, 110, 9, WATER, 1)                                          # the harbour
    for x in (20, 64):
        fill(m, x, 3, 2, 4, 1, 7, PLANK)                                    # piers
    ship(m, 70, 2, n=14)                                                    # the trade junk
    m.rect(0, 14, 110, 5, PLANK, 3)                                         # the waterfront
    building(m, 6, 22, 14, 8, two_storey=True)                              # Yoritomo's hall
    building(m, 26, 22, 10, 6, wall=WOOD)                                   # the guest house
    building(m, 42, 22, 10, 6, wall=WOOD)                                   # the Rakusho school
    building(m, 58, 22, 10, 6, wall=WOOD)                                   # the chandler
    building(m, 92, 22, 10, 6, wall=DARKWOOD)                               # the boathouse
    for x in (4, 24, 40, 56, 76, 90, 104):
        fb(m, x, 19, 2, LAMP_STREET)
    ev = Events(m)
    ev.portal(1, 16, "M307", 1, d=1)                                        # event 1: the dump (west)
    hill = ev.portal(108, 16, "M309", 1, d=3)                               # event 2: the silk hill path (after S04)
    ev.ev["#%d#" % hill]["reqs0"] = [flag("G713")]
    ev.portal(13, 21, "M305", 1, d=0)                                       # event 3: Yoritomo's hall
