def winter_cherry(m, x, z, h=6):
    """A bare cherry in winter (blocks): dark trunk, crossed branches, snow on the forks."""
    y0 = int(m.hgt[z, x])
    top = y0 + h
    fill(m, x, y0 + 1, z, 1, h, 1, DARKWOOD)                                # the trunk
    for dx, dz, up in ((-1, 0, 0), (-2, 0, 1), (-3, 0, 2), (1, 0, 1), (2, 0, 2), (0, 1, 1), (0, 1, 2), (1, 1, 3),
                       (0, -1, 1), (-1, -1, 2), (0, 0, 1), (0, 0, 2)):
        fill(m, x + dx, top + up, z + dz, 1, 1, 1, DARKWOOD)                # bare, crooked branches
    for dx, dz, up in ((-3, 0, 3), (2, 0, 3), (1, 1, 4), (-1, -1, 3), (0, 0, 3)):
        fill(m, x + dx, top + up, z + dz, 1, 1, 1, PLASTER)                 # snow on the twig ends


