def tortoise_village():
    m = MapSpec("M315", "Tortoise Island", 110, 44, base=SAND, y=3)
    m.rect(0, 0, 110, 8, WATER, 1)                                          # the grey sea
    fill(m, 20, 3, 1, 4, 1, 7, PLANK)                                       # the ferry pier
    for x, z, n in ((40, 2, 6), (58, 3, 5), (86, 2, 6)):
        fill(m, x, 1, z, n, 2, 3, DARKWOOD)                                 # fishing boats
    m.rect(0, 11, 110, 5, DIRT, 3)                                          # the shore lane
    m.rect(0, 30, 36, 14, GRASS, 5)                                         # the hill (the new house)
    m.rect(28, 26, 6, 2, DIRT, 4)                                           # its steps
    m.rect(28, 28, 6, 2, DIRT, 5)
    m.rect(76, 24, 34, 20, GRASS, 5)                                        # the ridge (the dojo)
    m.rect(78, 20, 4, 2, DIRT, 4)
    m.rect(78, 22, 4, 2, DIRT, 5)
