def cove_2():
    m = cave_map("M319", "The Tortoise cove - the clay city", 80, 36,
                 rooms=[(8, 18, 6, 5), (36, 18, 14, 9), (62, 10, 6, 4), (70, 22, 7, 5)],
                 links=[(13, 18, 22, 18, 4), (44, 13, 58, 11, 3), (48, 20, 64, 22, 4)], seed=82, floor=SAND,
                 wall=STONE)
    for gx in range(-12, 13, 3):                                           # the miniature capital: 2x2 houses on a
        for gz in range(-7, 8, 3):                                          # grid (lanes between), older inward:
            ring = max(abs(gx) / 12.0, abs(gz) / 7.0)                       # tile roofs on plaster at the edge, then
            wall, roof = ((PLASTER, ROOF) if ring > 0.66 else (WOOD, DARKWOOD) if ring > 0.3 else  # wood, then
                          (DIRT, MATTING))                                  # mud and thatch at the centre
            fill(m, 36 + gx, 3, 18 + gz, 2, 1, 2, wall)
            fill(m, 36 + gx, 4, 18 + gz, 2, 1, 2, roof)
    ev = Events(m)
    ev.portal(3, 18, "M318", 2, d=1)                                        # event 1: back
    ev.portal(75, 22, "M320", 1, d=3)                                       # event 2: the portal
    ev.scene(22, 18, "G767", CITY_DGN2)
    ev.talk(35, 21, "CE000", [(None, [narrate("The clay city: tile roofs at the edge, thatch at the centre."),
                                      choices(discern("Each ring is a century. The centre is the year four hundred. "
                                                      "Someone made a map of when.", [setf("G756")]),
                                              ("Leave it.", []))]),
                              ([flag("G756")], [narrate("A map of when. The centre is the year four hundred.")])],
            trigger=1)
