BAD_FUTURE = [narrate("The World That Should Not Be: a capital with no Kitsuki courts. A Crane-blue eye in a Lion's "
                      "face. A wall that was never built, and the Shadowlands walking in through the gap."),
              narrate("The ink pulls Gendo back, gasping, to the moment before. (History: 30%.)"),
              setf("G748", 30), setf("G787"), script("::Rokugan.historyHUD();")]


def hist(delta):
    """Move the History meter (G748) and show it; at 0 the bad future plays and Gendo is pulled back."""
    return [setf("G748", delta, "+="), script("::Rokugan.historyHUD();"),
            narrate("History %s%d%%." % ("+" if delta > 0 else "", delta)),
            if_([{"lvar": "G748", "op": "<=", "rvar": 0}], BAD_FUTURE)]


def spectacles(dest, name):
    """A noble's door (F-2): take the spectacles off (Discern is harder inside) or keep them on (History -2)."""
    return [narrate("The door of %s." % name),
            choices(("Take off the spectacles.", [narrate("Gendo folds his spectacles away. The room will be a blur of "
                                                          "polite shapes.")] + DARK + [go(dest, 6, 5, padded=False)]),
                    ("Keep them on.", hist(-2) + DARK + [go(dest, 6, 5, padded=False)]),
                    ("Not now.", []))]


def house_exit(ev, town, x, z):
    """A castle-floor front door (custom: noble doors are talk events, not portals) back out into the town."""
    ev.talk(2, 2, "CE000", [(None, DARK + [go(town, x, z)])], trigger=5)


