def palace_400():
    m = MapSpec("M326", "Otosan Uchi - the palace (the year 400)", 100, 40, base=GRASS, y=3)
    m.rect(0, 12, 100, 5, STONEW, 3)                                         # the garden walk
    building(m, 30, 30, 30, 8, two_storey=True)                              # the palace hall (the war council)
    m.rect(10, 20, 12, 6, WATER, 1)                                          # the carp pond (frozen at the edges)
    for x, z in ((8, 28), (24, 22), (66, 22), (74, 28), (88, 24)):
        winter_cherry(m, x, z, h=6)
    fill(m, 80, 4, 22, 2, 1, 2, STONEW)                                      # the palace well
    for x in (6, 28, 62, 84):
        fb(m, x, 17, 2, LAMP_STREET)
    ev = Events(m)
    ev.portal(1, 14, "M325", 2, d=1)                                         # event 1: the streets (west)
    ev.portal(98, 14, "M322", 1, d=3)                                        # event 2: the winter orchard (east)
    ev.scene(50, 14, "G769", S01_DGN3, after=[flag("G752")])
    ev.prop(52, 16, SC["kusada"], reqs=[flag("G782", False)], d=2)
    ev.talk(45, 29, "CE000", [(None, [narrate("The palace hall. The war council meets behind these doors, and nobody "
                                              "has called for Gendo-of-no-family.")]),
                              ([flag("G779")], spectacles("M332", "the palace hall (the war council)"))], trigger=1)
    ev.talk(40, 14, SC["seppunguard"], [
        (None, [say("Palace guard", "His Majesty likes you. Be careful with that. The gozoku don't like what he "
                                    "likes.")]),
        ([flag("G771"), flag("G772", False)], [say("Palace guard", "You're asking after Seppun Ushimo? ...")] +
         TIP_DGN3),
        ([flag("G772")], [say("Palace guard", "South gate. The house with the closed shutters.")])])
    ev.npc(58, 14, SC["courtier"], "A court lady never runs. She hurries, beautifully.")
    ev.talk(80, 20, "CE000", [(None, [narrate("The palace well. Someone has hidden a purse on the ledge, below the "
                                              "rim.")] + [{"cmd": "cmd_moneyop", "op": 0, "amount": 1500},
                                                          narrate("Got 1500 zeni."), setf("G797")]),
                              ([flag("G797")], [narrate("The palace well.")])], trigger=1)
    ev.talk(36, 29, "CE000", [(None, [narrate("A palace window, lit late.")]),
                              ([{"lvar": "G770", "op": "==", "rvar": 3}, flag("G792", False)], SANRO_WINDOW)],
            trigger=1)
    return m, ev


