# ---- M340 the harbour tunnels (S03), M341 the flagship (S04)
S03_DGN4 = dp4("S03", stop_at="[BATTLE") + [narrate("Gunpowder barrels line the tunnels. Using one: History -5%.")]
BARREL_DGN4 = dp4("S03", start_at="TOGASHI YOSAI: (eyeing a barrel)", stop_at="[SAVE]") + [
    choices(("Use one anyway: blow the rubble from the side passage. (History -5)",
             [setf("G811"), narrate("The barrel goes up. So does the rubble. Behind it: a smuggler's side "
                                    "passage.")] + hist(-5)),
            ("Walk past it.", []))]


def harbour_tunnels():
    m = cave_map("M340", "The harbour tunnels (the year 400)", 80, 34,
                 rooms=[(8, 17, 6, 5), (30, 15, 10, 6), (54, 18, 10, 6), (72, 15, 6, 5), (40, 4, 5, 3)],
                 links=[(13, 17, 22, 15, 4), (38, 16, 46, 18, 4), (62, 17, 68, 15, 4), (33, 11, 40, 5, 3)], seed=95,
                 floor=STONEW, wall=STONE)
    for x, z, w, d in ((24, 18, 4, 2), (48, 22, 6, 2)):
        m.rect(x, z, w, d, WATER, 1)                                        # the sea in the floor, and sharks below
    ev = Events(m)
    ev.portal(3, 17, "M337", 1, d=1)                                        # event 1: the war camp
    ev.portal(77, 15, "M341", 1, d=3)                                       # event 2: the gangway (the flagship)
    ev.scene(8, 17, "G809", S03_DGN4)
    ev.scene(54, 18, "G810", [battle("M001", 108), setf("G810")], touch=True)
    ev.talk(33, 13, "CE000", [(None, BARREL_DGN4), ([flag("G811")], [narrate("An empty barrel.")])], trigger=1)
    ev.talk(41, 4, "CE000", [(None, [narrate("Rubble to the roof, and behind it the smell of a smuggler's cache.")]),
                             ([flag("G811")], [narrate("A Mantis smuggler's cache.")] +
                              got("%s" % item_named("Storm Legion Token"), "a Storm Legion Token") +
                              got("I240", "Pearl", 2) + [setf("G812")]),
                             ([flag("G812")], [narrate("The empty cache.")])], trigger=1)
    save_shrine(m, ev, 70, 17)                                              # F-3: the gangway save
    ev.chest(30, 19, "I190", 2)
    return m, ev


S04_DGN4 = dp4("S04", stop_at="[BATTLE") + [
    narrate("The cannons fire on a timer. Break Kumpei before the 8th round, or he hurls the vial overboard."),
    battle("M001", 109), setf("G813"),
    if_([flag("G815")], got("I194", "the Kami-ichor Vial"),
        [narrate("Togashi Yosai surfaces from the harbour with the vial in his teeth. It's cracked; most of it is gone.")]),
    say("Kakita Kumpei", "(sinking to his knees, brush in hand) ...It's a very beautiful year, 1122. I saw it in your "
                         "eyes when you arrived."),
    choices(("Spare him. Let him paint us home.", [setf("G814")] +
             dp4("S04", start_at="      KAKITA KUMPEI: (weeping, painting)", stop_at='  - "Give him')),
            ("Give him to the Emperor's guards.", [narrate("He paints the way home under guard.")]))] + DARK + [
    go("M342", 10, 5, padded=False)]


def flagship():
    m = MapSpec("M341", "The gaijin flagship (the year 400)", 60, 30, base=WATER, y=1)
    m.rect(6, 8, 48, 14, PLANK, 3)
