    building(m, 18, 23, 12, 6, wall=DARKWOOD)                               # the outfitter
    building(m, 34, 23, 10, 6, wall=WOOD)                                   # the apothecary
    building(m, 48, 23, 14, 7, wall=PLASTER)                                # the theatre
    building(m, 66, 23, 12, 6, wall=WOOD)                                   # the inn
