def traitors_grove():
    m = MapSpec("M348", "Traitor's Grove", 96, 32, base=GRASS3, y=3)
    m.rect(0, 12, 96, 5, ROAD, 3)
    for x in range(20, 76, 3):                                              # the grove: dark, close trees (behind
        for z in (21, 24, 27, 30):                                          # the road; the camera side stays open)
            if (x * 7 + z) % 5 < 3:
                m.tree(x + (z % 2), z, (TREE_L, TREE_M)[(x + z) % 2])
    for x in range(22, 72, 6):
        m.tree(x, 4 + x % 3, TREE_S)                                        # low scrub on the camera side
    for i, (x, z) in enumerate(((24, 19), (30, 20), (36, 19), (42, 20), (48, 19), (54, 20), (60, 19),
                                (26, 10), (34, 9), (44, 10), (52, 9), (62, 10), (68, 9))):
        fill(m, x, 4, z, 1, 4, 1, DARKWOOD)                                 # the posts (Mitsue doesn't count them)
    ev = Events(m)
    ev.portal(1, 14, "M347", 1, d=1)                                        # event 1: the castle town
    ev.portal(94, 14, "M349", 1, d=3)                                       # event 2: Shutai
    ev.scene(16, 14, "G869", S03_SCP1, touch=True, after=[flag("G839")])
    ev.scene(74, 14, "G840", S03_BANDITS, touch=True, after=[flag("G869")])
    for x, k in ((77, "road_bandit"), (79, "road_bandit"), (78, "road_bandit")):
        ev.prop(x, 13 + (x % 3), EP_HE[k], reqs=[flag("G840", False)], d=1)
    ev.talk(48, 21, "CE000", [
        (None, [narrate("A chained traitor's purse, still on his belt. Still full."),
                choices(("Take it.", [{"cmd": "cmd_moneyop", "op": 0, "amount": 80},
                                      narrate("80 zeni. A hiss from the nearest tree. And now that she looks: every "
                                              "mask and helmet in the grove has turned to face south."), setf("G841")]),
                        ("Leave it.", [narrate("Mitsue leaves it. The grove keeps what it keeps.")]))]),
        ([flag("G841")], [narrate("The empty chain. Every mask faces south.")])], trigger=1)
    ev.chest(70, 26, "I101", 1)
    return m, ev


# ---- M349 Shutai (the border town: "a wretched hive" on the flood-plain; Noburo; Megu's room)
def shutai():
    m = MapSpec("M349", "Shutai", 104, 40, base=DIRT, y=3)
    m.rect(0, 0, 104, 6, WATER, 1)                                          # the River of Gold
    m.rect(0, 14, 104, 6, ROAD, 3)
    for x, z in ((10, 9), (40, 8), (70, 10), (22, 24), (58, 25), (90, 9)):
        m.rect(x, z, 4, 2, WATER, 2)                                        # puddles: the flood-plain underfoot
    for x, z, w in ((4, 23, 10), (18, 23, 12), (34, 23, 10), (48, 23, 12), (64, 23, 10), (78, 23, 12),
                    (8, 30, 8), (30, 31, 10), (60, 31, 8), (84, 31, 10)):
        building(m, x, z, w, 5, wall=(WOOD, DARKWOOD)[x % 2])               # ramshackle, no plan
    for x in range(2, 104, 6):
        fill(m, x, 3, 6, 2, 1, 3, PLANK)                                    # rotten jetties
    ev = Events(m)
    ev.portal(1, 17, "M348", 2, d=1)                                        # event 1: the grove road
    ev.portal(102, 17, "M350", 1, d=3)                                      # event 2: the river road south
    ev.inn(24, 21, EP_SERVICE["innkeeper"], 30)
    ev.talk(28, 21, SC["innkeeper"], [
        (None, [say("Innkeeper", "Two murders this month. Both travellers from Kudo."),
                choices(eavesdrop("Innkeeper", 70, "Later, to his wife, low: \"Both of them bloodless. Not a drop "
                                  "left in them. Like the woman at Megu's.\"", "G844"), ("Leave him.", []))]),
        ([flag("G844")], [say("Innkeeper", "Bloodless. I said nothing. Rooms are thirty.")])])
    ev.clerk(54, 21, EP_SERVICE["merchant"], "R146")
    ev.talk(40, 18, SC["noburo"], [
        (None, [narrate("A nondescript man in grey has been three steps behind her since the gate. She steps into "
                        "a doorway; he walks straight into her."),
                say("Noburo", "...Ah. A Shosuro. Of course you're a Shosuro. Shosuro Noburo. I watch the interesting "
                              "newcomers."),
                say("Noburo", "Fourteen days ago: ghastly murders at Megu's sake house. The same days the Miya caravan "
                              "came through. A man cut a woman's throat, drew in her blood, and died beside it without "
                              "a mark."),
                say("Mitsue", "And the magistrates?"),
                say("Noburo", "Called it a bad night in Shutai. It's a town of bad nights. Megu will show you the room "
                              "for two bu."), setf("G842")]),
        ([flag("G842")], [say("Noburo", "I'm not here. You never saw me. Neither did anyone else, which is the "
                                        "job.")])])
    ev.talk(70, 21, SC["megu"], [
        (None, [say("Megu", "A room is two bu, with or without a geisha. Talking is five."),
                choices(("Pay for the room. (20 zeni)",
                         [if_([{"lvar": "MONEY", "op": ">=", "rvar": 20}],
                              [{"cmd": "cmd_moneyop", "op": 1, "amount": 20},
                               narrate("A dingy room upstairs. Cleaned, after a fashion. Old blood in a spatter, and "
                                       "more of it gathered on one patch of floor, in a pattern."),
                               say("Mitsue", "(crouching) Lines. Circles. A summoning. Half-finished. Somebody tried "
                                             "to call something through this floor, and paid with two lives, and "
                                             "failed."),
                               say("Mitsue", "...So it tried again further south."), setf("G843")],
                              [say("Megu", "No coin, no room. No room, no ghosts.")])]),
                        ("Leave.", []))]),
        ([flag("G843")], [say("Megu", "You didn't see anything up there. Nobody does. It's a very clean room.")])])
    ev.talk(86, 18, SC["priest"], [(None, [say("Priest", "The river's gone a strange colour upstream. Toward Kudo. "
                                                         "Brown, then red at dusk."), setf("G874")])])
    ev.npc(12, 18, EP_HE["hungry_ronin"], "Kudo pays well for swords. Too well. That's how you know.")
    ev.npc(96, 21, SC["drunksailor"], "The magistrates walk at the third bell. Every night. You can set a lamp by "
                                      "them. The thieves do.")
    shrine(m, 64, 31)
    shrine_rites(ev, 64, 31, "A shrine to Jurojin, the Fortune of long life. The priest says he lifts the grove's "
                             "curses, for a price.", "Mitsue sits until the river noise goes away.")
    ev.chest(100, 34, "I100", 2)
    return m, ev


# ---- M350 the River of Gold road (Shutai -> Kudo; bestiary F "Scorpion south & Kudo")
