def marsh_ground(m, seed, track=(12, 18)):
    rng = np.random.default_rng(seed)
    for _ in range(60):
        x, z = int(rng.integers(2, m.w - 6)), int(rng.integers(2, m.d - 6))
        if track[0] - 4 <= z <= track[1]:
            continue
        kind = (WATER, TARSTAIN, GRASS3)[_ % 3]                              # pools, stained mud, sick grass
        m.rect(x, z, int(rng.integers(2, 7)), int(rng.integers(2, 5)), kind, 2 if kind == WATER else 3)
    for _ in range(26):
        x, z = int(rng.integers(1, m.w - 1)), int(rng.integers(1, m.d - 1))
        if int(m.blk[z, x]) != WATER and not (track[0] - 1 <= z <= track[1]):
            m.tree(x, z, (TREE_S, TREE_M, ROCK_S)[_ % 3])


