def soshi_camp():
    m = MapSpec("M371", "The Soshi camp before Shiro no Soshi", 104, 40, base=DIRT, y=3)
    m.rect(0, 13, 104, 5, ROAD, 3)
    fill(m, 30, 4, 32, 50, 9, 6, STONEW)                                    # the grey walls of Shiro no Soshi
    for x in range(30, 80, 7):
        fill(m, x, 13, 31, 4, 2, 4, ROOF)
    for x, z in ((8, 21), (18, 22), (84, 21), (94, 22)):
        tent(m, x, z)
    tent(m, 60, 20, w=8, d=6)                                               # the general's white tent
    for x, z in ((12, 6), (26, 4), (44, 7), (64, 5), (82, 6)):
        m.rect(x, z, 5, 3, SL_GROUND, 3)                                    # the refugees' fires, trodden earth
    ev = Events(m)
    ev.portal(56, 12, "M369", 3, d=2)                                       # event 1: back north to Buried Leaves
    ev.scene(52, 15, "G925", SEPPUKU, after=[{"lvar": "G924", "op": ">=", "rvar": 3}, flag("G967", False)])
    ev.campfire(24, 18)
    ev.talk(22, 19, SC["soshiofficer"], [
        (None, [narrate("Soshi officers round a fire, talking low."),
                if_([flag("G919")], [choices(
                    eavesdrop("Soshi officer", 70, "\"The Iuchi kept our men in Jiochi for questioning. Hands of Jurojin "
                              "ready, so nobody could take the easy way. So we took the well. Oleander, from the "
                              "castle gardens.\"", "G938", grievance("G920")),
                    ("Many Faces: pour their sake. (Bribe the real servant: 300 zeni.)",
                     [if_([{"lvar": "MONEY", "op": ">=", "rvar": 300}],
                          [{"cmd": "cmd_moneyop", "op": 1, "amount": 300},
                           narrate("A servant's apron, a servant's bow. Sake makes officers careless."),
                           narrate("\"...the well at Jiochi. Oleander, from the castle gardens. It silenced our own "
                                   "men too. Better that than what the Iuchi were getting out of them.\"")] +
                          grievance("G920"),
                          [narrate("The servant wants 300 zeni for her apron.")])]),
                    ("Leave them.", []))])]),
        ([flag("G920")], [say("Soshi officer", "More sake, girl. Have we met?")])])
    ev.talk(86, 18, SC["clerk"], [
        (None, [narrate("The Soshi quartermaster, counting rice that isn't there."),
                if_([flag("G919")], [choices(
                    eavesdrop("Quartermaster", 75, "The rolls on his table: Bayushi and Shosuro troops, two hundred, "
                              "under Soshi banners. Neither family was named in the petition for war.", "G941",
                              grievance("G923")),
                    ("Many Faces: be a clerk from the castle come to check the rolls.",
                     [narrate("A clerk's ink-stained fingers and a clerk's sigh. He hands her the rolls without "
                              "looking up."),
                      narrate("Bayushi and Shosuro troops, two hundred, under Soshi banners.")] + grievance("G923")),
                    ("Leave him.", []))])]),
        ([flag("G923")], [say("Quartermaster", "The rolls are in order. The rice is not.")])] + [
        ([flag("G967")], [narrate("The Soshi quartermaster, counting rice that isn't there."),
                          if_([flag("G990")], LEDGERS_U2)]),
        ([flag("G967"), flag("G923")], [say("Quartermaster", "You paid for the books, Unicorn. Don't wave them at "
                                                              "me.")])])
    ev.talk(40, 19, SC["muledriver"], [
        (None, [say("Water-carrier", "Water! Clean water, from the castle well! Not from Jiochi. Never from Jiochi.")]),
        ([flag("G967"), flag("G990")], [say("Water-carrier", "Water! Clean water! Not from Jiochi."),
                                        if_([flag("G920", False)], JIOCHI_U2)]),
        ([flag("G967"), flag("G996")], [say("Water-carrier", "Wear the yoke in good health, Unicorn. It's carried "
                                                             "worse.")])])
    ev.npc(70, 18, SC["shinobu"], "(sweetly) If I am to understand the war correctly, magistrates, we only defended "
                                  "ourselves. I'm only a lowly wife, of course.")
    ev.npc(36, 12, SC["oldwoman"], "Ten thousand of us between the castle and the mountain, and the rice ran out at "
                                   "midsummer.")
    ev.chest(100, 34, "I101", 3)
    return m, ev


