def shioden():
    m = MapSpec("M372", "Shioden", 80, 30, base=GRASS, y=3)
    m.rect(0, 12, 80, 5, ROAD, 3)
    building(m, 30, 20, 16, 7, wall=DARKWOOD)                              # the burned manor, a shell
    building(m, 8, 20, 10, 6, wall=WOOD)
    building(m, 56, 20, 10, 6, wall=WOOD)
    for x in range(4, 80, 9):
        m.tree(x, 5 + x % 3, TREE_S)
    ev = Events(m)
    ev.portal(78, 14, "M369", 4, d=3)                                       # event 1: back to Buried Leaves
    ev.talk(38, 18, SC["ichihito"], [(None, [if_([flag("G919")], ICHIHITO,
                                                 [if_([flag("G990")], ICHIHITO_U2,
                                                      [say("Ichihito", "Go away. I'm busy being a daimyo.")])])]),
                                     ([flag("G922")], [say("Ichihito", "Write it as it happened. Nobody else will.")])])
    ev.npc(42, 18, SC["veteran"], "His sensei. I kept him out of the battle where his father died. I should have kept "
                                  "him out of the next one.")
    ev.chest(70, 26, "I131", 1)
    return m, ev


