def yotomo_hill():
    m = MapSpec("M374", "Yotomo bell hill", 90, 32, base=GRASS3, y=3)
    m.rect(0, 13, 90, 5, DIRT, 3)
    for k in range(4):
        m.rect(40 + k, 20 + k, 14 - 2 * k, 8 - 2 * k, GRASS3, 4 + k)        # the hill
    fill(m, 45, 8, 23, 1, 4, 1, DARKWOOD)                                   # the bell frame
    fill(m, 50, 8, 23, 1, 4, 1, DARKWOOD)
    fill(m, 45, 12, 23, 6, 1, 1, DARKWOOD)
    for x in (8, 20, 70, 80):
        building(m, x, 22, 7, 5, wall=WOOD, wall_h=3)                       # dovecotes
    fill(m, 0, 4, 30, 90, 8, 2, STONE)                                      # the ridge
    ev = Events(m)
    ev.portal(1, 15, "M369", 5, d=1)                                        # event 1: Buried Leaves
    on = ev.portal(88, 15, "M375", 1, d=3)                                  # event 2: Perfume Petal Blossom
    ev.ev["#%d#" % on]["reqs0"] = [flag("G927")]
    ev.prop(47, 19, SC["gochu"], reqs=[flag("G927", False)], d=1)
    ev.scene(44, 15, "G927", [if_([flag("G967")], GOCHU_U2, GOCHU)], touch=True, after=[flag("G926")])
    ev.talk(64, 26, "CE000", [(None, [narrate("High on the ridge, a glint: an amulet catching the sun. Then nothing. (The "
                                              "watchers.)"), setf("G940")]),
                              ([flag("G940")], [narrate("The ridge, empty now.")])], trigger=1)
    ev.chest(28, 26, "I100", 2)
    return m, ev


