def perfume_petal():
    m = MapSpec("M375", "Perfume Petal Blossom", 104, 40, base=GRASS, y=3)
    m.rect(0, 13, 104, 5, STONEW, 3)
    for x in range(0, 104, 9):
        m.rect(x + 1, 3, 7, 6, (POPPYF, GRASS2)[x % 2], 3)                  # the flower fields, too perfect
    for x, w in ((6, 10), (22, 10), (60, 10), (76, 10)):
        building(m, x, 22, w, 6, wall=PLASTER)
    building(m, 38, 22, 16, 8, two_storey=True)                             # the most beautiful house
    shrine(m, 92, 23)
    ev = Events(m)
    ev.portal(1, 15, "M374", 2, d=1)                                        # event 1: Yotomo
    ev.portal(45, 21, "M376", 1, d=0)                                       # event 2: Nihime's house
    ev.portal(70, 21, "M377", 1, d=0)                                       # event 3: behind the houses: the grave path
    east = ev.portal(102, 15, "M378", 1, d=3)                               # event 4: the mountain road (after S03)
    ev.ev["#%d#" % east]["reqs0"] = [flag("G929")]
    ev.talk(100, 15, "CE000", [(None, [narrate("The mountain road. Not before seeing whoever lives in the most beautiful "
                                               "house."), step_back(-2.0, 0)]), ([flag("G929")], [])], trigger=5)
    ev.scene(6, 15, "G943", [if_([flag("G967")], S03_ARRIVE_U2, S03_ARRIVE)], after=[flag("G927")])
    save_shrine(m, ev, 96, 20)
    ev.npc(30, 12, SC["kiyo"], "Everyone is very happy here, lady. (smiling) Very, very happy.")
    ev.npc(84, 12, SC["gonbei"], "Refugees? There were refugees. They went up to the mines for work. Lots of work.")
    ev.chest(100, 34, "I168", 2)
    return m, ev


def nihime_house():
    def extra(m, ev):
        ev.prop(10, 7, SC["nihime"], d=0)
        ev.scene(8, 4, "G929", [if_([flag("G967")], NIHIME_U2 + TELL_U2, NIHIME + TELL)], after=[flag("G927")])
        ev.talk(10, 6, "CE000", [(None, [say("Nihime", "More tea? It's the only thing in this village that isn't "
                                                       "lying.")])])
    return castle_floor("M376", "Perfume Petal Blossom - the most beautiful house", 20, 8,
                        [("table", 9, 5), ("candle", 3, 2), ("candle", 18, 2), ("highchest", 16, 6)],
                        down=("M375", 2), wall=PLASTER, extra=extra)


def grave_path():
    m = MapSpec("M377", "The grave path", 90, 32, base=SL_GROUND, y=3)
    m.rect(0, 13, 90, 4, DIRT, 3)
    for x in range(6, 86, 7):
        for z in (6, 22):
            m.rect(x, z + (x % 3), 3, 2, GRASS3, 4)                         # low mounds, flowers planted over them
    fill(m, 84, 4, 10, 6, 8, 8, STONE)                                      # the jade-mine gate, sealed
    ev = Events(m)
    ev.portal(1, 15, "M375", 3, d=1)                                        # event 1: back to the village
    ev.talk(82, 15, "CE000", [(None, [narrate("The jade-mine gate, sealed with an earth spell. Ravens go in through a gap "
                                              "near the top. A smell comes out."),
                                      say("Rin", "(very quietly) The refugees. They 'went up to the mines for work'."),
                                      if_([flag("G967")],
                                          [say("Tamotsu", "(very quietly, for once not smiling) Not today. Not without "
                                                          "a hundred people, lanterns, and someone who owns the "
                                                          "mine.")],
                                          [say("Mitsue", "Not this chapter. Not without a hundred people and a great "
                                                         "deal of jade.")]), setf("G931")]),
                              ([flag("G931")], [narrate("The sealed gate. The ravens.")])], trigger=1)
    ev.talk(30, 26, "CE000", [(None, [narrate("A child's grave, smaller than the others, with a carved toy horse on it.")] +
                               honor(1) + [setf("G939")]),
                              ([flag("G939")], [narrate("The toy horse.")])], trigger=1)
    ev.chest(60, 26, "I130", 2)
    ev.chest(44, 4, "I190", 1)
    return m, ev


