def dragon_town():
    m = MapSpec("M379", "Dragon mountain town", 110, 42, base=GRASS, y=3)
    m.rect(0, 13, 110, 5, ROAD, 3)
    for x in range(110):                                                    # the peaks behind, snow on top
        h = 12 + int(5 * abs(np.sin(x * 0.11)) + 2 * abs(np.sin(x * 0.37)))
        m.rect(x, 31, 1, 7, STONE, h)
        m.rect(x, 38, 1, 4, SNOW, h + 3)
    building(m, 6, 22, 14, 7, wall=WOOD)                                    # the pilgrims' inn
    building(m, 26, 22, 10, 6, wall=PLASTER)                                # the Togashi outfitter
    tent(m, 42, 21)                                                         # the incense-seller's stall
    building(m, 60, 23, 10, 6, wall=WOOD)
    shrine(m, 90, 23)                                                       # the mountain shrine
    for x in (4, 24, 40, 56, 74, 86, 104):
        fb(m, x, 20, 2, LAMP_STREET)
    for x in range(3, 108, 11):
        m.tree(x, 8 + x % 3, (TREE_S, TREE_M)[x % 2])
    ev = Events(m)
    east = ev.portal(108, 15, "M380", 1, d=3)                               # event 1: the mountain road (after S02)
    ev.ev["#%d#" % east]["reqs0"] = [flag("G945")]
    ev.talk(106, 15, "CE000", [(None, [narrate("The mountain road. The troupe hasn't gathered yet: the shrine, east "
                                               "end of town."), step_back(-2.0, 0)]), ([flag("G945")], [])], trigger=5)
    ev.talk(1, 15, "CE000", [(None, [narrate("The lowland road, back down to Buried Leaves."),
                                     choices(("Go back down.", DARK + [go("M369", 104, 16)]), ("Stay.", []))])],
            trigger=5)
    ev.scene(5, 15, "G944", S01_SCP4, after=[flag("G936")])
    ev.scene(90, 16, "G945", S02_SCP4, touch=True, after=[flag("G944")])
    ev.inn(13, 20, EP_SERVICE["innkeeper"], 120)
    ev.clerk(31, 20, SC["outfitter"], "R154")
    ev.clerk(45, 19, SC["incense"], "R155")
    ev.npc(20, 12, SC["mirumotosentry"], "Pilgrims, walk on the left. The Togashi road belongs to the mountain. The "
                                         "mountain belongs to the Togashi. You belong on the left.")
    ev.npc(36, 12, SC["tbeggar"], "(holding out a bowl; a real tattoo coils up his forearm, the ink faded) Rice for an "
                                  "old pilgrim? I climbed higher than you once.")
    ev.talk(52, 19, SC["tamorimonk"], [(None, [
        say("Tamori apprentice", "Going up to the Furnace? Then listen. The rock up there is hot enough to cook you "
                                 "through your sandals."),
        say("Tamori apprentice", "The red stone near the lava burns anyone without a Tamori heat-ward. The outfitter "
                                 "sells them. Wear one, pilgrim."),
        say("Tamori apprentice", "And the fire spirits hate water and a good staff. The ash-dead hate jade. That's all "
                                 "the Furnace teaches, really.")])])
    ev.talk(70, 19, SC["kitsukiclerk"], [
        (None, [narrate("A Kitsuki clerk, muttering to a colleague over a ledger of road tolls."),
                choices(eavesdrop("Kitsuki clerk", 75, "\"...the Scorpion Champion's procession passes the "
                                  "Togashi road tomorrow. All of it. Banners, bearers, him. Going up to the High "
                                  "House.\"", "G955", CLERK_TIP,
                                  fail="(closing the ledger) Evidence, pilgrim, is not for sale. Nor for listening "
                                       "to."),
                        ("Leave him to his ledger.", []))]),
        ([flag("G955")], [say("Kitsuki clerk", "Tolls, tolls. Everybody wants to climb a mountain this summer.")])])
    ev.npc(82, 12, SC["muledriver"], "There's a ledge on the Togashi road. A wrestler's shortcut, if you can shoulder "
                                     "past my mules. You can't.")
    ev.npc(96, 12, SC["oldpilgrim"], "Kyuden Togashi! I've climbed to the High House nine times. The Kami has never "
                                     "once looked at me. I think that's the point.")
    ev.npc(76, 12, SC["pilgrimgirl"], "My grandmother says the Furnace takes anything. I asked if it takes "
                                      "homework.")
    ev.chest(100, 26, "N000", 3000)
