def mountain_road():
    m = MapSpec("M380", "The mountain road", 112, 36, base=GRASS3, y=3)
    for x in range(112):                                                    # the road climbs a step every 16 blocks
        m.rect(x, 0, 1, 36, None, 3 + x // 16)
    m.rect(0, 13, 112, 5, DIRT)
    for x in range(112):
        h = 3 + x // 16
        m.rect(x, 26, 1, 10, STONE, h + 8 + int(3 * abs(np.sin(x * 0.2))))  # the mountainside
        m.rect(x, 0, 1, 5, GRASS3, max(3, h - 1))                           # the drop below the road
    building(m, 54, 21, 14, 5, wall=WOOD)                                   # the mountain inn
    for x in range(4, 110, 9):
        m.tree(x, 8 + x % 4, (TREE_S, TREE_M)[x % 2])
    ev = Events(m)
    ev.portal(1, 15, "M379", 1, d=1)                                        # event 1: the town
    ev.portal(60, 20, "M381", 1, d=0)                                       # event 2: the mountain inn
    east = ev.portal(110, 15, "M382", 1, d=3)                               # event 3: the Togashi road (after S03)
    ev.ev["#%d#" % east]["reqs0"] = [flag("G946")]
    ev.talk(108, 15, "CE000", [(None, [narrate("Night is coming up the valley. Pilgrims stop at the mountain inn."),
                                       step_back(-2.0, 0)]), ([flag("G946")], [])], trigger=5)
    ev.npc(30, 12, SC["pilgrim"], "The Togashi road's beyond the inn. Wolves on it at night. Wolves, and worse.")
