def duty_choice(left):
    """The locked choice (production S05): every option but "Keep walking" answers with Mitsue's reason and asks again
    without it."""
    opts = [(lbl, [think(why), duty_choice([o for o in left if o[0] != lbl])]) for lbl, why in left]
    return choices(*(opts + [("Keep walking.", [])]))


