def case_done(f):
    """A grievance proven for the tribunal (production S03; numeric G975 cases_done)."""
    return [setf(f), setf("G975", 1, "+="),
            if_([{"lvar": "G975", "op": "==", "rvar": 2}],
                [narrate("Objective: two cases. Old Miyahana-sensei's cottage is in the hills south of town.")]),
            if_([{"lvar": "G975", "op": "==", "rvar": 3}],
                [narrate("Objective: three cases. Back to the Welcome Road inn: the tribunal's welcome dinner.")])]


# ---- M387 the Town of Buried Leaves (autumn), M388 the Welcome Road inn (S01, S05, S08)
def buried_leaves_autumn():
    m = MapSpec("M387", "The Town of Buried Leaves (autumn)", 110, 40, base=DIRT, y=3)
    m.rect(0, 14, 110, 5, ROAD, 3)
    building(m, 6, 22, 16, 7, wall=PLASTER)                                 # the Welcome Road inn
    building(m, 26, 22, 8, 5, wall=WOOD, wall_h=3)                          # the stable (Persimmon)
    building(m, 56, 22, 10, 6, wall=WOOD)                                   # the Unicorn trader
    building(m, 74, 23, 12, 6, wall=PLASTER)                                # the old tax office
    for x, z in ((88, 6), (96, 9), (102, 5), (12, 6), (30, 8), (44, 5)):
        tent(m, x, z, w=5, d=4)                                             # the refugees around the town
    for x in (4, 24, 52, 70, 90, 104):
        fb(m, x, 20, 2, LAMP_STREET)
    fb(m, 92, 21, 3, 14)                                                    # the roadside Jizo
    ev = Events(m)
    ev.portal(13, 21, "M388", 1, d=0)                                       # event 1: the Welcome Road inn
    ev.portal(108, 16, "M389", 1, d=3)                                      # event 2: east, the refugee camps
    ev.portal(1, 16, "M390", 1, d=1)                                        # event 3: west, the valley road
    ev.portal(80, 1, "M395", 1, d=2)                                        # event 4: south, the hills (Miyahana)
    ev.prop(29, 20, "EP172", msg="Persimmon glares at you. Persimmon glares at everyone.", d=1)
    ev.clerk(61, 20, SC["merchant"], "R156")
    ev.npc(40, 13, SC["censorclerk"], "A Crane clerk keeps the tribunal's ledgers. Every ledger in this valley has two "
                                      "sets of numbers.")
    ev.npc(46, 19, SC["uyojimbo"], "(holding his bandaged hand) Your pony. Your pony is a demon. ...Thank you for the "
                                   "sweets.")
    ev.npc(90, 13, SC["iuchifarmer"], "Salt. At Hafuna they ploughed salt into the fields. Riders in furs, with sacks. "
                                      "I saw them.")
    ev.npc(100, 18, SC["kitechild"], "The inn's having a big dinner when the judges are done. Everyone's invited "
                                     "except us.")
    ev.chest(28, 26, "N000", 100)                                           # c: the stable loft
    return m, ev


