    ev.portal(1, 15, "M393", 1, d=1)                                        # event 6: west, the Motobu crater
    ev.talk(56, 19, "CE000", [(None, [narrate("A track north to Yotomo, the pigeon breeders' village. Nothing for the "
                                              "tribunal up there."), step_back(0, -2.0)]),
                              ([flag("G978")], [])], trigger=5)
