def shiro_iuchi_garden():
    m = MapSpec("M391", "Shiro Iuchi - the garden", 84, 34, base=GRASS, y=3)
    for x in range(84):                                                     # the crags of the wind tunnel
        h = 10 + int(4 * abs(np.sin(x * 0.19)))
