def motobu_crater():
    m = MapSpec("M393", "The Motobu crater", 90, 34, base=SL_GROUND, y=4)
    m.rect(0, 13, 90, 5, DIRT, 4)
    zz, xx = np.mgrid[0:34, 0:90]
    crater = ((xx - 46) / 16.0) ** 2 + ((zz - 25) / 8.0) ** 2 <= 1.0
    m.hgt[crater] = 2
    m.blk[crater] = T(1)                                                    # scorched earth
    for x, z in ((36, 22), (54, 27), (44, 30), (58, 21)):
        m.tree(x, z, (ROCK_S, ROCK_M)[x % 2])                               # the temple's stones
    ev = Events(m)
    ev.portal(88, 15, "M390", 6, d=3)                                       # event 1: east, back to the valley road
    ev.talk(30, 18, SC["hitoro"], [(None, CASE3 + HITORO), ([flag("G987")], [
        say("Hitoro", "Both of them. Tell the judges both.")])], d=2)
    ev.npc(16, 12, SC["acolyte"], "We went to Denshi, after. The village. Hitoro-sama comes back here every day.")
    ev.chest(70, 30, "I130", 1)
    return m, ev


