def note(name, text):
    """Covered Ears: a written note instead of speech (production NOTE: lines, in capitals as the script has them)."""
    return {"cmd": "cmd_showmsg", "key": "message_talk", "text": _clean(text),
            "name": "%s (note)" % FULL_NAMES.get(name, name), "uiclose": 2}


EARS_ON = [setf("G999"), narrate("(Covered Ears: the wax goes in. Nothing the servants sing can reach you - and nobody "
                                 "can hear you either. Notes only. In battle, a voice skill means pulling your wax out "
                                 "first.)")]
EARS_OFF = [setf("G999", False), narrate("(The wax comes out. Birds. Wind. Your own breathing, very loud.)")]


def ears_off_here(ev, x, z):
    """A safe map: the wax comes out on arrival (autorun while G999 is set)."""
    ev.talk(x, z, "CE000", [([flag("G999")], EARS_OFF)], trigger=6)


# ---- M399 the star field outside Shiro Iuchi (S01)
S01_UNI3 = [narrate("CHAPTER 3 - The Noblest Blood."),
            narrate("A field outside Shiro Iuchi. An eight-pointed star burned into the frost. And at its centre, a "
                    "messenger in Seppun colours who will never deliver his message."),
            narrate("Akodo Rin stands at the edge of the burned star, very pale."),
            say("Rin", "A Seppun courier. Royal blood. (beat) It was meant to be me."),
            say("Tamotsu", "(gently) It wasn't you. Because of you. Because you were careful."),
            say("Rin", "Because you were careful."),
            narrate("A man in a white porcelain mask kneels by the body, sniffing the air. His eyes glow faintly behind "
                    "it: Iuchi Karasu, the daimyo's nephew."),
            say("Karasu", "(deadpan) The characters at the points. Noble. Blood. Teacher. And 'Fortunes', upside down."),
            say("Karasu", "Regret. My great-uncle Kurosho has summoned the Shuten Doji of Regret."),
            say("Karasu", "Its servants sing. If you hear them, you belong to it. And then you sing too."),
            say("Karasu", "I was a prisoner in the Shadowlands for six months. I never once regretted anything."),
            say("Karasu", "(beat) Except leaving. And now, coming back."),
            say("Tamotsu", "Then we'd better not listen. (holding up a twist of beeswax) The Iuchi agent's satchel. I "
                           "kept it."),
            say("Karasu", "(looking at the wax for a long moment) ...An emissary who carries earplugs. My uncle's luck "
                          "is improving."),
            say("Karasu", "Jade hurts it. Nothing else does much. And Shahai - my cousin, nine - is in the castle with "
                          "every servant in it singing."),
            say("Ryuko", "(already walking toward the castle) Then we go and get her.")] + \
    guest_join(12) + [
    narrate("(Iuchi Karasu: Jade Strike, called in twice a battle. Jade burns the dead and the Tainted.)"),
    narrate("Covered Ears: at the castle gate the Wax Earplugs go in. Possession by hearing can't touch you - but "
            "nobody can hear you either. Spoken path actions are out and the party talks in written notes. In "
            "battle, a voice skill (Words of Peace, Song of the Ki-Rin, The Clouds Part) means pulling your wax out "
            "first - and then you can hear them. The wax comes out at safe places."),
    setf("G998"), SAVE_CHOICE,
    narrate("Objective: Shiro Iuchi, north. The tower where Shahai is hiding.")]
GATE_UNI3 = [narrate("Shiro Iuchi's north gate, at the mouth of its wind tunnel. Somewhere inside, a great many people are "
                "humming the same song."),
        choices(("Put the wax in, and go in.", EARS_ON + DARK + [go("M400", 3, 3, padded=False)]),
                ("Not yet.", [step_back(0, -2.0)]))]


def star_field():
    m = MapSpec("M399", "The star field outside Shiro Iuchi", 110, 36, base=SNOW, y=3)
    m.rect(0, 13, 110, 5, DIRT, 3)
    for x in range(0, 110, 13):
        m.rect(x + 2, 4, 7, 6, GRASS3, 3)                                   # the frost thinning to grass
    cx, cz = 30, 25                                                         # the eight-pointed star, burned in
    for z in range(cz - 9, cz + 10):
        for x in range(cx - 9, cx + 10):
            a, dd = np.arctan2(z - cz, x - cx), np.hypot(x - cx, z - cz)
            t = 1 - abs(((a / (2 * np.pi) * 8) % 1) - 0.5) * 2
            if dd <= 2.0 + 6.5 * t ** 2:
                m.rect(x, z, 1, 1, SL_GROUND if dd > 2.2 else EMBER, 3)
    fill(m, 0, 4, 31, 110, 10, 5, STONE)                                    # the crags of the wind tunnel
    fill(m, 46, 4, 30, 18, 12, 2, STONEW)                                   # Shiro Iuchi's north wall
    fill(m, 52, 4, 30, 6, 6, 2, VOID)                                       # the gate
    fill(m, 46, 16, 30, 18, 1, 2, ROOF)
    for x in (44, 66):
        fb(m, x, 28, 2, LAMP_TORCH)
    ev = Events(m)
    tower = ev.portal(55, 29, "M400", 1, d=0)                               # event 1: the castle (back from the tower)
    ev.ev["#%d#" % tower]["reqs0"] = [flag("G999")]
    woods = ev.portal(108, 16, "M403", 1, d=3)                              # event 2: east, the Iuchi woods
    ev.ev["#%d#" % woods]["reqs0"] = [flag("G1000")]
    camp = ev.portal(84, 1, "M404", 1, d=2)                                 # event 3: south, the Mirumoto camp
    ev.ev["#%d#" % camp]["reqs0"] = [flag("G1002")]
    ev.talk(55, 27, "CE000", [(None, [narrate("The castle. Not before seeing to the star field.")]),
                              ([flag("G998")], GATE_UNI3), ([flag("G1000")], [narrate("The gate. The humming hasn't "
                                                                                 "stopped.")])], trigger=5)
    ev.talk(106, 16, "CE000", [(None, [narrate("The Iuchi woods, east. Shahai first."), step_back(-2.0, 0)]),
                               ([flag("G1000")], [])], trigger=5)
    ev.talk(84, 3, "CE000", [(None, [narrate("The road south, toward the valley mouth and the Dragon army. Daiyu "
                                             "first."), step_back(0, 2.0)]), ([flag("G1002")], [])], trigger=5)
    ev.talk(1, 15, "CE000", [(None, [narrate("The valley road, back to the Town of Buried Leaves."),
                                     choices(("Go back.", DARK + [go("M369", 94, 16)]), ("Stay.", []))])], trigger=5)
    ev.scene(6, 15, "G998", S01_UNI3, after=[flag("G994")])
    ev.prop(30, 25, SC["courier"], msg="The Seppun courier, face-down in the star.", d=1)
    ev.prop(32, 24, SC["karasu"], reqs=[flag("G998", False)], d=1)
    ears_off_here(ev, 8, 20)
    ev.chest(100, 26, "I131", 2)
    return m, ev


# ---- M400-M402 Shiro Iuchi's tower (S02: ears covered; the singing servants; Shahai's door)
TOWER_NOTES = [narrate("The castle halls. Servants in aprons sway between the pillars, eyes blank, mouths open on the "
                       "same song. Nobody hears a note of it."),
               note("Tamotsu", "DON'T STEP ON THE HUMMING ONES. THEY'LL REMEMBER IT."),
               note("Karasu", "AGREED. ALSO MY FEET ARE COLD."),
               note("Rin", "WHICH WAY IS THE TOWER"),
               note("Ryuko", "UP."),
               narrate("(Singing servants are weak to Bo, Water and Jade: Karasu's Jade Strike, or Jade Dust. Break one "
                       "- a Suki - and it wakes and leaves the fight, alive. If one tears the wax out of your ears, its "
                       "Hum will silence you.)")]


