def jade_node(ev, x, z, f, porter=False):
    """A raw-jade node: free Raw Jade; with porter=True it goes to the carts unless the camps were fed (F-2)."""
    take = got("I410", "Raw Jade", 2) + [setf(f)]
    ev.talk(x, z, "CE000", [
        (None, [narrate("A seam of raw jade, green under the grime.")] +
         ([if_([flag("G970")], take, [narrate("A Dragon porter is already prising it out for the carts."), setf(f)])]
          if porter else take)),
        ([flag(f)], [narrate("An empty seam.")])], trigger=1)


def jade_mines_1():
    m = cave_map("M405", "The jade mines - the entrance", 72, 40,
                 rooms=[(10, 6, 7, 4), (22, 18, 10, 6), (44, 16, 9, 5), (60, 28, 8, 6), (30, 32, 7, 4)],
                 links=[(10, 0, 10, 8, 5), (14, 9, 20, 14, 5), (30, 18, 38, 16, 5), (50, 18, 58, 25, 5),
                        (24, 22, 28, 30, 4), (60, 33, 60, 40, 5)], seed=41)
    for x, z in ((18, 20), (40, 14), (62, 30)):
        fb(m, x, z, 4, IN["jewel"], y=2)                                    # glints of jade
    ev = Events(m)
    ev.portal(10, 1, "M404", 2, d=2)                                        # event 1: out to the camp
    ev.portal(60, 38, "M406", 1, d=0)                                       # event 2: deeper, the galleries
    ev.ev["#2#"]["reqs0"] = [flag("G1007")]
    ev.scene(10, 6, "G1006", GRAVES, after=[flag("G1004")])
    for x, z in ((6, 8), (14, 8)):
        m.rect(x, z, 2, 1, GRASS3, 3)                                       # the mounds, flowers on them
    cave_fight(ev, 44, 16, "G1007", 127, DEAD_A, [(47, 15, "EP432"), (48, 17, "EP432"), (49, 16, "EP432")])
    jade_node(ev, 18, 21, "G1014")
    jade_node(ev, 40, 15, "G1015", porter=True)
    jade_node(ev, 62, 31, "G1016")
    ev.chest(30, 33, "I104", 3)                                             # c: Jade Dust
    return m, ev


