def tunnel_map(mid, name, seed):
    m = MapSpec(mid, name, 110, 24, base=DIRT, y=3)
    rng = np.random.default_rng(seed)
    for x in range(110):                                                    # the canyon walls, high behind, low in front
        m.rect(x, 18 + int(rng.integers(0, 2)), 1, 6, STONE, 12 + int(rng.integers(0, 4)))
        m.rect(x, 0, 1, 3 + int(rng.integers(0, 2)), STONE, 5)
    for x in range(14, 104, 16):
        m.rect(x, 4, 2, 14, SAND, 3)                                        # the gale strips, wind-scoured
    GALE_TILES[mid] = [SAND]
    return m


