    m.rect(0, 14, 104, 4, ROAD, 3)
    building(m, 12, 22, 14, 7, wall=WOOD)                                   # the harbour inn
    building(m, 34, 22, 10, 6, wall=WOOD)                                   # the chandler
    building(m, 52, 23, 16, 7, wall=DARKWOOD, wall_h=5)                     # a warehouse
    for x in (8, 30, 50, 74, 96):
        fb(m, x, 20, 2, LAMP_STREET)
    ev = Events(m)
    ev.portal(102, 16, "M416", 1, d=3)                                      # event 1: east, the market
    ev.scene(12, 9, "G1040", S01_RON1, after=[flag("G1062")])
