    m.rect(44, 14, 12, 3, DARKWOOD, 3)                                      # the maple log
    m.rect(56, 13, 44, 5, DIRT, 3)
    for x in range(2, 100, 7):
        if not (40 <= x <= 58):
            m.tree(x, 4 + x % 3, (TREE_M, TREE_S)[x % 2])
