def slope_map(mid, name, w, d, rise):
    m = MapSpec(mid, name, w, d, base=SNOW, y=3)
    for x in range(w):
        m.rect(x, 0, 1, d, SNOW, 3 + x // rise)                             # the path climbs east
    for x in range(w):
        m.rect(x, 13, 1, 5, DIRT, 3 + x // rise)                            # the trodden trail
    return m


def cedar_slopes():
    m = slope_map("M431", "The Mountain of the White Snow - the cedar slopes", 110, 34, 28)
    for x in range(2, 110, 5):
        m.tree(x, 24 + x % 6, TREE_L)
        if x % 3 == 0:
            m.tree(x + 1, 4 + x % 4, TREE_L)
    fill(m, 62, 4 + 62 // 28, 20, 2, 2, 1, STONEW)                          # the Crane grave
    fill(m, 48, 4 + 48 // 28, 21, 5, 3, 3, STONEW)                          # the rock shelter
    ev = Events(m)
    on = ev.portal(108, 15, "M432", 1, d=3)                                 # event 1: on, to the ice ledges
    ev.ev["#%d#" % on]["reqs0"] = [flag("G1099")]
    ev.talk(2, 15, "CE000", [(None, [narrate("Back down to the village?"),
                                     choices(("Go down.", [go("M430", 100, 15)]), ("Stay.", []))])], trigger=1)
    rope_point(ev, 28, 12, "G1117", [narrate("Above, Matsu Hanae's foot goes out from under her. She swings "
                                             "from the line over a long drop."),
                                     say("Hanae", "(dangling) Ronin! Ronin!"),
                                     say("Sayo", "(pulling her up one-handed) Sayo. My name's Sayo, my lady. It's "
                                                 "quicker to shout.")])
    rope_gate(ev, 32, 15, "G1117", "Too steep to climb untied. (A rope point, just back there.)")
    ev.talk(50, 19, "CE000", [(None, SHELTER), ([flag("G1120")], [narrate("The frozen yari. The banner.")])],
            trigger=1)
    ev.prop(63, 18, "EP166", reqs=[flag("G1099", False)], d=1)                 # a snow beast in the drift
    ev.scene(58, 15, "G1099", STAGE1, touch=True, after=[flag("G1098")])
    ev.prop(100, 15, SC["hikaru"], reqs=[flag("G1099", False)], d=3)
    ev.chest(72, 25, "I131", 1)                                             # c
    return m, ev


