def oracle_town():
    m = MapSpec("M438", "The Oracle's shrine town", 116, 46, base=SL_GROUND, y=3)
    m.rect(0, 12, 116, 7, DIRT, 3)                                          # the pilgrim street
    m.rect(0, 0, 116, 6, SL_GROUND, 2)
    for x in range(116):
        m.rect(x, 36, 1, 10, SL_GROUND, 14 + (x * 7) % 5)                   # the volcano behind the town
    m.rect(52, 40, 4, 6, LAVA, 15)                                          # the glow of the crater road
    building(m, 4, 23, 10, 6, wall=WOOD)                                    # the herb stall's house
    building(m, 34, 23, 14, 8, wall=PLASTER)                                # the pilgrim inn
    building(m, 54, 23, 12, 7, wall=DARKWOOD)                               # the temple outfitter
    shrine(m, 76, 24)                                                       # the lower shrine
    building(m, 92, 23, 12, 7, wall=PLASTER, two_storey=True)              # the quiet teahouse
    building(m, 106, 24, 8, 6, wall=WOOD)                                   # the agents' lodging
    for x in range(6, 116, 10):
        fb(m, x, 20, 2, LAMP_STREET)
    ev = Events(m)
    ev.portal(1, 15, "M437", 1, d=1)                                        # event 1: back down the pilgrim road
    east = ev.portal(114, 15, "M439", 1, d=3)                               # event 2: the eta quarter
    ev.ev["#%d#" % east]["reqs0"] = [flag("G1134")]
    ev.scene(6, 15, "G1134", S01_RON4, after=[flag("G1132")])
    ev.follower(10, 17, SC["akari"], "Akari keeps her hood up and her eyes on the mountain.",
                reqs=[flag("G1134"), flag("G1138", False)])
    ev.inn(41, 21, EP_SERVICE["innkeeper"], 120)
    ev.clerk(60, 21, SC["outfitter"], "R168")
    ev.clerk(9, 21, SC["herbseller"], "R169")
    ev.talk(46, 14, SC["pilgrimagent"], [(None, AGENT), ([flag("G1135")], AGENT_AFTER)], reqs=[flag("G1134")])
    ev.npc(22, 12, SC["pilgrimagent"], "(to another pilgrim in very good sandals) Rooftops by midnight. Two dozen of us.",
           reqs=[flag("G1134")])
    ev.talk(64, 12, EP_HE["order_watcher"], [(None, SCOUT), ([flag("G1156")], [say("Snake scout", "The Order is "
                                                                                    "patient, ronin girl.")])],
            reqs=[flag("G1134")])
    ev.talk(84, 18, SC["priest"], [(None, PRIESTS)])
    ev.npc(88, 19, SC["priest"], "(muttering) An eta at the crater. The ancestors would weep.")
    ev.talk(30, 17, SC["oldpilgrim"], [(None, PILGRIMS)], reqs=[flag("G1134")])
    ev.prop(32, 17, SC["pilgrimgirl"], d=2)
    ev.talk(78, 22, SC["shrinekeeper"], [(None, OLD_PRIEST)])
    ev.scene(97, 19, "G1143", S05_RON4, touch=True, after=[flag("G1142")])
    ev.prop(99, 20, SC["snakeelder"], reqs=[flag("G1142"), flag("G1143", False)], d=2)
    ev.npc(70, 18, SC["pilgrimgirl"], "The mountain's been grumbling since the spring. Mother says it's clearing its "
                                      "throat.")
    ev.npc(104, 15, SC["incense"], "Incense for the ascension! Ten zeni a stick, and the Oracle sees it rise!")
    ev.chest(26, 31, "I131", 3)                                             # c
    for x, item in ((107, "I254"), (109, "I185"), (111, "W140")):           # C: the agents' lodging
        ev.chest(x, 21, item, 1)
    return m, ev


