def eta_quarter_oracle():
    m = MapSpec("M439", "The eta quarter below the shrine town", 84, 36, base=T(0), y=3)   # bare mud
    m.rect(0, 13, 84, 5, DIRT, 3)
    fill(m, 0, 4, 20, 84, 3, 1, DIRT)                                       # the mud walls behind
    fill(m, 0, 4, 9, 84, 2, 1, DIRT)                                        # and in front (a gate at the west end)
    for x, z in ((6, 24), (22, 24), (40, 24), (58, 25)):
        building(m, x, z, 10, 6, wall=WOOD)                                 # huts
    fill(m, 72, 4, 23, 6, 2, 4, DIRT)                                       # the tanning vats
    m.walls += [(x, 10) for x in range(4, 84)]
    ev = Events(m)
    ev.portal(1, 15, "M438", 2, d=1)                                        # event 1: back up to the town
    ev.scene(8, 15, "G1138", S03_RON4, touch=True, after=[flag("G1134")])
    ev.prop(14, 18, SC["hiro"], reqs=[flag("G1138", False)], d=2)
    ev.talk(26, 19, SC["umebaa"], [(None, [say("Ume-baa", "(puffing her pipe) Fire's just an old man shouting. "
                                                          "You've dealt with those.")])], reqs=[flag("G1138")])
    ev.talk(44, 19, SC["akari"], [(None, [say("Akari", "(quietly) It's still saying my name. Louder at night.")]),
                                  ([flag("G1143")], RACE_START)], reqs=[flag("G1138"), flag("G1145", False)])
    ev.npc(62, 18, SC["fumi"], "The well's the only good water in the quarter. The town won't share theirs.")
    ev.talk(80, 15, "CE000", [(None, WELL_LANE), ([flag("G1140")], [narrate("The well. The water is clear again.")])],
            reqs=[flag("G1138")], trigger=1)
    return m, ev


