def poisoned_well():
    m = MapSpec("M440", "The eta quarter's well (night)", 60, 30, base=T(0), y=3)
    m.rect(0, 12, 60, 6, DIRT, 3)
    fill(m, 0, 4, 20, 60, 3, 1, DIRT)
    fill(m, 30, 4, 19, 3, 1, 3, STONEW)                                     # the well
    building(m, 8, 23, 10, 6, wall=WOOD)
    building(m, 40, 23, 10, 6, wall=WOOD)
    ev = Events(m)
    ev.portal(1, 15, "M439", 1, d=1)                                        # event 1: back into the quarter
    for x, z in ((28, 17), (34, 17), (31, 14)):
        ev.prop(x, z, SC["pilgrimagent"], reqs=[flag("G1140", False)], d=1)
    ev.prop(46, 15, SC["nashiko"], reqs=[flag("G1140"), flag("G1142", False)], d=1)
    ev.scene(18, 15, "G1157", S04_RON4, touch=True, after=[flag("G1135")])
    ev.light(31, 20, col=0xFFFFB060, lr=4.0)
    return m, ev


