def oracle_rooftops():
    m = MapSpec("M441", "The shrine town rooftops (night)", 110, 30, base=T(0), y=1)   # the street far below
    for x in range(0, 110, 14):
        m.rect(x, 7, 12, 4, PLASTER, 5)                                     # the houses' walls below the eaves
        m.rect(x + 2, 19, 12, 4, PLASTER, 5)
    m.rect(0, 11, 110, 8, ROOF, 8)                                          # the tiled roofs, eave to eave
    m.rect(59, 11, 19, 8, DIRT, 3)                                          # down into the alley
    for x in range(54, 59):
        m.rect(x, 11, 1, 8, PLANK, 8 - (x - 54))                            # a stair of crates down
    for x in range(78, 83):
        m.rect(x, 11, 1, 8, PLANK, 4 + (x - 78))                            # and up the far side
    m.rect(83, 11, 27, 8, ROOF, 8)
    for x in range(4, 110, 16):
        fb(m, x, 10, 2, LAMP_STREET)
    m.walls += [(x, z) for x in range(110) for z in (10, 19)]
    ev = Events(m)
    on = ev.portal(108, 15, "M442", 1, d=3)                                 # event 1: on, to the switchback stair
    ev.ev["#%d#" % on]["reqs0"] = [flag("G1147")]
    ev.talk(2, 15, "CE000", [(None, NO_TIME)], trigger=5)
    for x, z in ((34, 13), (36, 16)):
        ev.prop(x, z, EP_HE["shadow_in_black"], reqs=[flag("G1146", False)], d=1)
    for x, z in ((70, 13), (72, 16)):
        ev.prop(x, z, EP_HE["shadow_in_black"], reqs=[flag("G1147", False)], d=1)
    ev.follower(4, 16, SC["akari"], "Akari, out of breath, holding the basket as if it were the Oracle's own.",
                reqs=[flag("G1145")])
    ev.follower(4, 14, SC["hiro"], "Hiro, the no-dachi over his shoulder, counting under his breath.",
                reqs=[flag("G1145"), flag("G1147", False)])
    ev.scene(28, 15, "G1146", RACE1, touch=True, after=[flag("G1145")])
    ev.scene(66, 15, "G1147", RACE2, touch=True, after=[flag("G1146")])
    ev.light(66, 15, col=0xFFFFA050, lr=5.0, dy=2)
    return m, ev


# ---- M442 the switchback stair (S06: race battles 3-5, the back gate, the crater lantern; S07 the Naga's champion)
ROAD_ON = [{"lvar": "G1144", "op": "==", "rvar": 1}]
CLIFF_ON = [{"lvar": "G1144", "op": "==", "rvar": 2}]
SKIP = [narrate("Above the last bend: the crater shrine's back gate, iron-bound, nobody's road but a priest's."),
        narrate("Sayo turns the old priest's key in the lock. The gate swings, and the last switchback goes by "
                "underneath them."), setf("G1148"), setf("G1150")]
RACE3 = [if_([flag("G1136")] + ROAD_ON,
             [say("Pilgrim", "(shouting, making way) The eta girl! Let the fire's girl through!"),
              narrate("The crowd on the pilgrim road parts for them. Someone presses water and rice balls into Sayo's "
                      "hands as she passes."),
              {"charaid": "P000", "cmd": "cmd_hpmp", "cmdtgt": 11, "hp1": True, "op": 1, "pid": "HP", "val": 30}]),
         if_([flag("G1112")] + ROAD_ON,
             [narrate("On the switchback, five young samurai in bright clan colours push through the pilgrims."),
              say("Hanae", "Ronin! Sayo! Go - we'll hold this one!"),
              say("Sayo", "(over her shoulder) My lady! Thank you for the ropes!"),
              say("Hanae", "(drawing) Go!"), setf("G1148")],
             [if_([flag("G1137")] + ROAD_ON, SKIP,
                  [narrate("The first switchback. The stair is narrow, and the drop is long. They are waiting."),
                   battle("M001", 149), setf("G1148")])])]
RACE4 = [narrate("The cliff path: a ledge of black stone over nothing, the town's lanterns far below."),
         battle("M001", 150), setf("G1149")]
RACE5 = [if_([flag("G1137")], SKIP,
             [narrate("The last of them, on the last ledge before the crater."),
              battle("M001", 151), setf("G1150")])]
LANTERN = [narrate("A stone lantern at the top of the stair, its flame lit from the crater itself."),
           say("Akari", "(gasping, climbing) Sayo - I can't - the fire's so loud -"),
           say("Sayo", "(pulling her up) Then shout back! Tell it to wait for us!"),
           say("Akari", "(a cracked, astonished shout up at the mountain) WAIT FOR US!"),
           narrate("The mountain rumbles. It sounds, almost, like it's laughing."),
           SAVE_CHOICE, narrate("Objective: the crater, at the top.")]
S07_RON4 = [narrate("At the top of the stair, blocking the way: a great serpent-bodied warrior in a pearl-white robe, "
                    "spear lowered. The Great Naga's champion - the Order's guardian."),
            say("Naga champion", "The Order guards the true lines. The choice must be the right one."),
            say("Sayo", "It is. (pointing at Akari) There's a true line. It goes from her to the fire."),
            say("Sayo", "(drawing) Guard that."),
            narrate("(The Naga's champion: weak to Air, Yari and Fire; resists Water. He is not evil. Break him, and "
                    "he may listen.)"),
            battle("M001", 153),
            if_([flag("G1153")],
                [narrate("The champion lowers his spear and coils aside.")] + honor(1),
                [narrate("The champion sinks onto his coils, breathing like the sea, and lets them pass.")]),
            narrate("Something round and cool lies on the stair where he coiled. A pearl.")] + \
    got("A165", "the Naga Pearl") + [
    narrate("Dawn is a red line on the crater's rim."),
    go("M443", 6, 15)]


def switchback_stair():
    m = MapSpec("M442", "The switchback stair (night)", 116, 40, base=SL_GROUND, y=3)
    for x in range(116):
        h = 3 + x // 24                                                     # the stair climbs east
        m.rect(x, 0, 1, 40, SL_GROUND, h)
        m.rect(x, 0, 1, 9, SL_GROUND, h - 2)                                # the drop in front (the cliff path)
        m.rect(x, 13, 1, 5, STONEW, h)                                      # the stair
        m.rect(x, 24, 1, 16, SL_GROUND, h + 7)                              # the mountain behind
    for x in range(4, 116, 11):
        fb(m, x, 20, 2, LAMP_STREET)
    m.walls += [(x, 9) for x in range(116)]
    ev = Events(m)
    ev.talk(2, 15, "CE000", [(None, NO_TIME)], trigger=5)                   # event 1: no going back
    ev.follower(4, 16, SC["akari"], "Akari, one hand on the rock, the other on Sayo's belt.",
                reqs=[flag("G1145"), flag("G1154", False)])
    for x in (36, 38):
        ev.prop(x, 14 + (x % 3), EP_HE["shadow_in_black"], reqs=[flag("G1148", False)], d=1)
    ev.scene(30, 15, "G1148", RACE3, touch=True, after=[flag("G1147")])
    ev.scene(52, 15, "G1149", RACE4, touch=True, after=[flag("G1148")] + CLIFF_ON)
    ev.scene(74, 15, "G1150", RACE5, touch=True, after=[flag("G1149")] + CLIFF_ON)
    ev.talk(80, 15, "CE000", [(None, [narrate("The path on is narrow. (They are still behind you.)"),
                                             step_back(-2.0, 0)]),
                                     ([flag("G1148")] + ROAD_ON, []), ([flag("G1150")], [])], trigger=5)
    ev.scene(94, 15, "G1151", LANTERN, touch=True, after=[flag("G1148")])
    ev.light(96, 18, col=0xFFFF9040, lr=5.0, dy=3)
    ev.scene(104, 15, "G1152", S07_RON4, touch=True, after=[flag("G1151")])
    return m, ev


# ---- M443 the crater shrine (S08 the ascension, at dawn; the chapter ends)
S08_RON4 = [narrate("The crater shrine, at the lip of the fire. The old Oracle of Fire stands at the edge, ancient, "
                    "half-made of flame. Dawn breaks."),
            say("Oracle of Fire", "(turning; a voice like a bonfire) You brought her. Good. I was getting impatient. "
                                  "Fire always is."),
            narrate("He holds out a burning hand. Akari, shaking, takes it."),
            narrate("The old Oracle becomes light and rises into the dawn like a spark from a bonfire, and is gone."),
            narrate("Akari stands at the crater's edge. The flames in the pit bow toward her. The priests who climbed "
                    "behind them fall to their knees. Some weep. Some look furious."),
            say("Akari", "(her voice carries like a bonfire now) Sayo."),
            say("Akari", "(beat; almost herself again) ...It still says my name like a lord."),
            say("Akari", "(smiling) But it says yours like a friend."),
            narrate("She holds out something small and warm: an ember, caught in a twist of iron."),
            say("Akari", "For you. It won't make you anything. It'll just keep you warm. And light, if you need it.")] + \
    got("A164", "the Ember Charm") + [
    narrate("(Ember Charm: once a battle, its wearer can Spark - a small Fire hit - or Rekindle a fallen ally.)"),
    say("Sayo", "(taking it; no powers, no glow, just an ember) ...That's all I ever wanted from fire, honestly."),
    setf("G1154"),
    narrate("The descent. Sayo turns the snake beads in one hand and the ember in the other."),
    say("Sayo", "(to herself) Three hundred years of emperors, descended from a peasant."),
    say("Sayo", "I could start a war with one sentence. (beat) I'll keep it. For the villagers who'd die in it."),
    if_([flag("G1114")], [say("Sayo", "(beat) For Old Mosuke's rice cakes.")]),
    say("Sayo", "(looking at her friends ahead on the path) ...And for my family."),
    narrate("\"The Oracle's Choice\" - complete."),
    narrate("An eta woman the fire called by name, a poisoned well, a race up a burning mountain, and a serpent that "
            "lowered its spear. Sayo didn't become the Oracle. She got her friend there alive - and finally chose a "
            "family."),
    narrate("(Sayo's road is walked. Hiro's \"The Tiger in the Blood\" waits for her in Cakon. And at Rank 4, Lv 51: her "
            "fourth ronin technique.)")] + DARK + [go("M438", 8, 15)]


def crater_shrine():
    m = MapSpec("M443", "The crater shrine (dawn)", 72, 34, base=SL_GROUND, y=6)
    m.rect(4, 12, 34, 7, STONEW, 6)                                         # the shrine's paved walk
    m.rect(0, 0, 72, 6, SL_GROUND, 4)
    m.rect(40, 8, 26, 20, SL_GROUND, 3)                                     # the pit
    m.rect(43, 11, 20, 14, LAVA, 2)                                         # the fire
    m.rect(0, 28, 72, 6, SL_GROUND, 14)                                     # the crater wall behind
    shrine(m, 18, 22)
    m.walls += [(39, z) for z in range(8, 28)]
    ev = Events(m)
    ev.prop(38, 16, SC["oracle"], reqs=[flag("G1154", False)], d=3)
    ev.prop(34, 15, SC["akari"], d=3)
    for x, z in ((14, 10), (18, 9), (22, 10)):
        ev.prop(x, z, SC["priest"], d=1)
    ev.scene(12, 15, "G1158", S08_RON4, touch=True, after=[flag("G1152")])
    ev.light(52, 18, col=0xFFFF7030, lr=10.0, dy=4)
    return m, ev


# ---- battle backdrops
def battle_oracle_road():
    m = MapSpec("M894", "Battle: the pilgrim road", 128, 128, base=SL_GROUND, y=0)
    m.rect(0, 56, 128, 16, DIRT, 0)
    for x in range(0, 128, 20):
        m.rect(x, 30, 8, 6, LAVA, 0)
    m.rect(0, 92, 128, 36, SL_GROUND, 12)
    for x in range(4, 128, 10):
        m.tree(x, 84 + x % 5, ROCK_M)
    return m


def battle_town_night():
    m = MapSpec("M895", "Battle: the shrine town at night", 128, 128, base=T(0), y=0)
    m.rect(0, 56, 128, 16, DIRT, 0)
    for x in range(4, 128, 22):
        building(m, x, 92, 14, 8, wall_h=5, wall=WOOD)
    ev = Events(m)
    ev.n = 100
    ev.light(52, 66, col=0xFFFFA050, lr=10.0, dy=5)                         # a lantern over the fight
    return m, ev


def battle_switchback():
    m = MapSpec("M896", "Battle: the switchback stair", 128, 128, base=STONEW, y=0)
    m.rect(0, 92, 128, 36, SL_GROUND, 12)
    for x in range(8, 128, 16):
        fb(m, x, 88, 2, LAMP_STREET)
    ev = Events(m)
    ev.n = 100
    ev.light(52, 66, col=0xFFFF8040, lr=10.0, dy=5)                         # the crater's red glow
    return m, ev


BATTLE_SPECS.update({"M894": battle_oracle_road, "M895": battle_town_night, "M896": battle_switchback})
