def battle_thunder_plain():
    m = MapSpec("M897", "Battle: the Plains of Thunder", 128, 128, base=GRASS3, y=0)
    m.rect(0, 56, 128, 16, ROAD, 0)
    for x in range(0, 128, 14):
        m.rect(x, 92 + x % 5, 10, 36, GRASS3, 3 + x % 4)
    for x in range(6, 128, 12):
        m.tree(x, 86 + x % 6, ROCK_M if x % 2 else ROCK_S)
    return m


def battle_stockade():
    m = MapSpec("M898", "Battle: the stockade of Osano-Wo", 128, 128, base=DIRT, y=0)
    m.rect(0, 56, 128, 16, ROAD, 0)
    fill(m, 0, 1, 90, 128, 5, 2, DARKWOOD)                                  # the stockade behind the fight
    for x in range(6, 128, 14):
        fb(m, x, 86, 2, LAMP_TORCH)
    ev = Events(m)
    ev.n = 100
    ev.light(52, 66, col=0xFFFF9050, lr=10.0, dy=5)                         # torchlight and burning goblins
    return m, ev


