def shinomen_map(mid, name, seed, w=100, d=34, clearing=None):
    """A Shinomen stretch: an old deer track through dense forest, the canopy closing overhead."""
    m = MapSpec(mid, name, w, d, base=GRASS3, y=3)
    for x in range(0, w, 2):                                                # the track wanders
        z = 14 + int(round(2.5 * math.sin(x / 9.0 + seed)))
        m.rect(x, z, 2, 5, DIRT, 3)
    keep = [(x, x + 2, 12 + int(round(2.5 * math.sin(x / 9.0 + seed))),
             21 + int(round(2.5 * math.sin(x / 9.0 + seed)))) for x in range(0, w, 2)]
    if clearing:                                                            # a side clearing, a short path to it
        cx, cz, cw, cd = clearing
        m.rect(cx, cz, cw, cd, GRASS3, 3)
        keep.append((cx - 1, cx + cw + 1, cz - 1, cz + cd + 1))
        mx, zt = cx + cw // 2, track_z(cx + cw // 2, seed)
        z0, z1 = min(zt, cz + cd // 2), max(zt, cz + cd // 2)
        m.rect(mx - 1, z0, 3, z1 - z0 + 1, DIRT, 3)
        keep.append((mx - 2, mx + 3, z0, z1 + 1))
    rng = np.random.default_rng(seed)
    forest_trees(m, rng, int(w * d / 11), keep)
    for x in range(0, w, 6):                                                # the forest wall, both sides
        m.tree(x, 2 + x % 3, TREE_L)
        m.tree(x + 3, d - 3 - x % 2, TREE_L)
    return m


def track_z(x, seed):
    return 16 + int(round(2.5 * math.sin(x / 9.0 + seed)))


def shinomen_1():
    s = 1
    m = shinomen_map("M447", "Shinomen Mori - the deer track", s)
    for x in range(30, 52):                                                 # the drag-marks, across the track
        m.rect(x, track_z(x, s) - 6 + (x - 30) // 2, 2, 2, DIRT3, 3)
    ev = Events(m)
    ev.portal(1, track_z(1, s), "M446", 2, d=1)                             # event 1: back to the edge
    ev.portal(98, track_z(98, s), "M448", 1, d=3)                           # event 2: deeper
    ev.scene(40, track_z(40, s), "G1179", NAGA_MARKS, touch=True)
    ev.prop(46, 7, EP_NAGA, msg="Nothing. Only the ferns, moving back into place.", d=0, reqs=[flag("G1179", False)])
    stichkik_follows(ev, 4, track_z(4, s))
    ev.chest(66, 10, "I130", 2)
    ev.chest(84, 23, "I131", 3)
    return m, ev


