    fill(m, 50, 4, 6, 2, 3, 2, DARKWOOD)                                    # the carving: kneeling figure
    fill(m, 49, 4, 7, 1, 1, 1, DARKWOOD)
    m.tree(51, 4, TREE_L)                                                   # the tree it was cut from
    ev = Events(m)
    ev.portal(1, track_z(1, s), "M447", 2, d=1)
    ev.portal(98, track_z(98, s), "M449", 1, d=3)
    ev.scene(50, 10, "G1180", CARVED, touch=True)
    ev.talk(50, 9, "CE000", [(None, [narrate("\"Here is your bushido. Honestly.\" The sap has dried.")])], trigger=1,
            reqs=[flag("G1180")])
