    ev.prop(33, 10, SC["mamoru"], reqs=[flag("G1186", False)], d=1)
    for x, z in ((22, 5), (42, 6), (44, 23)):                               # his children, in the branches
        ev.prop(x, z, EP_KUMO, msg="Many eyes, in the branches. They are watching the old man, not you.", d=0,
                reqs=[flag("G1184", False)])
    ev.scene(31, 15, "G1184", MAMORU, touch=True)
