def corrupted_glade_approach():
    m = MapSpec("M452", "Shinomen Mori - the glade", 64, 30, base=GRASS3, y=3)
    m.rect(0, 13, 30, 5, DIRT, 3)
    m.rect(28, 4, 36, 24, POPPYF, 3)                                        # flowers that aren't petal
    m.rect(44, 10, 9, 7, WATER, 2)                                          # the pool that reflects the sky wrong
    for x, z in ((34, 7), (38, 22), (56, 6), (58, 22), (48, 24), (32, 12), (54, 19), (41, 9)):
        m.rect(x, z, 3, 2, TARSTAIN, 3)                                     # black stains where things grew wrong
    rng = np.random.default_rng(452)
    for _ in range(90):                                                     # red flowers that aren't petal
        x, z = int(rng.integers(29, 63)), int(rng.integers(5, 27))
        if not (43 <= x <= 53 and 9 <= z <= 17) and not (28 <= x <= 32 and 13 <= z <= 19):
            m.block(x, z, FLOWER_R)
    forest_trees(m, rng, 70, [(0, 30, 11, 20), (26, 64, 2, 28)])
    m.tree(36, 15, TREE_L)                                                  # the largest tree
