def battle_glade():
    m = MapSpec("M806", "Battle: the corrupted glade", 128, 128, base=POPPYF, y=0)
    m.rect(10, 52, 34, 24, TARSTAIN, 0)                                     # her mat, behind her
    rng = np.random.default_rng(806)
    for _ in range(90):
        x, z = int(rng.integers(0, 128)), int(rng.integers(0, 128))
        if not (36 <= z <= 80):
            m.block(x, z, FLOWER_R)
    for x in range(3, 128, 7):
        m.tree(x, 88 + (x * 5) % 12, (TREE_L, TREE_M)[x % 2])
        m.tree(x, 18 + (x * 7) % 12, TREE_L)
    return m


def battle_starfield():
    m = MapSpec("M807", "Battle: the starfield (Body of Damned Time)", 128, 128, base=SL_GROUND, y=0)
    m.rect(0, 40, 128, 40, TARSTAIN, 0)
    fill(m, 0, 1, 92, 128, 44, 2, VOID)                                     # the dark behind everything
    fill(m, 0, 1, 0, 2, 44, 92, VOID)
    fill(m, 126, 1, 0, 2, 44, 92, VOID)
    rng = np.random.default_rng(807)
    for _ in range(90):                                                     # the stars: pale specks on the dark
        fill(m, int(rng.integers(0, 128)), int(rng.integers(3, 40)), int(rng.integers(84, 91)), 1, 1, 1, PLASTER)
    return m


