# ---- The epilogue, E01 "Eight Codas" and E02 "Final Image" (production E01/E02; storyboard: reused hub maps). Each
# coda is a one-time scene added to that traveler's map; the traveler walks it alone (plugin fLead: the others wait),
# then the screen goes dark and the next coda's traveler leads. Props show only between that coda and the next.
CODA_FLAGS = ["G1198", "G1199", "G1200", "G1201", "G1202", "G1203", "G1204", "G1205"]   # Natsuko ... Mitsue
CODA_GO = {"G1198": ("P100", "M140", 27, 15, True), "G1199": ("P101", "M200", 31, 16, True),
           "G1200": ("P102", "M454", 9, 5, False), "G1201": ("P103", "M242", 30, 12, True),
           "G1202": ("P104", "M281", 17, 10, True), "G1203": ("P106", "M413", 17, 14, True),
           "G1204": ("P107", "M455", 11, 7, False), "G1205": ("P105", "M382", 30, 15, True),
           "G1206": ("P105", "M456", 20, 12, True)}
UNDARK = [{"cmd": "cmd_screenfxoff", "sfxbits": 7, "time": 900}]


def coda_next(f):
    pid, mid, x, z, padded = CODA_GO[f]
    return [script("::Rokugan.fLead( \"%s\");" % pid)] + DARK + [go(mid, x, z, padded=padded)]


def coda_props(f):
    """While this coda is the current one (from the previous scene until the next begins)."""
    i = CODA_FLAGS.index(f)
    nxt = CODA_FLAGS[i + 1] if i + 1 < len(CODA_FLAGS) else "G1206"
    return [flag("G1197"), flag(nxt, False)]


