def with_coda(builder, f):
    def b(*a, **k):
        m, ev = builder(*a, **k)
        for x, z, mdl, d, extra in CODA_SPOTS.get(f, ()):
            ev.prop(x, z, mdl, d=d, reqs=coda_props(f) + ([extra] if extra else []))
        i = CODA_FLAGS.index(f)
        nxt = CODA_FLAGS[i + 1] if i + 1 < len(CODA_FLAGS) else "G1206"
        x, z = CODA_GO[f][2:4]
        ev.scene(x, z, f, UNDARK + CODA[f] + coda_next(nxt),
                 after=[flag("G1197"), flag(CODA_FLAGS[i - 1] if i else "G1208")])
        return m, ev
    return b


