# ---- The post-game, P1 "the gate back" (storyboards/finale.md F-4: after the credits the Shadowlands reopen through
# the Wall gate; bestiary F "Post-game: Shadowlands deep / Hiruma Castle", Lv 61-80). Its own maps, not Crab Ch3's
# (those replay Natsuko's chapter in a save that never walked it): a road-marker at the Shrine of Osano-Wo (after the
# clear, G1207) -> M457 the Kaiu Wall's Shinomen gate (the T5 smith, a waystone) -> M458-M460 the deep road, Lv 61-68
# -> Hiruma Castle (P2, not built). Taint tiles as in Crab Ch3; the battle backdrop is the Shadowlands' (M817).
PG_ROAD = [narrate("A Crab rider at the shrine gate, mud to the knees: the Kaiu Wall has opened its Shinomen gate. "
                   "The Hida are sending scouts into the deep Shadowlands, past anywhere on the maps."),
           narrate("(The post-game: the deep Shadowlands, Lv 61+. Recommended level 61.)"),
           choices(("Ride south to the Wall. (Three days)", DARK + [go("M457", 6, 15)]), ("Not now.", []))]


def wall_shinomen_gate():
    m = MapSpec("M457", "Kaiu Wall - the Shinomen gate", 72, 40, base=T(0, 5), y=2)
    m.rect(0, 0, 72, 6, GRASS, 2)
    kaiu_wall(m, 30, 40, 16, crenel_z=30)
    fill(m, 52, 3, 30, 7, 9, 1, VOID)                                       # the gate, open
    building(m, 8, 18, 12, 7, wall=WOOD)                                    # the Kaiu forge
    building(m, 26, 18, 14, 7)                                              # the scouts' barracks
    for x in (6, 46, 64):
        fb(m, x, 15, 2, LAMP_STREET)
    ev = Events(m)
    ev.talk(1, 15, "CE000", [(None, [narrate("North, back to the Shrine of Osano-Wo."),
                                     choices(("Ride north. (Three days)", DARK + [go("M445", 86, 15)]),
                                             ("Stay.", []))])], trigger=5)
    ev.clerk(14, 16, EP_SERVICE["quartermaster"], "R170")
    ev.npc(30, 15, SC["townguard"], "Nobody's gone this deep since the Hiruma lost their castle. Bring back maps. "
                                    "Bring back yourselves.")
    ev.npc(46, 13, EP["veteran"], "Forty years on the Wall and I've never seen this gate open. Twice in one year, now.")
    waystone(m, ev, 40, 12)
    ev.talk(55, 28, "CE000", [(None, [narrate("The Shinomen gate stands open. Beyond it the ground goes black."),
                                      choices(("Go through.", [go("M458", 5, 16)]), ("Not yet.", [step_back(0, -2.0)]))])],
            trigger=5)
    return m, ev


def deep_road(mid, name, seed, base, tiles, nxt, prev, chests, extra=None, pre=()):
    m = MapSpec(mid, name, 112, 40, base=base, y=3)
    sl_ground(m, seed)
    rng = np.random.default_rng(seed)
    for _ in range(6):
        x, z = int(rng.integers(8, 100)), int(rng.integers(3, 24))
        if not 12 <= z <= 19:
            m.rect(x, z, int(rng.integers(5, 10)), int(rng.integers(3, 6)), tiles)
    ev = Events(m)
    ev.talk(1, 16, "CE000", [(None, [go(*prev)])], trigger=5)               # back (map moves: the far ends are
    if nxt:                                                                 # touch triggers, so no landing on one)
        ev.talk(110, 16, "CE000", [(None, list(pre) + [go(nxt, 4 if nxt in MAZE else 5, 24 if nxt in MAZE else 16)])],
                trigger=5)
    for x, z, item, num in chests:
        ev.chest(x, z, item, num)
    if extra:
        extra(m, ev)
    return m, ev


def deep_road_1():
    def extra(m, ev):                                                       # the way through, told (memory
        ev.talk(14, 13, "CE000", [(None, [                                  # counters-known-and-available)
            narrate("A Hiruma waymarker, half sunk in the black earth. Under the crab mon, a scout's chant is scratched "
                    "deep, the way the Hiruma teach it to children:"),
            narrate("\"East. West. North. South. West, west, east. Never twice south.\""),
            say("Natsuko", "(touching it) Father taught me that one. The ground out there doesn't stay where you leave "
                           "it. The chant does.")])], trigger=1)
    return deep_road("M458", "Shadowlands deep - the Fallen road", 458, SL_GROUND, TARSTAIN, "M459", ("M457", 55, 26),
                     [(30, 24, "I130", 2), (74, 6, "I131", 3)], extra, pre=[setf("G1223", False)])


# ---- The shifting waste (user, 2026-11-07: "shadowlands by lore seems to move around ... there should be a special
# way to navigate the edges ... if you go south 2x you go back to beginning map (where you can exit back to the wall or
# try again)"). A lost-woods maze between the Fallen road (M458, the start: west leads back to the Wall gate) and the
# Hiruma road (M460). Six maze maps, open on all four edges; MAZE[k-1] is where you stand after k right turns. The way
# through is the Hiruma scouts' chant on the waymarker at the start: East, West, North, South, West, West, East. A
# wrong edge sends you back one map; south twice in a row (G1223 = the last move was south) folds you back to the start.
# Camera faces north: north is up the screen (the back edge), south is down (the front edge).
MAZE = ["M459", "M465", "M466", "M467", "M468", "M469"]
MAZE_SEQ = "ewnswwe"
MAZE_ARRIVE = {"e": (4, 24), "w": (67, 24), "n": (36, 4), "s": (36, 43)}      # landing side by the move just made
SHIFT = narrate("The ground shifts underfoot, like a rug pulled by a hand you can't see. ...This place again.")
FOLD = narrate("The Shadowlands fold like paper. You're back where the road began.")


def maze_move(k, d):
    """Commands for leaving maze state k (1-6) by edge d."""
    def to(state, d):
        if state <= 0:
            return [go("M458", 12, 16)]
        if state > len(MAZE):
            return [go("M460", 5, 16)]
        return [go(MAZE[state - 1], *MAZE_ARRIVE[d])]
    right = MAZE_SEQ[k] == d
    normal = [setf("G1223", d == "s")] + ([] if right else [SHIFT]) + to(k + 1 if right else k - 1, d)
    if d == "s":
        return [if_([flag("G1223")], [setf("G1223", False), FOLD] + to(0, d), normal)]
    return normal


def shifting_waste(k):
    mid = MAZE[k - 1]
    m = MapSpec(mid, "Shadowlands deep - the shifting waste", 72, 48, base=SL_GROUND, y=3)
    rng = np.random.default_rng(900 + k)
    tile = (TARSTAIN, EMBER, POPPYF)[k % 3]
    for _ in range(int(72 * 48 / 70)):                                      # ash drifts
        x, z = int(rng.integers(0, 68)), int(rng.integers(0, 45))
        m.rect(x, z, int(rng.integers(2, 6)), int(rng.integers(1, 4)), SL_ASH)
    for _ in range(5):                                                      # corrupted patches (Taint tiles)
        x, z = int(rng.integers(6, 60)), int(rng.integers(6, 38))
        if not (30 <= x + 3 <= 42 or 20 <= z + 2 <= 28):                     # keep the cross-paths clear
            m.rect(x, z, int(rng.integers(4, 9)), int(rng.integers(3, 6)), tile)
    for _ in range(18):                                                     # rocks and old bones
        x, z = int(rng.integers(3, 69)), int(rng.integers(3, 45))
        if not (32 <= x <= 40 or 20 <= z <= 28):
            m.tree(x, z, (ROCK_M, ROCK_S)[int(rng.integers(0, 2))])
    lx, lz = (12, 36) if k % 2 else (58, 10)                                # a landmark, so a map can be recognised
    fill(m, lx, 4, lz, 2, 5 + k % 3, 2, STONE)
    fill(m, lx + 3, 4, lz + 1, 1, 3, 1, STONE)
    ev = Events(m)
    for d, (x, z) in {"w": (1, 24), "e": (70, 24), "s": (36, 1), "n": (36, 46)}.items():
        ev.talk(x, z, "CE000", [(None, maze_move(k, d))], trigger=5)
    if k == 3:
        ev.chest(54, 34, "I130", 3)
    if k == 5:
        ev.chest(18, 12, "N000", 4000)
    return m, ev


def deep_road_3():
    def extra(m, ev):
        waystone(m, ev, 96, 12)
        ev.talk(110, 16, "CE000", [                                         # (on the east edge: the whole edge leads on)
            (None, [narrate("The road goes on east, into hills the colour of old blood. On the highest of them, "
                            "something with walls."),
                    say("Natsuko", "(very quietly) ...That's on Father's map."), setf("G1215"),
                    choices(("Go on, to the castle.", DARK + [go("M461", 5, 16)]), ("Not yet.", [step_back(-2.0, 0)]))]),
            ([flag("G1215")], [choices(("On to Shiro Hiruma.", [go("M461", 5, 16)]),
                                       ("Not yet.", [step_back(-2.0, 0)]))])], trigger=5)
    return deep_road("M460", "Shadowlands deep - the Hiruma road", 460, SL_GROUND, POPPYF, None, ("M458", 106, 16),
                     [(26, 6, "I130", 3), (70, 24, "I131", 3)], extra)


def shrine_pg_marker(builder):
    def b(*a, **k):
        m, ev = builder(*a, **k)
        ev.talk(92, 15, SC["townguard"], [(None, PG_ROAD)], reqs=[flag("G1207")])
        return m, ev
    return b


MAPS["M445"] = shrine_pg_marker(MAPS["M445"])
MAPS.update({"M457": wall_shinomen_gate, "M458": deep_road_1, "M460": deep_road_3})
MAPS.update({mid: (lambda k: (lambda: shifting_waste(k)))(i + 1) for i, mid in enumerate(MAZE)})
TAINT_TILES.update({"M458": ([TARSTAIN], 6), "M460": ([POPPYF], 6)})
TAINT_TILES.update({mid: ([TARSTAIN, EMBER, POPPYF], 5) for mid in MAZE})


# ---- The post-game, P2 "Shiro Hiruma" (finale.md post-game: the Hiruma Castle side story, the canon Hare sword;
# 00-synthesis.md: the lost Hare Clan sword recovered from the ruins of Shiro Hiruma, 1123; 02-travelers.md: Natsuko's
# father died mapping the road back, "thirty years of work"). Lv 68-75. M461 the outer bailey (the map), M462 the keep
# (the ancestors; waystone), M463 the lord's hall: Oni no Okura (gid 172, M808), then the Hare Sword (W157) on the
# throne and the last line of the map. Okura is the 1999 CCG's: Akuma's daughter, at the edge of the Shadowlands.
BAILEY = [narrate("Shiro Hiruma. The Hiruma's castle, lost fifteen generations ago to the Shadowlands, and never "
                  "retaken."),
          narrate("The outer walls still stand. The gate is a hole. Everything inside is black."),
          narrate("Hiruma Natsuko takes the oiled case from her pack, and unrolls her father's map on a fallen stone."),
          say("Natsuko", "Thirty years of work."),
          narrate("Every landmark they passed is on it, in his careful hand: the tar, the poppies, the bone fields. The "
                  "last line stops a day short of the castle. Where he died."),
          say("Natsuko", "...He was right. All of it. It leads here."),
          say("Sayo", "(gently) Then let's finish it for him.")]
KEEP_ANCESTORS = [narrate("The keep's shrine. The kami-shelf is broken, the tablets scattered. Hiruma names, hundreds of "
                          "them, under the soot."),
                  narrate("Natsuko sets the tablets back up, one by one. It takes a long time. Nobody hurries her."),
                  say("Natsuko", "We're back. Not for good. Not yet. But we came."),
                  narrate("For a moment, the cold in the keep is a little less cold.")]
OKURA = [narrate("The lord's hall of Shiro Hiruma. On the dais, in the lord's own armour, something with horns and a "
                 "blue face sits the Hiruma throne as if it were born there."),
         say("Oni no Okura", "Little Hiruma. You brought a map. How sweet. Your father brought one too."),
         say("Natsuko", "(very still) ...You met him."),
         say("Oni no Okura", "My father took a Jade Champion's name. I took a castle. He took a road a day too far."),
         say("Natsuko", "Then this is the last day of the road."),
         dict(battle("M001", 172), losefunc=1),
         if_([WON], [
             narrate("Okura falls back across the dais, and comes apart like a burned scroll. The armour stays behind, "
                     "empty, as it was always supposed to be."),
             narrate("On the throne, under fifteen generations of dust: a katana with a running hare on the tsuba. "
                     "Not a Crab blade at all."),
             say("Natsuko", "A Usagi sword. In the Hiruma's castle. (turning it over) Somebody carried this a long "
                            "way, a long time ago."),
             say("Gendo", "(pushing his spectacles up) I'd like to know who. I'd also like to know why. I'll file it."),
         ] + got("W157", "the Hare Sword") + [
             narrate("Natsuko takes out her father's map, and a stick of charcoal, and draws the last line: from the "
                     "bone fields, up the hill, to the gate."),
             say("Natsuko", "There, Father. It leads home."),
             narrate("(Shiro Hiruma - cleared. The Hiruma have a road home, and a map that proves it.)"),
             setf("G1218")],
             [say("Oni no Okura", "Run home, little Hiruma. Oh - you can't. You haven't got one.")])]


def hiruma_bailey():
    m = MapSpec("M461", "Shiro Hiruma - the outer bailey", 110, 40, base=SL_GROUND, y=3)
    sl_ground(m, 461, back_z=32)
    for x in range(0, 110, 1):                                              # the outer wall behind, broken
        if not (50 <= x <= 56) and (x * 7) % 11:
            fill(m, x, 4, 28, 1, 6 + (x * 5) % 4, 3, STONEW)
    for (x, z, w, d, h) in ((20, 6, 8, 1, 3), (40, 22, 1, 5, 4), (70, 5, 10, 1, 2), (88, 20, 6, 1, 3)):
        fill(m, x, 4, z, w, h, d, STONEW)                                   # fallen walls in the bailey
    for (x, z, w, d) in ((28, 18, 8, 4), (76, 9, 7, 4)):
        m.rect(x, z, w, d, TARSTAIN)
    ev = Events(m)
    ev.talk(1, 16, "CE000", [(None, [go("M460", 104, 16)])], trigger=5)
    ev.scene(10, 16, "G1216", BAILEY)
    ev.talk(108, 16, "CE000", [(None, [narrate("The keep's gate, a black mouth."),
                                       choices(("In.", [go("M462", 5, 16)]), ("Not yet.", [step_back(-2.0, 0)]))])],
            trigger=5)
    ev.chest(24, 24, "I130", 3)
    ev.chest(80, 6, "N000", 5000)
    return m, ev


