def pad(m, ev):
    """Surround the playable area with scenery that continues the edge terrain (the camera never shows the void):
    edge columns are replicated outward, objects/events shift, and trees are scattered on the new land."""
    px, pt, pb = PAD_X, PAD_TOP, PAD_BOTTOM
    m.blk = np.pad(m.blk, ((pb, pt), (px, px)), mode="edge")
    m.hgt = np.pad(m.hgt, ((pb, pt), (px, px)), mode="edge")
    for o in m.objs:
        o["x"] += px
        o["z"] += pb
    m.walls = [(x + px, z + pb) for x, z in m.walls]                       # extra no-entry cells move too
    if ev:
        for e in ev.ev.values():
            e["pos"][0] += px
            e["pos"][2] += pb
    w0, d0 = m.w, m.d
    m.w, m.d = m.w + 2 * px, m.d + pb + pt
    rng = np.random.default_rng(len(m.mid) * 97 + int(m.mid[1:]))
    soft = {GRASS, GRASS2, GRASS3, T(2, 0), T(2, 1), DIRT3}
    for _ in range(int((m.w * m.d - w0 * d0) / 22)):
        x, z = int(rng.integers(1, m.w - 1)), int(rng.integers(1, m.d - 1))
        inside = px - 2 <= x < px + w0 + 2 and pb - 2 <= z < pb + d0 + 2
        if inside or int(m.blk[z, x]) not in soft:
            continue
        if int(m.blk[z, x]) == DIRT3:                                      # Shadowlands: rocks, no green
            m.tree(x, z, (ROCK_S, ROCK_M)[int(rng.integers(0, 2))])
        else:
            m.tree(x, z, (TREE_L, TREE_M, TREE_S, TREE_L)[int(rng.integers(0, 4))])
    return px / 2.0, pb / 2.0


