def _route_gate(pids):
    for f, p in ROUTE_GATES.items():
        if p == pids:
            return f
    f = "G%d" % (1300 + len(ROUTE_GATES))
    ROUTE_GATES[f] = list(pids)
    return f


for _r in ROUTES:                                                          # gate flags in a fixed order
    _route_gate(_r[4][2])
    _route_gate(_r[5][2])


def _tier_rows(pid, tier):
    """The re-levelled encounter rows of a path's ladder band (ENCOUNTERS after apply_ladders), conditions dropped."""
    import ladders as _lad
    rows, bmap = [], None
    for i, (path, done, maps) in enumerate(_lad.LADDERS):
        t = 1 if i < 8 else 2 if i < 15 else 3 if i < 23 else 4
        if LADDER_PID_EARLY.get(path) != pid or t != tier:
            continue
        for mid, _lo, _hi in maps:
            if mid not in ENCOUNTERS:
                continue
            bm, table = ENCOUNTERS[mid]
            for r in table:
                c = r[3] if len(r) > 3 else {}
                if done in (c.get("rt_if"), c.get("rt_if2")):
                    rows.append((r[0], list(r[1]), r[2]))
                    bmap = bmap or bm
    return rows, bmap


LADDER_PID_EARLY = {"Crab": "P100", "Crane": "P101", "Dragon": "P102", "Lion": "P103", "Phoenix": "P104",
                    "Scorpion": "P105", "Unicorn": "P106", "Ronin": "P107"}


def route_encounters(pids_a, pids_b, tier):
    """Up to 6 groups: both ends' paths at this band (the nearest band that has any)."""
    for t in [tier] + sorted({1, 2, 3, 4} - {tier}, key=lambda v: abs(v - tier)):
        ra, rb, bm = [], [], None
        for pid in pids_a:
            rows, b = _tier_rows(pid, t)
            ra += rows
            bm = bm or b
        for pid in pids_b:
            rows, b = _tier_rows(pid, t)
            rb += rows
            bm = bm or b
        mix = [r for pair in zip(ra, rb) for r in pair] + ra[len(rb):] + rb[len(ra):]
        if mix:
            return bm, mix[:6]
    return None, []


def _danger(rows):
    lv = [int(x) for r in rows for x in re.findall(r"\(Lv (\d+)\)", r[0])]
    return "Danger %d-%d" % (min(lv), max(lv)) if lv else "Danger unknown"


def _edge_spot(m, ev, side):
    """A cell on the builder's edge for a new way out: dry, not in a building, away from other events, with level
    ground inward; a road cell first, then nearest the middle of the edge."""
    solid = set()
    for o in m.objs:
        if o["t"] == "fill" and o["blk"] != 0:
            solid.update((o["x"] + i, o["z"] + j) for i in range(o["w"]) for j in range(o["d"]))
    taken = [(e["pos"][0], e["pos"][2]) for e in ev.ev.values() if "pos" in e]
    inw = {"w": (1, 0), "e": (-1, 0), "f": (0, 1), "b": (0, -1)}[side]
    if side in ("w", "e"):
        x = 1 if side == "w" else m.w - 2
        cand = [(x, z) for z in range(4, m.d - 4)]
    else:
        z = 1 if side == "f" else m.d - 2
        cand = [(x, z) for x in range(6, m.w - 6)]

    def ok(c, depth, half, step, gap):
        x, z = c
        h0 = int(m.hgt[z, x])
        for k in range(depth):
            cx, cz = x + inw[0] * k, z + inw[1] * k
            for a in range(-half, half + 1):
                px, pz = (cx, cz + a) if side in ("w", "e") else (cx + a, cz)
                if not (0 <= px < m.w and 0 <= pz < m.d) or (int(m.blk[pz, px]) & 31) == 8 or (px, pz) in solid \
                        or abs(int(m.hgt[pz, px]) - h0) > step:
                    return False
        return all(abs(x - a) + abs(z - b) > gap for a, b in taken)
    good = []
    for rule in ((8, 2, 1, 6), (5, 1, 2, 4), (3, 1, 2, 3)):                # strict first, then looser
        good = [c for c in cand if ok(c, *rule)]
        if good:
            break
    if not good:
        raise RuntimeError("%s: no room for a route exit on side %s" % (m.mid, side))
    mid = (m.d if side in ("w", "e") else m.w) // 2
    along = 1 if side in ("w", "e") else 0
    return min(good, key=lambda c: (int(m.blk[c[1], c[0]]) != ROAD, abs(c[along] - mid)))


def route_hub(builder, hub, rid, side, route_ev):
    def b(*a, **k):
        r = builder(*a, **k)
        m, ev = r if isinstance(r, tuple) else (r, None)
        x, z = _edge_spot(m, ev, side)
        n = ev.portal(x, z, rid, route_ev, d=0)
        ROUTE_EV[(hub, rid)] = n
        return m, ev
    return b


ROUTE_THEME = {   # ground, side band (blk, z0, z1), trees
    "coast": (GRASS, (SAND, 24, 30), (TREE_S, ROCK_S, ROCK_M)),
    "forest": (GRASS2, None, (TREE_L, TREE_M, TREE_L, TREE_S)),
    "hills": (GRASS, None, (TREE_L, TREE_M, TREE_S, ROCK_S)),
    "snow": (SNOW, None, (TREE_S, ROCK_S, ROCK_M)),
    "mountain": (T(2, 0), None, (ROCK_S, ROCK_M, TREE_S)),
}


def route_map(r):
    rid, name, theme, tier, A, B, caves = r
    W, D = 130, 40
    ground, band, trees = ROUTE_THEME[theme]
    m = MapSpec(rid, name, W, D, base=ground, y=3)
    if band:
        m.rect(0, band[1], W, band[2] - band[1], band[0], 3)
    m.rect(0, 16, W, 5, ROAD, 3)                                             # the road, west to east
    ends, spurs = [], []
    for k, (hub, hside, pids) in enumerate((A, B)):
        rs = _OPP[hside]
        x0 = 12 if k == 0 else W - 13
        pos = {"w": (1, 18), "e": (W - 2, 18), "f": (x0, 1), "b": (x0, D - 2)}[rs]
        if rs == "f":
            m.rect(x0 - 2, 0, 5, 17, ROAD, 3)
            spurs.append((x0, 0, 17))
        elif rs == "b":
            m.rect(x0 - 2, 20, 5, D - 20, ROAD, 3)
            spurs.append((x0, 20, D))
        ends.append((hub, pids, pos))
    cave_x = [44, 86][:len(caves)] if len(caves) > 1 else [64]
    rng = np.random.default_rng(int(rid[1:]))
    for _ in range(140):                                                   # scenery, off the road, spurs and caves
        x, z = int(rng.integers(1, W - 1)), int(rng.integers(1, D - 1))
        if 13 <= z <= 23 or any(abs(x - sx) <= 4 and z0 - 1 <= z <= z1 for sx, z0, z1 in spurs) \
                or any(abs(x - cx) <= 5 and z >= 22 for cx in cave_x):
            continue
        m.tree(x, z, trees[int(rng.integers(0, len(trees)))])
    for cx in cave_x:
        m.rect(cx - 2, 21, 5, 5, DIRT, 3)                                   # a trodden path up to the mouth
        fb(m, cx, 27, 3, 21)                                                # the cave mouth
    ev = Events(m)
    for k, (hub, pids, pos) in enumerate(ends):                            # events 1, 2: the ends
        if (hub, rid) not in ROUTE_EV:
            MAPS[hub]()                                                     # (registers the hub's way onto here)
        n = ev.portal(pos[0], pos[1], hub, ROUTE_EV[(hub, rid)], d=0)
        e = ev.ev["#%d#" % n]
        e["reqs0"] = [flag(_route_gate(pids))]
        e["closed_msg"] = ("The road on is closed. %s's lands - that road isn't walked yet. When %s has walked it, "
                           "this way opens." % (ROUTE_NAME[pids[0]], ROUTE_NAME[pids[0]]))
    for i, (cid, cname, plus) in enumerate(caves):                         # events 3, 4: the caves
        ev.portal(cave_x[i], 25, cid, 1, d=0)
    bm, rows = ROUTE_ENC.get(rid, (None, []))
    for k, (hub, pids, pos) in enumerate(ends):
        sx = min(max(pos[0] + (4 if k == 0 else -4), 3), W - 4)
        ev.talk(sx, 14, "CE000", [(None, [narrate("A road-stone: \"This way: %s. Back: %s. %s.\"" % (
            MAP_TITLE.get(ends[1 - k][0], "the next lands"), MAP_TITLE.get(ends[k][0], "the last lands"),
            _danger(rows)))])], trigger=1)
    for i, cx in enumerate(cave_x):
        cbm, crows = ROUTE_ENC.get(caves[i][0], (None, []))
        ev.talk(cx + 3, 24, "CE000", [(None, [narrate("A cave mouth. Cold air, and old bones by the entrance. "
                                                      "(%s)" % _danger(crows))])], trigger=1)
    loot = ROUTE_LOOT[min(tier, 4)]
    ev.chest(30, 11, *loot[0])
    ev.chest(W - 34, 26 if theme != "coast" else 11, *loot[1])
    return m, ev


MAP_TITLE = {"M103": "Hoshi-no-Ichi", "M213": "Yasuki Yashiki", "M351": "Kudo", "M424": "Floating Flowers",
             "M255": "Shiro Akodo", "M430": "the Wounded Lion", "M282": "Zumiki", "M415": "Cakon",
             "M228": "Kyuden Doji", "M252": "Shiro no Kamatori", "M379": "the Dragon mountain town",
             "M387": "the Town of Buried Leaves", "M202": "Pleasant Eaves", "M347": "Kyuden Bayushi"}


def route_cave(cid, name, tier, rid, back_ev, seed):
    """A side cave: five chambers in a chain, tunnels 4 wide (a full block to walk through everywhere), chests by
    difficulty; cave_sprawl grows galleries (and a save shrine) off it."""
    rng = np.random.default_rng(seed)

    def j(v):
        return int(v + rng.integers(-3, 4))
    rooms = [(20, 9, 7, 5), (j(46), j(15), 10, 6), (j(26), j(30), 9, 6), (j(58), j(33), 11, 7), (j(82), j(20), 9, 6)]
    links = [(20, 0, 20, 8, 4)] + [(a[0], a[1], b[0], b[1], 4) for a, b in zip(rooms, rooms[1:])]
    m = cave_map(cid, name, 100, 46, rooms, links, seed=seed)
    ev = Events(m)
    ev.portal(20, 1, rid, back_ev, d=2)                                     # event 1: out to the road
    loot = ROUTE_LOOT[min(tier, 4)]
    for k, (cx, cz, rx, rz) in enumerate(rooms[1:], 1):
        ev.chest(cx + 2, cz, *loot[k % len(loot)])
    return m, ev


ROUTE_ENC = {}
for _r in ROUTES:
    _rid, _nm, _th, _tier, _A, _B, _caves = _r
    _bm, _rows = route_encounters(_A[2], _B[2], _tier)
    if _rows:
        ROUTE_ENC[_rid] = (_bm, _rows)
    for _i, (_cid, _cn, _plus) in enumerate(_caves):
        _cbm, _crows = route_encounters(_A[2], _B[2], min(_tier + _plus, 4))
        if _crows:
            ROUTE_ENC[_cid] = (_cbm, _crows)
        MAPS[_cid] = (lambda c=_cid, n=_cn, t=min(_tier + _plus, 4), r=_rid, k=_i, s=int(_cid[1:]):
                      route_cave(c, n, t, r, 3 + k, s))
        RSET[_cid] = "rt_hd2d_cave"
    for _k, (_hub, _side, _pids) in enumerate((_A, _B)):
        MAPS[_hub] = route_hub(MAPS[_hub], _hub, _rid, _side, 1 + _k)
    MAPS[_rid] = (lambda r=_r: route_map(r))
ENCOUNTERS.update(ROUTE_ENC)
ENCOUNTER_MAPS |= set(ROUTE_ENC)


def marker_pass(mp):
    """(user 2026-11-14: "a floating quest marker ... that shows you where to go next according to your currently
    selected quest, edge of screen taking the player to the next map over, to a door, etc.") Writes
    RokuganMarkerData.sk for plugin RokuganMarker.sk, all in world units (blocks / 2):
      MK_EXITS  map -> [[dest map, x, z, half x, half z], ...]  the ways out a player can walk (doors, edges, portals)
      MK_LINKS  map -> [dest map, ...]                           every map move, story ones too (for the road search)
      MK_BEATS  [[map, x, z, [[lvar, op, rvar], ...]], ...]      once-scenes: due when their reqs hold
      MK_PATH   map -> traveler                                  whose road a map belongs to (from PATH_START)
      MK_QUEST  quest id -> [giver map, x, z, hunt map, x, z]    the Journal's side quests and odd jobs"""
    exits, links, beats = {}, {}, []
    route_ids = {r[0] for r in ROUTES} | {c[0] for r in ROUTES for c in r[6]}

    def dests(e):
        out = set()
        if e.get("role") == "portal" and (e.get("dest") or {}).get("mapid"):
            out.add(e["dest"]["mapid"])
        for s in json.dumps(e.get("page") or []).split('"cmd_mapmove"')[1:]:
            mm = re.search(r'"mapid": "(M\d{3})"', s)
            if mm:
                out.add(mm.group(1))
        return out
    for mid, m in mp.items():
        if not re.fullmatch(r"M\d{3}", mid) or "M800" <= mid < "M900" or mid in DEBUG_MAPS:
            continue
        for e in (m.get("event") or {}).values():
            if not isinstance(e, dict) or "pos" not in e:
                continue
            js = json.dumps(e)
            pages = e.get("page") or []
            trig = {pg.get("trigger") for pg in pages}
            x, z = e["pos"][0] / 2.0, e["pos"][2] / 2.0
            ds = dests(e) - {mid}
            if ds and "pathBegin" not in js and "pathFinale" not in js:
                links.setdefault(mid, set()).update(ds)
                if e.get("role") == "portal" or trig & {1, 5}:
                    r = (e.get("mdl") or {}).get("r") or [0, 1.0, 0, 1.0, 1.0, 0.5]
                    long_z = len(e["pos"]) > 3 and e["pos"][3] in (1, 3)
                    hx, hz = (r[5], r[3]) if long_z else (r[3], r[5])
                    for dm in sorted(ds):
                        exits.setdefault(mid, []).append([dm, round(x, 2), round(z, 2), round(hx, 2), round(hz, 2)])
            for pg in pages:
                if pg.get("trigger") not in (5, 6):
                    continue
                cb = pg.get("cmdblock") or []
                if cb and cb[0].get("cmd") == "cmd_if":
                    reqs = cb[0].get("reqs") or []
                    if reqs and reqs[0].get("op") == "==" and reqs[0].get("rvar") is False:
                        beats.append([mid, round(x, 2), round(z, 2),
                                      [[r_.get("lvar"), r_.get("op"), r_.get("rvar")] for r_ in reqs]])
    path_of = {}
    # (tester 2026-11-14: one road after another let the Crab road flood every map its story links reach - the Crane
    # maps came out "P100", and no map was Crane's or Phoenix's) all eight roads at once, breadth-first: a map belongs
    # to the road that reaches it first
    q = [((dest.get("dest") or {}).get("mapid"), pid) for pid, f, dest in PATH_START]
    # (each road's last map too: the Scorpion and Unicorn ends were reached first from other roads)
    q += [(gm_, next(p for p, g in CH4_DONE.items() if g == v[2])) for gm_, v in FINALE_GATES.items()]
    while q:
        cur, pid = q.pop(0)
        if not cur or cur in path_of or cur in route_ids or "M444" <= cur <= "M469" or cur < "M100":
            continue
        path_of[cur] = pid
        q += [(n, pid) for n in sorted(links.get(cur, ()))]
    # a map numbered between exactly one road's first and last map is that road's (the Unicorn maps M399-M412 were
    # reached first from the Scorpion road)
    span = {}
    for pid, f, dest in PATH_START:
        a = (dest.get("dest") or {}).get("mapid")
        b = next((m_ for m_, v in FINALE_GATES.items() if CH4_DONE.get(pid) == v[2]), None)
        if a and b:
            span[pid] = (a, b)
    span = {p: (a, b) for p, (a, b) in span.items()                       # (Lion and Phoenix interleave: BFS there)
            if not any(q != p and a <= b2 and a2 <= b for q, (a2, b2) in span.items())}
    for m_ in list(path_of):
        inside = [p for p, (a, b) in span.items() if a <= m_ <= b]
        if len(inside) == 1:
            path_of[m_] = inside[0]
    # the end-of-road objective (scene "G1230", shown once) stays due until that road is walked
    for b in beats:
        if b[3] and b[3][0][0] == "G1230" and path_of.get(b[0]) in PATH_WALKED:
            b[3][0] = [PATH_WALKED[path_of[b[0]]], "==", False]
    quest = {}

    def find(mid, needle):
        for e in ((mp.get(mid) or {}).get("event") or {}).values():
            if isinstance(e, dict) and "pos" in e and needle in json.dumps(e):
                return [mid, round(e["pos"][0] / 2.0, 2), round(e["pos"][2] / 2.0, 2)]
        return None
    for k, q_ in enumerate(SIDE_QUESTS):
        key, road, title, gmap, x, z, spr, gname, opens, hmap, gids, *_ = q_
        g = find(gmap, json.dumps("Side quest: %s" % title)[1:-1])
        h = find(hmap, '"lvar": "%s", "op": "==", "rvar": false' % SQ_FLAGS[key][1])
        if g and h:
            quest[100 + k] = g + h
    for k, q_ in enumerate(FETCH_QUESTS):
        key, title, gmap, gx, gz, spr, gname, imap, *_ = q_
        g = find(gmap, json.dumps("Odd job: %s" % title)[1:-1])
        h = find(imap, '"lvar": "%s", "op": "=", "rvar": true' % FQ_FLAGS[key][1])
        if g and h:
            quest[200 + k] = g + h

    def sq(v):
        return json.dumps(v).replace("false", "false").replace("true", "true").replace("null", "null")
    out = os.path.join(PROJ, "plugin", "rokugan", "RokuganMarkerData.sk")
    with open(out, "w", encoding="utf-8") as f:
        f.write("//\tgenerated by tools/gen_maps.py marker_pass (the floating quest marker, RokuganMarker.sk)\n")
        f.write("::Rokugan.MK_EXITS <- {\n%s\n};\n" % ",\n".join('\t%s = %s' % (k, sq(v)) for k, v in sorted(exits.items())))
        f.write("::Rokugan.MK_LINKS <- {\n%s\n};\n" % ",\n".join('\t%s = %s' % (k, sq(sorted(v)))
                                                              for k, v in sorted(links.items())))
        f.write("::Rokugan.MK_BEATS <- [\n%s\n];\n" % ",\n".join("\t" + sq(b) for b in beats))
        f.write("::Rokugan.MK_PATH <- {\n%s\n};\n" % ",\n".join('\t%s = "%s"' % (k, v) for k, v in sorted(path_of.items())))
        f.write("::Rokugan.MK_QUEST <- {\n%s\n};\n" % ",\n".join('\t[%d] = %s' % (k, sq(v)) for k, v in sorted(quest.items())))
    print("marker: %d maps with exits, %d story beats, %d maps on roads, %d quests" % (
        len(exits), len(beats), len(path_of), len(quest)))


def route_pass():
    """Writes RokuganRouteData.sk: the gate flags for plugin RokuganField routeFlags."""
    path = os.path.join(PROJ, "plugin", "rokugan", "RokuganRouteData.sk")
    body = ", ".join('%s = [%s]' % (f, ", ".join('"%s"' % p for p in pids)) for f, pids in ROUTE_GATES.items())
    open(path, "w", encoding="utf-8").write("//\tgenerated by tools/gen_maps.py route_pass (the connecting routes)\n"
                                            "::Rokugan.ROUTE_GATES <- { %s };\n" % body)


# ------------------------------------------------------------------------------------------- registration / build
# Random-encounter rate (engine: ENCOUNTER += steps x (0.6-2.0) x rate; a fight at 100). The template's 1.0 meant one
# fight per ~100 m: the user walked the whole Coast Road escort without one. 4.0 is a fight every ~25 m on average,
# about every 20-30 steps as in most JRPGs.
ENC_RATE = 5.0


def register(specs, events):
    mpath = os.path.join(PROJ, "data", "map.json")
    mp = json.load(open(mpath, encoding="utf-8"))
    base = mp["M001"]
    for sp in specs:
        if sp.mid in BATTLE_SPECS:
            e = json.loads(json.dumps(mp["M800"]))
            e.update({"name": sp.name, "size": [sp.w, 64, sp.d]})
            if sp.mid in RSET:                                                # a lit backdrop (night forest, cells)
                e["rsetid"] = RSET[sp.mid]
            if events.get(sp.mid):                                            # backdrop props (campfires...)
                e["event"].update(events[sp.mid].ev)
            mp[sp.mid] = e
            continue
        e = json.loads(json.dumps(base))
        ev = events.get(sp.mid)
        e["camwork"] = {"fovy": 30, "hpb": [0, 38, 0], "viewport": 8.0 if sp.mid in INTERIORS else 15.0, "yoffs": 0.5}
        e.update({"name": sp.name, "size": [sp.w, 64, sp.d], "event": ev.ev if ev else {},
                  "encount": [], "encntrate": 0.0, "rsetid": RSET.get(sp.mid, "rt_hd2d_field"),
                  "bgmid": music_for(sp)})
        if sp.mid in TAINT_TILES:                                         # plugin RokuganField taintStep
            blocks, pct = TAINT_TILES[sp.mid]
            e["rt_taint"] = {"blocks": [int(b) for b in blocks], "pct": pct}
        if sp.mid in GALE_TILES:                                          # plugin RokuganField galeStep
            e["rt_gale"] = {"blocks": [int(b) for b in GALE_TILES[sp.mid]]}
        if sp.mid in HEAT_TILES:                                          # plugin RokuganField heatStep
            blocks, pct, dmg = HEAT_TILES[sp.mid]
            e["rt_heat"] = {"blocks": [int(b) for b in blocks], "pct": pct, "dmg": dmg}
        if sp.mid in ENCOUNTER_MAPS:
            bmap, table = ENCOUNTERS[sp.mid]
            spots = [(-0.9, 1.5), (-1.6, -1.9), (0.5, -0.3), (-2.4, 0.25)]       # 4th as in the M001 goblin raid
            groups = []
            for n, row in enumerate(table):
                gname, foes, rate = row[:3]
                g = json.loads(json.dumps(base["encount"][0]))
                g.update({"name": gname, "gid": n + 1, "rate": rate, "mapid": bmap, "bgmid": "MU104",
                          "enemies": [{"id": f, "x": spots[k][0], "z": spots[k][1]} for k, f in enumerate(foes)]})
                g.update(row[3] if len(row) > 3 else {})                    # rt_if / rt_ifnot (plugin RokuganField)
                groups.append(g)
            e["encount"], e["encntrate"] = groups, ENC_RATE
        mp[sp.mid] = e
    ladder_hint_pass(mp)
    chapter_end_pass(mp)
    objective_pass(mp)
    journal_pass(mp)
    route_pass()
    marker_pass(mp)
    json.dump(mp, open(mpath, "w", encoding="utf-8"), ensure_ascii=False, indent="	")


# (user 2026-11-14: "add journal to the menu in game and add selectable objectives there") The Journal's Training
# entries: each levelling ladder (tools/ladders.py) as the maps and foe levels it opens, for RokuganJournal.sk.
LADDER_PID = {"Crab": "P100", "Crane": "P101", "Dragon": "P102", "Lion": "P103", "Phoenix": "P104", "Scorpion": "P105",
              "Unicorn": "P106", "Ronin": "P107"}


def journal_pass(mp):
    from ladders import LADDERS
    rows = []
    for k, (path, done, maps) in enumerate(LADDERS):
        where = "; ".join("%s (Lv %d-%d)" % ((mp.get(mid) or {}).get("name") or mid, lo, hi) for mid, lo, hi in maps)
        later = [d for p, d, _ in LADDERS[k + 1:] if p == path]            # the next ladder of this road replaces it
        rows.append('\t{ pid = "%s", flag = "%s", next = %s, lo = %d, hi = %d, where = %s }' % (
            LADDER_PID[path], done, json.dumps(later[0] if later else None).replace("null", "null"),
            min(m[1] for m in maps), max(m[2] for m in maps), json.dumps(where, ensure_ascii=False)))
    out = os.path.join(PROJ, "plugin", "rokugan", "RokuganJournalData.sk")
    quests = []
    for k, q in enumerate(SIDE_QUESTS):
        key, road, title, gmap, x, z, spr, gname, opens, hmap, gids, offer, hunt, remind, thanks, zeni, job = q
        taken, hunted, done = SQ_FLAGS[key]
        opens_f = [SQ_FLAGS[o][2] if o in SQ_FLAGS else o for o in opens]
        gplace = (mp.get(gmap) or {}).get("name") or gmap
        quests.append('\t{ id = %d, who = "%s", title = %s, open = %s, taken = "%s", hunted = "%s", done = "%s", '
                      'job = %s, offer = %s, hunt = %s, back = %s }' % (
                          100 + k, road, json.dumps(title), json.dumps(opens_f), taken, hunted, done,
                          json.dumps(job), json.dumps("%s: %s has work." % (gplace, _the(gname))),
                          json.dumps(remind), json.dumps("Back to %s in %s." % (_the(gname), gplace))))
    for k, q in enumerate(FETCH_QUESTS):                                   # the Cakon odd jobs: "hunted" = found
        key, title, gmap, gx, gz, spr, gname, imap, ix, iz, offer, found, thanks, zeni = q
        taken, got_, done = FQ_FLAGS[key]
        gplace = (mp.get(gmap) or {}).get("name") or gmap
        iplace = (mp.get(imap) or {}).get("name") or imap
        quests.append('\t{ id = %d, who = "P107", title = %s, open = %s, taken = "%s", hunted = "%s", done = "%s", '
                      'job = null, offer = %s, hunt = %s, back = %s }' % (
                          200 + k, json.dumps("Odd job: " + title), json.dumps([FQ_OPEN]), taken, got_, done,
                          json.dumps("%s: %s has an odd job." % (gplace, _the(gname))),
                          json.dumps("Find it: %s." % iplace),
                          json.dumps("Back to %s in %s." % (_the(gname), gplace))))
    with open(out, "w", encoding="utf-8") as f:
        f.write("//\tGenerated by tools/gen_maps.py journal_pass: the Journal's Training entries (tools/ladders.py)\n"
                "//\tand side quests (SIDE_QUESTS).\n")
        f.write("::Rokugan.JOURNAL_LADDERS <- [\n%s\n];\n" % ",\n".join(rows))
        f.write("::Rokugan.JOURNAL_QUESTS <- [\n%s\n];\n" % ",\n".join(quests))
    print("journal: %d training entries, %d side quests" % (len(rows), len(quests)))


