def fetch_events(ev, mid):
    """Givers and the places their things are found (builder coordinates; before pad)."""
    for k, q in enumerate(FETCH_QUESTS):
        key, title, gmap, gx, gz, spr, gname, imap, ix, iz, offer, found, thanks, zeni = q
        taken, got_, done = FQ_FLAGS[key]
        if mid == gmap:
            ev.talk(gx, gz, SC[spr], [
                (None, [say(gname, "Busy, busy.")]),
                ([flag(FQ_OPEN), flag(taken, False)],
                 [narrate("Odd job: %s" % title), say(gname, offer),
                  choices(("\"I'll do it.\"", [setf(taken), narrate("Odd job taken: %s. (The Journal tracks it.)" %
                                                                     title)]),
                          ("\"Not now.\"", []))]),
                ([flag(taken), flag(got_, False)], [say(gname, "Any luck?")]),
                ([flag(got_), flag(done, False)],
                 [say(gname, thanks), setf(done), {"cmd": "cmd_moneyop", "op": 0, "amount": zeni},
                  narrate("Got %d zeni." % zeni), script("::Rokugan.questExp( 5);"),
                  narrate("${::Rokugan.lastExpText(0)}"), narrate("Odd job done: %s." % title)]),
                ([flag(done)], [say(gname, "Thanks again, ronin.")])], d=2)
        if mid == imap:
            ev.talk(ix, iz, "CE000", [(None, [narrate(found), setf(got_), narrate("Back to %s." % _the(gname))])],
                    reqs=[flag(taken), flag(got_, False)], trigger=1)


def _the(g):
    return "the " + (g[2:] if g.startswith("A ") else g)        # "Hida yojimbo" -> "the Hida yojimbo"


def side_quest_events(m, ev, mid):
    # one giver per spot, with every quest of the chain on it in order (a later page wins when its reqs are met)
    givers = {}
    for k, q in enumerate(SIDE_QUESTS):
        if q[3] == mid:
            givers.setdefault((q[4], q[5]), []).append(q)
    for (x, z), chain in givers.items():
        spr, gname = chain[0][6], chain[0][7]
        pages = [(None, [say(gname, "Busy road. Busy, busy road.")])]
        for q in chain:
            key, road, title, gmap, _x, _z, _s, _g, opens, hmap, gids, offer, hunt, remind, thanks, zeni, job = q
            taken, hunted, done = SQ_FLAGS[key]
            opens_f = [flag(SQ_FLAGS[o][2] if o in SQ_FLAGS else o) for o in opens]
            reward = [{"cmd": "cmd_itemop", "itemid": "N000", "op": 0, "num": zeni, "LV": 1},
                      narrate("Got %d zeni." % zeni)] + got("I001", "Healing Herb", 2)
            if job:
                reward += [script("foreach( m in ::rpgstat.members) if( m) ::Rokugan.ensureJobs( m);"),
                           narrate("${::Rokugan.jobUnlockText(\"%s\")}" % job)]
            pages += [
                (opens_f + [flag(taken, False)],
                 [narrate("Side quest: %s" % title), say(gname, offer),
                  choices(("\"I'll do it.\"", [setf(taken), narrate("Side quest taken: %s. (%s) The Journal "
                                                                   "tracks it." % (title, remind))]),
                          ("\"Not now.\"", []))]),
                ([flag(taken), flag(hunted, False)], [say(gname, remind)]),
                ([flag(hunted), flag(done, False)],
                 [say(gname, thanks), setf(done)] + reward + [narrate("Side quest done: %s." % title)]),
                ([flag(done)], [say(gname, "The road's quieter for it.")])]
        ev.talk(x, z, SC[spr], pages, d=2)
    for k, q in enumerate(SIDE_QUESTS):
        key, road, title, gmap, x, z, spr, gname, opens, hmap, gids, offer, hunt, remind, thanks, zeni, job = q
        taken, hunted, done = SQ_FLAGS[key]
        if mid == hmap:
            fights = []
            for gid in gids:
                fights += [battle(hmap, gid)]
            # the once-flag is set first (scene); a lost or fled fight clears it so the quarry comes again
            ev.scene(6 + 2 * (k % 4), 16, hunted, [narrate(hunt)] + fights[:1] + [
                if_([{"lvar": "RESULT", "op": "==", "rvar": 1}],
                    fights[1:] + [if_([{"lvar": "RESULT", "op": "==", "rvar": 1}],
                                      [narrate("Side quest: %s - done here. Back to %s." % (title, _the(gname)))],
                                      [setf(hunted, False)])],
                    [setf(hunted, False)])], after=[flag(taken)])


def chapter_end_pass(mp):
    n = 0

    def walk(o):
        nonlocal n
        if isinstance(o, dict):
            for v in o.values():
                walk(v)
        elif isinstance(o, list):
            for i, c in enumerate(o):
                t = c.get("text", "") if isinstance(c, dict) and c.get("cmd") == "cmd_showmsg" else ""
                mt = re.match(r'"(.+)" - complete\.$', t)
                if mt and mt.group(1) in CHAPTER_END_OBJ and "Objective" not in json.dumps(o[i + 1:]):
                    j = i + 1                                                   # after the summary line, if any
                    if j < len(o) and isinstance(o[j], dict) and o[j].get("cmd") == "cmd_showmsg" and \
                            not o[j].get("name"):
                        j += 1
                    o.insert(j, narrate(CHAPTER_END_OBJ[mt.group(1)]))
                    n += 1
                    break
            for v in o:
                walk(v)
    for mid in mp:
        walk((mp[mid] or {}).get("event") or {})
    print("chapter ends given an objective:", n)


def ladder_hint_pass(mp):
    """(user 2026-11-12: "NPCs should tell you ... you need to toughen up ... new creatures have moved in. Similar in any
    other level ladder situation") Right where a chapter's completion flag is set, a line says which of its places now
    hold tougher creatures and how tough (tools/ladders.py). The Crab Wall has its own NPCs (wall_garrison)."""
    import ladders as _lad
    hints = {}
    for path, done, maps in _lad.LADDERS:
        names, lo, hi = [], 99, 0
        for mid, a, b in maps:
            nm = (mp.get(mid) or {}).get("name") or mid
            nm = nm.split(" - ")[0] if " - " in nm else nm
            if nm not in names:
                names.append(nm)
            lo, hi = min(lo, a), max(hi, b)
        where = names[0] if len(names) == 1 else ", ".join(names[:-1]) + " and " + names[-1]
        hints[done] = ("Word on the road: new creatures have moved into %s since you passed - tougher than before "
                       "(Lv %d-%d). Good hunting, if you need seasoning before what comes next." % (where, lo, hi))

    def walk(x):
        if isinstance(x, dict):
            for v in list(x.values()):
                walk(v)
            return
        if not isinstance(x, list):
            return
        i = 0
        while i < len(x):
            c = x[i]
            if (isinstance(c, dict) and c.get("cmd") == "cmd_compute" and c.get("lvar") in hints
                    and c.get("op") == "=" and c.get("rvar") is True):
                j = i + 1
                while j < len(x) and isinstance(x[j], dict) and x[j].get("desc") == "RT ladder hint":
                    j += 1
                x[i + 1:j] = [dict(narrate(hints[c["lvar"]]), desc="RT ladder hint")]
                i += 1
            else:
                walk(c)
            i += 1
    for mid in sorted(mp):
        if isinstance(mp[mid], dict):
            walk(mp[mid].get("event"))


# The field HUD (plugin RokuganHUD.sk; user 2026-11-11: "a couple boxes in the lower right hand corner, one that says
# Story: *description of where to go next*. and the 2nd box ... Recommended level of area"). Every narration with
# "Objective:" (or starting "Next:") gets a cmd after it that sets OBJ_VAR to its number in the list written to
# RokuganObjectives.sk; a chapter card's "(Recommended level N)" sets CH_LV_VAR = N.
OBJ_VAR, CH_LV_VAR = "G1227", "G1228"


def objective_pass(mp):
    import re as _re
    # (2026-11-12: saves store the objective's NUMBER; inserting the chapter cards renumbered the list and an old save
    # showed a Chapter 2 line in Chapter 4) a kept registry: known lines keep their numbers, new ones go at the end
    reg_path = os.path.join(HERE, "_objectives.json")
    objs = json.load(open(reg_path, encoding="utf-8")) if os.path.exists(reg_path) else []
    if not objs and os.path.exists(os.path.join(PROJ, "plugin", "rokugan", "RokuganObjectives.sk")):
        old = open(os.path.join(PROJ, "plugin", "rokugan", "RokuganObjectives.sk"), encoding="utf-8").read()
        objs = [json.loads(s) for s in _re.findall(r'^\t(".*"),$', old, _re.M)]
        objs = [t for t in objs if not t.startswith("Chapter ")]      # (the order before the chapter cards)
    idx = {t: i for i, t in enumerate(objs)}

    def found(c):
        t = c.get("text") or ""
        if not isinstance(t, str):
            return None, None
        lv = _re.search(r"\(Recommended level (\d+)\)", t)
        i = t.find("Objective:")
        if i >= 0:
            s = t[i + len("Objective:"):].strip()
            return (s[:1].upper() + s[1:]) or None, lv
        if t.startswith("Next:"):
            return _re.sub(r"\s*\(Recommended level \d+\)", "", t[len("Next:"):]).strip(), lv
        # (user 2026-11-12: the Story box kept "back to the Wall / learn the kata" after the next chapter began) a
        # chapter card replaces the old objective with the chapter itself
        ch = _re.match(r"CHAPTER (\d+) - ([^(]+?)\.?\s*(\(|$)", t)
        if ch:
            return "Chapter %s: %s." % (ch.group(1), ch.group(2).strip().rstrip(".")), lv
        return None, lv

    def walk(x):
        if isinstance(x, dict):
            for v in list(x.values()):
                walk(v)
            return
        if not isinstance(x, list):
            return
        i = 0
        while i < len(x):
            c = x[i]
            if isinstance(c, dict) and c.get("cmd") == "cmd_showmsg":
                t, lv = found(c)
                sets = []
                if t:
                    if t not in idx:
                        idx[t] = len(objs)
                        objs.append(t)
                    sets.append({"cmd": "cmd_compute", "lvar": OBJ_VAR, "op": "=", "rvar": idx[t] + 1,   # 1-based:
                                 "desc": "RT objective"})                                          # 0 = none
                if lv:
                    sets.append({"cmd": "cmd_compute", "lvar": CH_LV_VAR, "op": "=", "rvar": int(lv.group(1)),
                                 "desc": "RT objective"})
                j = i + 1
                while j < len(x) and isinstance(x[j], dict) and x[j].get("desc") == "RT objective":
                    j += 1
                x[i + 1:j] = sets                                     # (re-runs replace the old setters)
                i += len(sets)
            else:
                walk(c)
            i += 1

    for mid in sorted(mp):
        if isinstance(mp[mid], dict):
            walk(mp[mid].get("event"))
    json.dump(objs, open(reg_path, "w", encoding="utf-8"), ensure_ascii=False, indent=0)
    out = os.path.join(PROJ, "plugin", "rokugan", "RokuganObjectives.sk")
    with open(out, "w", encoding="utf-8") as f:
        f.write("//\tGenerated by tools/gen_maps.py objective_pass (the field HUD's Story lines, by number = rpgvar %s).\n"
                % OBJ_VAR)
        f.write("::Rokugan.OBJECTIVES <- [\n")
        for t in objs:
            f.write("\t%s,\n" % json.dumps(t, ensure_ascii=False))
        f.write("];\n")
    print("objectives: %d (HUD list %s)" % (len(objs), out))


def free_engine(wait_s=3600):
    """The engine runs one instance at a time (a second exits with code 7), and the build needs it. Test instances
    (launched with -map / -battle / -rt...) are stopped; the user's own game (a plain -testplay) never is: the build
    waits until it is closed (user 2026-11-13: don't kill the user's game)."""
    import time
    t0, said = time.time(), False
    while True:
        out = subprocess.run(["powershell", "-NoProfile", "-Command",
                              "Get-CimInstance Win32_Process -Filter \"name='rpgcobo.exe'\" | "
                              "ForEach-Object { \"$($_.ProcessId)`t$($_.CommandLine)\" }"],
                             capture_output=True, text=True).stdout
        procs = [ln.split("\t", 1) for ln in out.splitlines() if "\t" in ln]
        if not procs:
            return
        users = [p for p, c in procs if not any(f in c for f in (" -map", " -battle", " -event", " -rt"))]
        for pid, cmd in procs:
            if pid not in users:
                subprocess.run(["taskkill", "/PID", pid, "/F"], capture_output=True)
        if not users:
            time.sleep(0.5)
            continue
        if not said:
            print("gen_maps: the game is open (PID %s) - waiting for it to close before building." % users[0])
            said = True
        if time.time() - t0 > wait_s:
            sys.exit("gen_maps: the game stayed open; build skipped.")
        time.sleep(5)


def build(specs):
    job = {"maps": [s.write() for s in specs]}
    jpath = os.path.join(JOBDIR, "job.json")
    json.dump(job, open(jpath, "w", encoding="utf-8"))
    free_engine()
    logp = os.path.join(JOBDIR, "build.log")
    import time
    with open(logp, "w", encoding="utf-8", errors="replace") as lf:
        proc = subprocess.Popen([os.path.join(TOOL, "rpgcobo.exe"), "-testplay", "-map", specs[0].mid, "[1,3,1,0]"],
                                cwd=TOOL, stdout=lf, stderr=subprocess.STDOUT)
        t0 = time.time()
        while time.time() - t0 < 180:
            time.sleep(1.0)
            txt = open(logp, encoding="utf-8", errors="replace").read()
            if "RTMAPGEN done" in txt or proc.poll() is not None:
                break
        subprocess.run(["taskkill", "/PID", str(proc.pid), "/F"], capture_output=True)
    os.remove(jpath)
    for line in open(logp, encoding="utf-8", errors="replace").read().splitlines():
        if "RTMAPGEN" in line:
            print(line)


ARENA_TREE_Z = (40, 76)            # battle camera: trees here stand in front of / among the fighters (z 64)
ARENA_BOX = (40, 90, 46, 74)       # x0, x1, z0, z1: no rocks either (party x 75, enemies x 56)


def clear_arena(m):
    """Battle backdrops: nothing tall between the battle camera and the fighters (user: "trees blocked view" in
    combat). Trees between the foreground and the road behind the arena go; rocks go from the arena itself."""
    keep = []
    for o in m.objs:
        if o["t"] == "fb" and o.get("fbtype") == 20:
            tall = o["fbparam"] not in (ROCK_S, ROCK_M)
            in_box = ARENA_BOX[0] <= o["x"] < ARENA_BOX[1] and ARENA_BOX[2] <= o["z"] < ARENA_BOX[3]
            if (tall and ARENA_TREE_Z[0] <= o["z"] < ARENA_TREE_Z[1]) or in_box:
                continue
        keep.append(o)
    m.objs = keep


# ---- Hireables (tools/hirelings.py; memory hireables): hire for zeni, or win Sumai to recruit for free. One at a
# time (G293 = number, G294 = charges). They follow on every field map and go home when the charges are spent.
import hirelings as _hire  # noqa: E402


def hire_join(h):
    lead = h.get("leader", "Natsuko")
    return [if_([{"lvar": "G293", "op": ">=", "rvar": 1}], [narrate("Your current hireling heads home.")]),
            setf("G293", h["n"]), setf("G294", h["charges"]), say(h["name"], h["joined"]),
            narrate("%s follows %s. (In battle: Support. %d uses, then home to %s.)" % (h["name"], lead, h["charges"],
                                                                                   h["home"]))]


def hire_npc(ev, x, z, h):
    """The hire spot: shown whenever this hireling isn't the one following Natsuko."""
    name, lead = h["name"], h.get("leader", "Natsuko")
    pay = [if_([{"lvar": "MONEY", "op": ">=", "rvar": h["price"]}],
               [{"cmd": "cmd_moneyop", "op": 1, "amount": h["price"]}] + hire_join(h),
               [say(name, "Coin first, %s-sama." % FULL_NAMES[lead].split()[0] if lead in FULL_NAMES
                     else "Coin first. Even heroes pay up front." if lead.startswith("the ")
                     else "Coin first, %s. Ronin pay up front." % lead)])]
    opts = [("Hire (%d zeni, %d uses)." % (h["price"], h["charges"]), pay)]
    if h.get("free_item"):                                       # Gonta: the Hidden Ones' Thanks pays once
        opts.insert(0, ("Call in the debt. (Free)", [
            if_([{"lvar": "NUM_" + h["free_item"], "op": ">=", "rvar": 1}],
                [{"cmd": "cmd_itemop", "itemid": h["free_item"], "op": 1, "num": 1, "LV": 1},
                 say(name, "Debt's a debt. Paid in full, Crab.")] + hire_join(h),
                [say(name, "We're square, Crab. Coin, or the belt.")])]))
    if h.get("charm"):                                           # Rensei's path action (chance; town standing)
        town = h["home"].replace("the ", "").split(" inn")[0]
        opts.append(("Charm to recruit (%d%%)." % h["charm"], [if_(
            [{"lvar": h["town"], "op": "<=", "rvar": 0}],
            [say(name, "Everybody's heard about the Crane with the speeches. No."),
             narrate("(%s has had enough. Make amends at the inn.)" % town)],
            [say("Rensei", h["charm_line"]),
             script("W = ::Rokugan.roll( %d);" % h["charm"]),
             if_([flag("W")], [say(name, h["won"])] + hire_join(h),
                 [say(name, h["taunt"]), setf(h["town"], 1, "-="),
                  narrate("(%s thinks a little less of the stiff young Crane.)" % town)])])]))
    elif h["sumai"]:
        won = [narrate("Natsuko takes the belt, drops her hips, and throws."), say(name, "...Fair's fair. I'll come.")] + hire_join(h)
        lost = [narrate("Natsuko goes for the belt and ends up in the dust."), say(name, h["taunt"])] + honor(-1)
        ask = say("Natsuko", "Wrestle me. If I win, you come for nothing.")
        opts.append(("Sumai match to recruit.", [ask] + sumai_match(name, SC[h["key"]], h["sumai"], won, lost)))
        opts.append(("Quick throw to recruit (%d%%)." % h["sumai"], [ask, script("W = ::Rokugan.roll( %d);" % h["sumai"]), if_([flag("W")], won, lost)]))
    elif h.get("leader", "Natsuko") == "Natsuko":
        opts.append(("Sumai to recruit.", [say("Natsuko", "Wrestle me."), say(name, h["refuse"])]))
    opts.append(("Leave.", []))
    ev.talk(x, z, SC[h["key"]], [(None, [say(name, h["hello"]), choices(*opts)])],
            reqs=[{"lvar": "G293", "op": "!=", "rvar": h["n"]}] + [flag(f, v) for f, v in h.get("reqs", [])])


def hire_followers(ev):
    for h in _hire.HIRELINGS:
        ev.follower(2, 2, SC[h["key"]], h["bark"], gap=1.4, reqs=[{"lvar": "G293", "op": "==", "rvar": h["n"]}])


_PARTY_MDL = {}


def party_npc_pass(ev):
    """(user 2026-11-14: "make sure NPCs do not spawn while they are already in the party") A map NPC drawn with a
    player character's model (villagers and talk-only events) stays away while that character is in the party (flag
    G1220 + number, plugin RokuganParty partyFlags). Hireling followers (G293) and scenes are left alone."""
    if not _PARTY_MDL:
        pl = json.load(open(os.path.join(PROJ, "data", "player.json"), encoding="utf-8"))
        for pid, p in pl.items():
            if isinstance(p, dict) and p.get("mdlid") and re.fullmatch(r"P1[0-4]\d", pid) and int(pid[1:]) <= 141:
                _PARTY_MDL.setdefault(p["mdlid"], pid)
        _PARTY_MDL.setdefault("-", None)
    for e in ev.ev.values():
        pid = _PARTY_MDL.get(e.get("mdlid"))
        if not pid or e.get("memo") == "barricade" or "G293" in json.dumps(e.get("reqs0")):
            continue
        role, pages = e.get("role"), e.get("page") or []
        if role != "villager" and not (role == "custom" and pages and all(pg.get("trigger") == 1 for pg in pages)):
            continue
        f = "G%d" % (1220 + int(pid[1:]))
        reqs = list(e.get("reqs0") or [])
        if not any(r.get("lvar") == f for r in reqs):
            e["reqs0"] = reqs + [flag(f, False)]


def cave_mounds(m, ev):
    """(user 2026-11-14: "caves should have a mound or something behind them") Every cave-mouth model outdoors (fb 3/21)
    gets a rocky mound behind it, rising in steps away from the mouth; level ground with nothing on it only."""
    taken = {(e["pos"][0], e["pos"][2]) for e in ev.ev.values() if "pos" in e}
    solid = set()
    for o in m.objs:
        if o["t"] == "fill":
            solid.update((o["x"] + a, o["z"] + b) for a in range(o["w"]) for b in range(o["d"]))
    for o in [o for o in m.objs if o["t"] == "fb" and o.get("fbtype") == 3 and o.get("fbparam") == 21]:
        cx, cz = o["x"], o["z"]
        h0 = int(m.hgt[cz, cx])
        for dz in range(1, 8):                                               # behind = further from the camera
            half = 6 - dz // 2
            for dx in range(-half, half + 1):
                x, z = cx + dx, cz + dz
                if not (0 <= x < m.w and 0 <= z < m.d) or (x, z) in taken or (x, z) in solid \
                        or int(m.hgt[z, x]) != h0 or (int(m.blk[z, x]) & 31) == 8 or int(m.blk[z, x]) == ROAD:
                    continue
                rise = min(dz + 2, 7) - abs(dx) // 3
                if rise > 0:
                    m.hgt[z, x] = h0 + rise
                    m.blk[z, x] = T(2, 0) if abs(dx) < half - 1 else T(2, 1)
        m.objs = [t for t in m.objs if not (t["t"] == "fb" and t.get("fbtype") == 20
                                             and cx - 6 <= t["x"] <= cx + 6 and cz + 1 <= t["z"] <= cz + 7)]


def make(i):
    if not DOOR_EV or ("M141", "castle") not in DOOR_EV:   # portals reference other maps' door ids
        wall_garrison()
        hoshi_town()
        kh_town()
    r = MAPS[i]()
    m, ev = r if isinstance(r, tuple) else (r, None)
    if ev is not None and "M100" <= i < "M800":
        for h in _hire.HIRELINGS:
            for mid, x, z in h["spots"]:
                if mid == i:
                    if i in ROOM_OFS:                                       # (tester 2026-11-11: the Shadow Hunter
                        x, z = x + ROOM_OFS[i][0], z + ROOM_OFS[i][1]       # stood outside M363) room -> map coords
                    hire_npc(ev, x, z, h)
        hire_followers(ev)
        gids = duel_gids()
        if gids:
            for k in list(ev.ev):
                ev.ev[k] = wrap_duels(ev.ev[k], gids)
        for x, z, n, d in getattr(ev, "inns", []):                         # Togashi Yosai (user: every path)
            raw, done = ev.pos(x, z, d), ev.ev["#%d#" % n]["pos"]             # interiors were already embedded:
            k = yosai_inn(ev, x + 2, z, i)                                  # shift him by the inn's own offset
            p = ev.ev["#%d#" % k]["pos"]
            ev.ev["#%d#" % k]["pos"] = [p[0] + done[0] - raw[0], p[1] + done[1] - raw[1], p[2] + done[2] - raw[2],
                                        p[3]]
    if ev is not None and i in FINALE_GATES:                                 # the road to the finale
        gx, gz = FINALE_GATES[i][:2]
        if i in ROOM_OFS:                                                   # interiors were already embedded:
            gx, gz = gx + ROOM_OFS[i][0], gz + ROOM_OFS[i][1]               # room coordinates -> map coordinates
        finale_gate(ev, gx, gz, *FINALE_GATES[i][2:])
        # (user 2026-11-12: "closed game again, i don't know where to go" - the gate was an invisible spot) a stone
        # marker you can see, a chevron to it, and the objective (once; also for saves made after the chapter)
        own, indoors = FINALE_GATES[i][2], FINALE_GATES[i][3]
        if not indoors and 0 <= gz + 1 < m.d:
            fb(m, gx, gz + 1, 3, 14)
        floor_arrows(m, type("E", (), {"ev": {"gate": {"role": "portal", "pos": [gx, 0, gz, 0]}}})())
        ev.scene(gx, gz - 2, "G1230", [narrate("Objective: the %s - the end of this road. There the next traveler's "
                                               "road begins; when all eight are walked, the finale." % (
                                                   "letter on the table" if indoors else "road-marker near here"))],
                 after=[flag(own)])
    if ev is not None and any(i in (q[3], q[9]) for q in SIDE_QUESTS):      # side-quest givers and hunts
        side_quest_events(m, ev, i)
    if ev is not None and any(i in (q[2], q[7]) for q in FETCH_QUESTS):    # Cakon odd jobs (Ronin Ch1)
        fetch_events(ev, i)
    if ev is not None and hasattr(m, "cave_floor"):
        _cave.sprawl(m, ev, i, (ROCK_S, ROCK_M), save_shrine)
    library_to_ours(m, ev, battle="M800" <= i < "M900")
    if ev is not None:
        fix_dark(ev.ev)
    if ev is not None and ("M100" <= i < "M800") and i not in INTERIORS and i not in ROOM_OFS:
        move_exits(m, ev, i)
        mark_exits(m, ev)
    if "M800" <= i < "M900":
        clear_arena(m)
    if ("M100" <= i < "M800" or i == "M099") and i not in INTERIORS and i not in ROOM_OFS:
        pad(m, ev)
        if ev is not None and getattr(m, "exits", None):
            edge_triggers(m, ev)
    if ev is not None and (i in INTERIORS or i in ROOM_OFS):
        floor_arrows(m, ev)
    elif ev is not None and "M100" <= i < "M800":
        # (user 2026-11-12: "need an indicator what tile to step on to get out of the kaiu tunnels and into the
        # shadowlands") caves: every exit inside the map; elsewhere: the invisible walk-on spots that move you on
        floor_arrows(m, ev, walkon_only=i not in CAVE_MAPS)
    if ev is not None:
        settle_floaters(m, ev)
    if ev is not None:
        portals_off_side_walls(m, ev)
        arrivals_face_open_ground(m, ev)
        people_off_blocks(m, ev)
    if ev is not None:
        party_npc_pass(ev)
    if ev is not None and "M100" <= i < "M800" and i not in CAVE_MAPS and i not in INTERIORS and i not in ROOM_OFS:
        cave_mounds(m, ev)
    if ev is not None and i in CAVE_MAPS:                                  # (user 2026-11-14) a full body's width to
        sys.modules.setdefault("gen_maps", sys.modules[__name__])          # every object in a cave (walkcheck.py)
        import walkcheck as _walk
        n = _walk.widen(m, ev)
        if n:
            print("   %s: widened %d cells (a full block to every object)" % (i, n))
    if ev is not None:                                                     # a big walk-in box whose centre can be
        for e in ev.ev.values():                                           # off screen while the player is in it
            r = (e.get("mdl") or {}).get("r") or []                        # would not exist there (spawndist 1)
            if len(r) == 6 and max(r[3], r[5]) >= 2.0 and e.get("spawndist", 1) == 1 and e.get("role") != "villager":
                e["spawndist"] = 5
    return m, ev


DEBUG_MAPS = {"M090", "M091", "M092", "M094"}                             # probes and catalogs: build by name only


def register_all():
    """Re-register every game map (all but DEBUG_MAPS) in map.json without rebuilding .bw files (called by gen_data.py)."""
    specs, events = [], {}
    for i in [k for k in MAPS if k not in DEBUG_MAPS]:
        m, ev = make(i)
        specs.append(m)
        events[m.mid] = ev
    register(specs, events)


def main():
    ids = sys.argv[1:] or [k for k in MAPS if k not in DEBUG_MAPS]
    specs, events = [], {}
    for i in ids:
        m, ev = make(i)
        specs.append(m)
        if ev:
            events[m.mid] = ev
    register(specs, events)
    build(specs)


if __name__ == "__main__":
    main()
